SELECT 'moj-all-verified-judgments-review-002-chunk-148' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"20900b20-9128-597b-aad5-1aa1bdcac7eb","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -اعتراف املتهمني على بعضهم جائز إذا لم يدفع الواحد منهم عن نفسه الضرر- إقرار بعض املتهمن دون البعض -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى .","document_number":"3436738","case_number":"33442161","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -اعتراف املتهمني على بعضهم جائز إذا لم يدفع الواحد منهم عن نفسه الضرر- إقرار بعض املتهمن دون البعض -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3436738 :‬‬\n                         ‫َر ْق ُم الدعوى‪33442161:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34221040‬تاريخه‪1434/5/25:‬هـ‬\n\n\n      ‫مطالبة برد مســروق ‪ -‬اشــتراك يف ســرقة من منزل ‪ -‬اعتراف املتهمني‬\n      ‫علــى بعضهــم جائــز إذا لــم يدفــع الواحــد منهــم عــن نفســه الضــرر‪-‬‬\n      ‫إقــرار بعــض املتهمــن دون البعــض‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار‬\n              ‫بحــق آلدمــي‪ -‬قبــول قــول املدعــي مــع ميينــه ‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n\n      ‫ادعى املدعي بأن املدعى عليهم اشــتركوا يف ســرقة ذهب ومجوهرات‬\n      ‫ومبالــغ ماليــة مــن منزلــه ؛ وطلــب إلزامهــم بإعــادة املســروقات أو تســليمه‬\n      ‫قيمتهــا ‪ -‬أنكــر املدعــى عليهــم دعــوى املدعــي جتاههــم جملــة وتفصيال‬\n      ‫‪ -‬املدعــى عليهــم لهــم إقــرارات مصدقــة شــرعا بالســرقة ‪ -‬مــن املقــرر‬\n      ‫شــرعا أن املــرء مؤاخــذ بإقــراره وأن اليمــن تشــرع يف جانــب أقــوى‬\n      ‫املتداعيــن ‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــي عليــه علــى‬\n      ‫صحــة دعــواه فأداهــا طبــق مــا طلــب منهــا ‪ -‬قضــت احملكمــة بإلــزام‬\n      ‫املدعــى عليهــم بتســليم املدعــي قيمــة املســروقات علــى أن تــوزع بينهــم‬\n      ‫بالتســاوي ولــكل واحــد منهــم الرجــوع علــى االخــر مبــا يعتقــد انــه اخــذ‬\n‫‪163‬‬\n\f‫زيــادة مــن قيمــة املســروقات ‪ -‬عــارض املدعــى عليهــم علــى احلكــم ‪-‬‬\n                  ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمة العامة باملدينة‬\n‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باملدينــة املنــورة برقــم ‪ 33442161‬وتاريــخ ‪1433/07/02‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331224190‬وتاريــخ ‪1433/6/30‬ه ـ حضــر‬\n‫‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى كل مــن ‪/‬‬\n‫ســعودي بالســجل املدني رقم ‪ /‬ســعودي بالســجل املدني رقم ‪ /‬ســعودي‬\n‫بالســجل املدنــي رقــم مبوجــب اإلقامــة رقــم قائــا بانهــم قامــوا بســرقة‬\n‫منزلــي الواقــع يف حــي الهجــرة عــن طريــق كســر األبــواب الرئيســية‬\n‫وأبــواب الغــرف اخلاصــة بغــرف النــوم وقامــوا بســرقة ذهــب تقــدر قيمتــه‬\n‫بأربعمائــة ألــف ريــال منهــا أربعــن جنيــه ذهــب ســعودي وســرقة مبلــغ‬\n‫مائــة وخمســة وســبعني ألــف ريــال نقــدا وكذلــك مبلــغ ســتة عشــر‬\n‫ألــف دوالر امريكــي ومنهــا ســرقة خــوامت ياقــوت واملــاس ذكــرى‬\n‫مــن الوالــد تقــدر قيمتهــا ســبعني ألــف ريــال وقيمــة إصــاح األبــواب‬\n‫التــي قامــوا بتكســيرها مبلــغ أربعــة االف ريــال اطلــب احلكــم عليهــم‬\n‫بإعــادة املســروقات او قيمتهــا التــي ذكرتهــا بدعــواي هكــذا ادعــى‬\n‫وقــد حضــر مــن املدعــى عليهــم الســجني املدعــو ‪ /‬وبســؤاله اإلجابــة‬\n‫علــى الدعــوى أجــاب قائــا بــان مــا ذكــره املدعــي غيــر صحيــح إطالقــا‬\n‫واملنــزل دخــل بــه ‪ /‬أمــا أنــا فقــد كنــت معهــم يف الســيارة ولــم اعلــم‬\n‫بانهــم يريــدون الســرقة وملــا نزلــوا مــن الســيارة بقيــت بالســيارة عندمــا‬\n\n                                                                                    ‫‪164‬‬\n\f      ‫خرجــوا باملســروقات وهــى عبــارة عــن شــنطة صغيــرة وشــنطة مكيــاج‬\n      ‫وبهــا علــب الذهــب وقــد تقاســموا املســروقات ببيــت ‪ /‬ولــم يعطونــي منهــا‬\n      ‫شــئيا وهــذا مثبــت يف محاضــر البحــث اجلنائــي هكــذا قــرر وإلحضــار‬\n      ‫بقيــة املتهمــن والرجــوع إلــى اوراق املعاملــة لرصــد مــا يوجــد بهــا مــن‬\n      ‫اثباتــات رفعــت اجللســة ثــم حضــر املدعــي وحضــر مــن املدعــى عليهــم‪/‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ /‬ســعودي بالســجل املدنــي رقــم وبتــاوة‬\n      ‫الدعــوى عليهمــا قــرر قائــا بــان مــا ذكــره املدعــي يف دعــواه غيــر‬\n      ‫صحيــح إطالقــا هكــذا قــرر وللرجــوع إلــى أوراق املعاملــة لرصــد مــا‬\n      ‫يوجــد بهــا مــن اثباتــات وإحضــار ‪ /‬رفعــت اجللســة ثــم حضــر املدعــي‬\n      ‫وحضــر مــن املدعــى عليهــم ‪ /‬ســعودي بالســجل املدنــي رقــم وبســؤال‬\n      ‫املدعــي قــرر قائــا بــان مــا جــاء بهــا غيــر صحيــح هكــذا قــرر وبالرجــوع‬\n                                ‫إلــى اعتــراف ‪ /‬وجــد هــذا نصــه ‪:‬ـ الثالــث عشــر ‪:‬‬\n      ‫يف إجــازة عيــد األضحــى املاضــي قمــت إنــا ومعــي كال مــن املدعــو‬\n      ‫‪ /‬واملدعــو ‪ /‬واملدعــو ‪ ....‬بســرقة فيــا مبخطــط ‪ ....‬خلــف مغاســل ‪....‬‬\n      ‫للســيارات حيــث ذكــرا لنــا املدعــو‪ /‬بــأن صديقتــه اإلندونيســية ‪....‬‬\n      ‫كانــت تعمــل مبشــغل مجــاور للفيــا وإنهــا تعــرف اخلادمــة املنزليــة التــي‬\n      ‫تعمــل بنفــس الفيــا وذكــرت لهــم اخلادمــة بأنهــم ســافروا إلــى محافظــة‬\n      ‫جــده وقــال بــأن ‪ ....‬تقــول إن الفيــا مليــان وفعــا اجتهنــا للفيــا وقــت‬\n      ‫أذان الفجــر بســيارتي ‪ ....‬ونزلنــا عنــد املغســلة مــن اخللــف ونقــز وفتــح‬\n      ‫البــاب ونــزل ومعــه عتلــة وراح وبعدهــا نزلــت أمــام الفيــا ورحــت بعيــد‬\n      ‫عــن الفيــا وكانــوا جميعهــم البســن قفــازات الف شــال علــى وجهــه‬\n      ‫داخــل احلــوش داخــل الفيــا وكان قلــق جــدا ويتصــل علــي كل دقيقــه‬\n      ‫ويذكــر بــان العيــال تأخــروا وبعــد حوالــي ســاعتني وأكثــر اتصــل وقــال‬\n\n\n‫‪165‬‬\n\f‫تعــاال عنــد البــاب ورحــت لهــم وخرجــوا مــن الفيــا وكانــا مــع كيــس‬\n‫كبيــرا بــه جميــع املســروقات واجتهنــا إلــى بيــت‪ /‬وقــام بتوزيــع الذهــب‬\n‫علــى حــده واالكسســورات علــى حــده وأعطانا منها طقــم ذهب وأعطى‬\n‫خــوامت وباقــي الذهــب وزعهــا أجــزاء اخلــوامت يف كيــس والبناجــر يف‬\n‫كيــس والسالســل يف كيــس ويف اليــوم التالــي طلعــت إنــا وزوجتــي يف‬\n‫ســيارتي حملافظــة جــده و وزوجتــه يف ســيارته حملافظــة جــده وتقابلنــا‬\n‫وســكنا يف فنــدق قريــب مــن ســوق ‪ ....‬وثانــي يــوم الصبــاح وذهبــت انــا‬\n‫وزوجــة‪ /‬إلــى الســوق لبيــع الذهــب وقامــت زوجــة ‪ /‬ببيــع الذهــب كامــا‬\n‫وال أعلــم كــم مبلــغ الذهــب الــذي باعتــه وأعطانــي نصيبــي تســعة أالف‬\n‫وأعطــى ‪ ....‬تســعة أالف نصيبــه حيــث طلــب ‪ ....‬مــن ‪ ....‬إن يعطــي املبلــغ‬\n‫ألخيــه ‪ .‬كمــا جــرى االطــاع علــى محضــر االســتدالل املذكــور وهــذا‬\n‫نصــه ‪ :‬الثالثــة عشــر ‪ :‬ثــم طلــب الســجني املذكــور التوجــه الــى مخطــط‬\n‫‪ ....‬وقــام بالداللــة واالرشــاد علــى احــدى الفلــل الواقعــة خلــف مغســلة ‪....‬‬\n‫واتضــح ان املنــزل عائــد للمدعــو‪ /‬وذكــر بــان الســرقة كانــت اثنــاء‬\n‫صــاة الفجــر قبــل شــهرين تقريبــا حيــث قامــت املــرأة‪ .... /‬اإلندونيســية‬\n‫بداللتهــم علــى املنــزل حيــث كانــت تعمــل يف الفلــة املجــاورة للفيــا‬\n‫املســروقة وقامــت باالتصــال علــى ‪ /‬وأشــارت لــه مــن فــوق الســطح علــى‬\n‫الفيــا العائــدة وذكــر بــأن املشــاركني لــه يف هــذه الســرقة كال مــن‬\n‫واملرأة ‪ .... /‬االندونيســية والتي قامت بداللتهم على املنزل وأن الســيارة‬\n‫املســتخدمة يف هــذه الســرقة هــي ‪ ....‬اللــون ابيــض ‪2006‬م مســتأجرة‬\n‫مــن مكتــب ‪ ....‬كمــا جــرى االطــاع علــى اعتــراف ‪ /‬وهــذا نصــه ‪:‬ـ‬\n‫‪ -44‬يف اجــازة عيــد االضحــى مــن عــام ‪1428‬ه ـ قمــت ومعــي ‪ /‬بالتوجــه‬\n‫علــى ســيارة مــن نــوع ‪ ....‬عائــده للمدعــو ‪ /‬وكان الوقــت حوالــي الســاعة‬\n\n\n                                                                                      ‫‪166‬‬\n\f      ‫ا وعندمــا وصلنــا للفيــا الواقعــة مبخطــط ‪ ....‬خلــف‬        ‫احلاديــة عشــر لي ـ ً‬\n      ‫ســوبر ماركــت ‪ ....‬قمــت بالنــزول مــن الســيارة وقمــت بالقفــز مــع ســور‬\n      ‫الفيــا بعــد أن قــام املدعــو ‪ /‬ومتكنــت مــن فتــح بــاب العمــارة اخلارجــي‬\n      ‫وبعــد ذلــك قــام بدخــول الفيــا وانــا ذهبــت وأوقفــت الســيارة بعيــد ًا عــن‬\n      ‫املنــزل ثــم عــدت لهــم ودخلــت املنــزل معهــم وكنــت أقــوم بــدور املراقبــة‬\n      ‫مــن حــوش العمــارة ومعــي ‪ /‬بينمــا قــام ‪ /‬بدخــول الفيــا ‪ .‬ومعهــم مفتــاح‬\n      ‫عجــل اســتخدموه بفــرز االبــواب الداخليــة للفيــا وبعــد نصــف ســاعة‬\n      ‫تقريب ـ ًا خــرج مــن الفيــا ومعهــم شــنطة دراســية صغيــرة بهــا مجموعــة‬\n      ‫مــن علــب املجوهــرات ومعهــم كذلــك كيــس ملــيء باملجوهــرات وبعــد‬\n      ‫ذلــك خرجنــا جميعــا مــن املنــزل وركبنــا الســيارة ‪ ....‬العائــدة وقامــوا‬\n      ‫بإنزالــي عنــد ســيارتي الواقعــة باجلــرف ولــم يعطونــي نصيبــي مــن هــذه‬\n      ‫الســرقة ‪ .‬كمــا جــرى االطــاع علــى محضــر االســتدالل ‪ ....‬املذكــور‬\n      ‫الــذي هــذا نصــه ‪ -1 :‬قــام املتهــم ‪ ....‬بالداللــة واإلرشــاد علــى منــزل يقــع‬\n      ‫مبخطــط ‪ ....‬خلــف أســواق ‪ ....‬واتضــح بــأن املنــزل للمدعــو ‪ /‬وقــد ذكــر‬\n      ‫املتهــم بــأن األشــخاص الذيــن شــاركوه يف الســرقة كال مــن املدعــو ‪/‬‬\n      ‫واملدعــو ‪ ./‬كمــا جــرى االطــاع علــى اعتــراف ‪ /‬وهــذا نصــه ‪-1 :‬قبــل‬\n      ‫شــهرين تقريبــا قمــت ومعــي كال مــن املدعــو ‪ /‬واملدعــو ‪ /‬واملدعــو ‪/‬‬\n      ‫بســرقة فيــا تقــع يف مخطــط ‪ ....‬حيــث توجهنــا الــى الفيــا علــى ســيارة‬\n      ‫مــن نــوع ‪ ....‬وكان ذلــك الســاعة الرابعــة فجــرا تقريبــا واذكــر انــه عنــد‬\n      ‫وصولنــا إلــى الفيــا قــام ‪ ....‬بالقفــز إلــى داخــل الفيــا وفتــح لنــا البــاب‬\n      ‫الرئيســي ثــم قمــت أنــا بدخــول الفيــا وكان‪ /‬يرتديــان قفــازات علــى‬\n      ‫أيديهــم ومعهــم كذلــك (عتلــه) وقــام بكســر البــاب الداخلــي للفيــا‬\n      ‫بواســطة العتلــة بينمــا كنــت أنــا أقــوم بــدور املراقبــة مــن داخــل حــوش‬\n\n\n‫‪167‬‬\n\f‫الفيــا وقــام بالدخــول الــى داخــل الفيــا وبعــد ســاعتني تقريبــا خــرج‬\n‫مــن داخــل الفيــا وكان يحمــل شــنطة كبيــرة ســوداء اللــون وكذلــك‬\n‫كيــس كان يحمــل شــنطة زرقــاء اللــون ثــم قــام باالتصــال علــى ‪/‬‬\n‫وطلــب منــه احضــار الســيارة امــام العمــارة وعنــد حضــور ‪ /‬خرجنــا‬\n‫مــن الفيــا وركبنــا مــع ومعنــا األكيــاس وتوجهنــا إلــى منــزل املدعــو‪/‬‬\n‫وقــام بإحضــار صحــن وســكب فيــه مــادة الكلوركــس وأخــذ يخــرج‬\n‫املجوهــرات قطعــة قطعــة ويقــوم بغمســها يف الكلوركــس ملعرفــة‬\n‫الذهــب مــن االكسســوار وقــام بتعبئــة الذهــب يف اربعــة اكيــاس‬\n‫(اكيــاس فحــم ) واتفقنــا ان يذهــب مــع ‪ /‬عائلتــه مــع ‪ /‬عائلتــه الــى‬\n‫جــدة لتصريــف الذهــب هنــاك وفعــا ذهبــا الــى هنــاك وقامــوا هنــاك‬\n‫بتصريــف الذهــب وبيعــه وبعــد اربعــة ايــام تقريبــا اتصــل علــي املدعــو‪/‬‬\n‫وقــال لــي لقــد بعــت الذهــب ونصيبــك مــن البيعــة تســعة االف ريــال‬\n‫(‪ )9000‬وفعــا قــام بإعطائــي هــذا املبلــغ ‪ .‬كمــا جــرى االطــاع علــى‬\n‫محضــر االســتدالل املذكــور الــذي هــذا نصــه ‪:‬ـ ‪/1‬قــام املذكــور‬\n‫بالداللــة علــى فيــا واقعــه مبخطــط ‪ .....‬خلــف مغســلة ‪ .....‬واتضــح بأنهــا‬\n‫فيــا املدعــو ‪ /‬والتــي تعرضــت للســرقة وقــام بالبالغ لدى مركز شــرطة‬\n‫قبــاء وذكــر املتهــم بــان الــذي شــاركه يف الســرقة كال مــن املدعــو ‪/‬‬\n‫واملدعــو ‪ /‬والــذي قــام بالداللــة علــى املنــزل املــرأة ‪ /‬إندونيســية اجلنســية‬\n‫‪.‬ا ‪0‬ه ـ ثــم ســألت عــن اعترافهــم املســجل شــرعا فقــررا كل واحــد منهما‬\n‫قائــا بــان مــا جــاء يف االعتــراف غيــر صحيــح هكــذا قــرر ثــم ســألت‬\n‫املدعــي مــا نــوع جنيــه الذهــب فقــرر قائــا بأنــه جنيــه ذهــب ســعودي‬\n‫ثــم قــرر قائــا باننــي قــد ذكــرت يف دعــواي أن قيمــة الذهــب اجمــاال‬\n‫مبلــغ اربعمائــة الــف ريــال ولكــن حصــل خطــأ يف الكتابــة ومســتعد‬\n\n\n                                                                                       ‫‪168‬‬\n\f      ‫باحللــف علــى صحــة مــا ادعيــت بــه هكــذا قــرر) ثــم ســألت املدعــي كــم‬\n      ‫تســاوي قيمــة اجلنيهــات الذهــب فقــرر قائــا بــان قيمــة جنيــه الذهــب‬\n      ‫يف ذلــك الوقــت تقــارب ســتمائة ريــال أمــا اآلن فهــو فــوق األلــف ريــال‬\n      ‫ســعودي وال مانــع لــدي مــن احتســاب قيمــة اجلنيهــات مبــا اشــتريته بــه‬\n      ‫تقريبــا وضمــه إلــي قيمــة الذهــب األخــرى ليصبــح اإلجمالــي اربعمائــة‬\n      ‫ألــف ريــال ســعودي هكــذا قــرر ثــم ســالته هــل يحلــف علــى صحــة مــا‬\n      ‫ادعــى بــه فقــال نعــم فعرضــت عليــه اليمــن التالــي نصهــا ( واهلل العظيــم‬\n      ‫ان منزلــي الواقــع يف مخطــط ‪ .....‬بجــوار صيدليــة ‪ .....‬تعــرض للســرقة‬\n      ‫وان قيمــة املســروقات هــي كمــا يلــي ذهــب تعــادل قيمتــه اربعمائــة ألــف‬\n      ‫ريــال ســعودي وكذلــك ســتة عشــر ألــف دوالر امريكــي ومبلــغ مائــه‬\n      ‫وخمســة وســبعني ألــف ريــال نقــدا وإصــاح االبــواب مــن الســرقة مببلــغ‬\n      ‫اربعــة االف ريــال واهلل العظيــم ) فحلفهــا علــى الوجــه املســطور بعاليــه‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وعلــى اعترافــات بعــض‬\n      ‫املدعــى عليهــم وكذلــك محاضــر االســتدالل وحيــث أن شــهادة بعــض‬\n      ‫املتهمــن علــى بعــض مقبولــة خاصــة وان املدعــى عليهــم يعتبــرون عصابــه‬\n      ‫مــع مجموعــة أخــرى حصــل منهــا ســرقات كثيــرة ممــا يــدل علــى صحــة‬\n      ‫الدعــوى اجتــاه اجلميــع وحيــث ان املدعــى قــد حلــف اليمــن الالزمــة‬\n      ‫لصحــة دعــواه لــذا كلــه فقــد ثبــت لــدي حصــول ســرقة بيــت املدعــي‬\n      ‫وتقــدر قيمــة املســروقات كمــا جــاء بدعــوى املدعــي لــذا كلــه فقــد‬\n      ‫الزمــت كل مــن ‪ /‬اجلنســية بدفــع مبلــغ خمســمائة وتســعة وســبعني الــف‬\n      ‫ريــال ســعودي وكذلــك ســتة عشــر الــف دوالر امريكــي للمدعــي تــوزع‬\n      ‫بينهــم بالتســاوي ولــكل واحــد منهــم الرجــوع علــى االخــر مبــا يعتقــد‬\n      ‫انــه أخــذ زيــادة مــن قيمــة املســروقات وبــه حكمــت وابلغــت كل مــن‬\n\n\n‫‪169‬‬\n\f‫ذلــك فقــرر كل واحــد منهــم عــدم القناعــة باحلكــم وجــرى تســليم كل‬\n‫واحــد منهمــا صــورة مــن صــك احلكــم لتقــدمي اعتراضــه عليــه يف مــدة‬\n‫ثالثــن يومــا وافهــم كل واحــد منهمــا بانــه اذا انتهــت مــدة االعتــراض‬\n‫ولــم يقــدم اعتراضــه فــان حقــه يف االعتــراض وطلــب االســتئناف يعتبــر‬\n‫ســاقطا فقــال كل واحــد منهمــا فهمــت ذلــك وامــرت ببعــث صــورة مــن‬\n‫صــك احلكــم إلــى الســجني ‪ /‬اجلنســية لتقــدمي اعتراضــه عليــه يف مــدة‬\n‫ثالثــن يومــا مــن تاريــخ اســتالمه لصــورة صــك احلكــم وصلــى اهلل علــى‬\n            ‫ســيدنا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/12‬ه ـ ‪.‬‬\n‫فبعــد رفــع صــك احلكــم رقــم ‪ 3436738‬يف ‪1434/2/13‬ه ـ املتعلــق‬\n‫بدعــوى ضــد ورفقــاه عــاد مصدق ـ ًا مــن محكمــة االســتئناف بقرارهــم‬\n‫رقــم ‪ 34221040‬يف ‪1434/5/25‬ه ـ وهــذا نصــه ‪ :‬احلمــد هلل والصــاة‬\n‫والســام علــى رســول اهلل وبعــد نحــن رئيــس وقضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى‬\n‫االطــاع منــا علــى الصــك رقــم ‪ 3436738‬يف ‪1434/2/13‬ه ـ الصــادر‬\n‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة باملدينــة املنــورة املتضمــن‬\n‫دعــوى املدعــي ضــد ورفقاه املتهمني بســرقة منــزل املدعي احملكوم فيه‬\n‫مبــا دون باطنــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه واللوائــح االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق ‪ .‬حــرر يف ‪1434/7/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":163,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3295af0928725240d778d208550811e506b300dbd8be69a9e73ddba41fa0cf45","normalized_text_hash":"925fb27b0b495aa6fe4d1f55dc0d7e4448725aa05ad4793ddb2404c4b1be782a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p163-3436738"},{"id":"66dcbc9f-3b3c-56b4-b932-2e63e4c49001","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -االقرار باستالم الذهب ومبلغ مالي مقابل املبالغ احملولة من حساب املدعي -احلكم بدفع املبلغ املدعى به -إفهام بالرجوع على من","document_number":"33451680","case_number":"33452309","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/13","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -االقرار باستالم الذهب ومبلغ مالي مقابل املبالغ احملولة من حساب املدعي -احلكم بدفع املبلغ املدعى به -إفهام بالرجوع على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33451680 :‬‬\n                           ‫َر ْق ُم الدعوى‪33452309:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3410255‬تاريخه‪1434/1/12:‬هـ‬\n\n\n       ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف ‪ -‬االقــرار‬\n       ‫باســتالم الذهــب ومبلــغ مالــي مقابــل املبالــغ احملولــة مــن حســاب‬\n       ‫املدعــي ‪ -‬احلكــم بدفــع املبلــغ املدعــى بــه ‪ -‬إفهــام بالرجــوع علــى مــن‬\n                                                                               ‫غــره ‪.‬‬\n\n\n\n\n       ‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــام بالتحايــل علــى موكلــه‬\n       ‫بانتحــال شــخصية موظــف يف أحــد املصــارف ثــم قــام بتحويــل مبالــغ‬\n       ‫ماليــة مــن حســابات موكلــه إلــى أحــد متاجــر الذهــب وقبــض مقابلهــا‬\n       ‫كميــة مــن الذهــب لصالــح نفســه ؛ ولــذا فقــد طلــب إلزامــه بتســليم‬\n       ‫موكلــه تلــك املبالــغ ‪ -‬أقــر املدعــى عليــه باســتالم الذهــب املذكــور‬\n       ‫يف الدعــوى وباقــي املبلــغ الــذي مت حتويلــه ودفــع بأنــه فعــل ذلــك لصالــح‬\n       ‫أحــد مرافقــي أخيــه بالســجن وأنــه ســلم الذهــب لشــخص آخــر بنــاء علــى‬\n       ‫طلبــه ولــم يكــن يعلــم بأنــه مت االحتيــال علــى املدعــي لســرقة مبالــغ‬\n       ‫ماليــة مــن حســاباته ‪ -‬املدعــى عليــه أقــر باســتالم الذهــب املذكــور‬\n\n‫‪171‬‬\n\f‫يف الدعــوى وباقــي املبلــغ الــذي مت حتويلــه ‪ -‬قضــت احملكمــة بإلــزام‬\n‫املدعــى عليــه بتســليم املدعــي أصالــة املبلــغ املدعــى بــه وإفهامــه بــأن لــه‬\n‫الرجــوع علــى مــن غــره إن كان صادق ـ ًا فيمــا ادعــاه ‪ -‬عــارض املدعــى‬\n‫عليــه علــى احلكــم‪ -‬قــررت محكمــة االســتئناف باألكثريــة املصادقــة‬\n                                                                    ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ حضــر حامــل‬\n‫الســجل املدنــي رقــم‪ :‬بالوكالــة عــن ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ 1001424843‬مبوجــب الوكالــة الصــادرة من كتابة عدل‬\n‫اخلبــراء ورياضهــا برقــم‪ 2844 :‬يف ‪1432/6/28‬ه ـ والتــي تخوله املطالبة‬\n‫واملرافعــة واملدافعــة واملخاصمــة وتقــدمي الدعــوى والبينــات‪ ،‬وســماع‬\n‫الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح‪ ،‬وقبــول احلكــم أو‬\n‫االعتــراض عليــه‪ ،‬وطلــب األميــان وســماعها‪ ،‬وادعــى علــى احلاضــر معــه‬\n‫حامــل الســجل املدنــي رقــم‪ ،..... :‬قائــا يف دعــواه‪ :‬لقــد اتصــل شــخص‬\n‫علــى وزعــم أنــه مديــر الســجالت بــإدارة مصــرف ‪ ...‬وطلــب منــه حتديــث‬\n‫حســاب والــده موكلــي فقــام باالتصــال علــى أخيــه وأعطــاه رقــم املتصــل‬\n‫فاتصــل عليــه ‪ ...‬فطلــب منــه صاحــب الرقــم حتديــث حســاب موكلــي‬\n‫فذهــب ‪ ...‬إلــى الصــراف اآللــي وقــام بعمــل اإلجــراءات التــي طلبهــا‬\n‫منــه املتصــل ويف ‪1432/5/13‬ه ـ تفاجــأ موكلــي بعــدة حــواالت متــت‬\n‫مــن حســاباته لــدى مصــرف ‪ ...‬إلــى عــدة حســابات منهــا حســاب ‪...‬‬\n‫صاحــب محــل ‪ ...‬للذهــب وهــي علــى النحــو التالــي ‪ :‬أربعــة وعشــرون‬\n\n                                                                                        ‫‪172‬‬\n\f      ‫ألــف ريــال مــن حســاب موكلــي رقــم ومبلــغ خمســن ألــف ريــال مــن‬\n      ‫حســاب موكلــي رقــم ومبلــغ خمســة وثمانــن ألــف ريــال مــن حســاب‬\n      ‫موكلــي رقــم ومبلــغ خمســة عشــر ألــف ريــال مــن حســاب موكلــي رقــم‬\n      ‫ومجموعهــا مائــة وأربعــة وســبعون ألــف ريــال ‪ ،‬وبســؤال عــن املبالــغ‬\n      ‫التــي حولــت إلــى حســابه ذكــر أن املدعــى عليــه حضــر إليــه واختــار‬\n      ‫عــدة أطقــم مــن الذهــب وأفــاده أن الثمــن ســوف يــرد إلــى حســابه وبعــد‬\n      ‫تأكــد صاحــب احملــل مــن دخــول املبلــغ إلــى حســابه قــام بتصويــر بطاقــة‬\n      ‫املدعــى عليــه وســلمه الذهــب وكان مببلــغ مائــة واثنــن وســبعني ألفــا‬\n      ‫وخمســمائة ريــال ورد للمدعــى عليــه الباقــي مــن مبلــغ احلــواالت وقــدره‬\n      ‫ألــف وخمســمائة ريــال ‪ ،‬وأطلــب إلــزام املدعــى عليــه بــأن يســلم ملوكلــي‬\n      ‫مائــة وأربعــة وســبعني ألــف ريــال هــذه دعــواي ‪ ،‬وباســتجواب املدعــى‬\n      ‫عليــه قــال ‪ :‬إن ابــن خالتــي كان مســجونا بســجن امللــز وكنــت أحضــر‬\n      ‫لــه أغراضــه التــي يحتــاج إليهــا فأخبرنــي أن معــه أحــد الســجناء اســمه‬\n      ‫فطلــب منــي أن أحضــر األغــراض التــي يحتاجهــا ثــم أصبــح يتواصــل‬\n      ‫معــي عــن طريــق اجلــوال وهــو يف الســجن وأقــوم بقضــاء حاجاتــه ويف أحد‬\n      ‫األيــام اتصــل علــي وطلــب منــي أن أقــوم بشــراء ذهــب وأن اســلمه ألخيــه‬\n      ‫فذهبــت إلــى ســوق ‪ ...‬ودخلــت إلــى أحــد محــات الذهــب فاتصــل وطلــب‬\n      ‫منــي أن أعطيــه صاحــب احملــل فأعطيتــه صاحب احملل وشــاهدت البائع‬\n      ‫يقــوم بإخــراج الذهــب ويضعــه علــى الطاولــة ثــم اتفــق معــه علــى الســعر‬\n      ‫وقــدره مائــة واثنــان وســبعون ألفــا وخمســمائة ريــال وبعــد أن نــزل الثمــن‬\n      ‫يف حســاب صاحــب احملــل أعطانــي صاحــب احملــل املبلــغ الزائــد من مبلغ‬\n      ‫احلــواالت وقــدره ألــف وخمســمائة ريــال ثــم حمــل الذهــب معــي وأركبــه‬\n      ‫يف شــنطة الســيارة ثــم اتصــل علــي ‪ ...‬وأدخلنــي يف مكاملــة جماعيــة مــع‬\n\n\n‫‪173‬‬\n\f‫شــخص آخــر وطلــب منــي أن أقــوم بتســليمه الذهــب وبالفعــل قابلتــه يف‬\n‫شــارع ‪ ...‬بحــي ‪ ...‬وكان يركــب ســيارة ‪ ...‬وارد ‪ ...‬وســلمته الذهــب‬\n‫ا وأعطانــي ثمانيــة آالف وخمســمائة ريــال حيــث إنــه بعــد شــرائي‬   ‫كامـ ً‬\n‫للذهــب قــال لــي بــأن لــي حــاوة ولــم أعلــم بأنــه ســوف يقــوم بإعطائــي‬\n‫هــذا املبلــغ ثــم تبــن لــي بعــد ســبعة أشــهر بعــد قبــض علــي أن املبالــغ‬\n‫التــي حولــت حلســاب صاحــب محــل الذهــب لــم تكــن مــن حســاب‪....‬‬\n‫وإمنــا كانــت مــن حســابات املدعــي أصالــة بطريقــة احتياليــة وال أدري‬\n‫كيــف متــت هــذه العمليــة ‪ ،‬هكــذا أجــاب ‪ ،‬وبعــرض ذلــك علــى املدعــي‬\n‫وكالــة قــال ‪ :‬إن أنكــر مــا ذكــره املدعــى عليــه واملدعــى عليــه هــو‬\n‫الــذي اســتلم الذهــب فأطلــب إلزامــه بتســليم املبلــغ هكــذا قــرر ‪ ،‬فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه أقــر بأنــه‬\n‫اســتلم الذهــب ومبلــغ ألــف وخمســمائة ريــال مقابــل املبالــغ احملولــة مــن‬\n‫حســابات املدعــي أصالــة لــذا فقــد حكمــت علــى املدعــى عليــه بــأن‬\n‫يســلم للمدعــي أصالــة مائــة وأربعــة وســبعني ألــف ريــال وأفهمتــه أن لــه‬\n‫الرجــوع علــى‪ ......‬إن كان صادقــا فيمــا ادعــاه ‪ ،‬وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر عــدم القناعــة بــه وطلــب االســتئناف فأجبتــه لطلبــه‬\n‫وقــررت تســليمه صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n‫خــال مــدة ال تتجــاوز ثالثــن يومــا فــإن تأخــر عــن ذلــك ســقط حقــه‬\n‫يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1433/11/13‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/05‬ه ـ‬\n‫فتحــت اجللســة الســاعة ‪ 10:45‬وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n\n\n                                                                                    ‫‪174‬‬\n\f      ‫وقــد همــش علــى ظهــر الصــك مبــا نصــه ( تظهيــرات الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف بالريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد‬\n      ‫اطلعنــا علــى هــذا القــرار رقــم ‪ 33451680‬وتاريــخ ‪1433/11/13‬ه ـ‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة بالريــاض الشــيخ ‪/‬‬\n      ‫وأصدرنــا القــرار رقــم ‪/3410255‬وتاريــخ ‪1434/01/12‬ه ـ املتضمــن‬\n      ‫أنــه لــم يظهــر لألكثريــة مــا يوجــب املالحظــة علــى احلكــم ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف د‪ .‬ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة لــي وجهــة نظــر ختمــه وتوقيعــه ) وكان ختــام‬\n      ‫هــذه اجللســة الســاعة ‪ 11:00‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n          ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/02/05‬ه ـ ‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":171,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a8bdb65bcd5106b7ae5c4d625b1dab27872e9cdccc9bb2aabf25db9951fc0358","normalized_text_hash":"f6c003156a804cf363d4ecd6e8e3902fefe12648963ccb76abb21c89566d2131","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p171-33451680"},{"id":"bce6d6ef-8a5e-568b-9f48-7738275803e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -نشل مبلغ مالي من اجليب -إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه برد املبلغ املسروق -تنفيذ","document_number":"3410162","case_number":"33532164","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"رد مسروق -نشل مبلغ مالي من اجليب -إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه برد املبلغ املسروق -تنفيذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410162 :‬‬\n                   ‫َر ْق ُم الدعوى‪33532164:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34197584‬تاريخه‪1434/4/24:‬هـ‬\n\n\n‫رد مســروق ‪ -‬نشــل مبلــغ مالــي مــن اجليــب ‪ -‬إثبــات بالقرائــن مــع‬\n‫ميــن املدعــي‪ -‬احلكــم بإلــزام املدعــى عليــه بــرد املبلــغ املســروق ‪ -‬تنفيــذ‬\n                                                                         ‫احلكــم ‪.‬‬\n\n\n\n\n                                ‫‪ -1‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n‫‪ -2‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة‬\n                                                        ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى احلاضــر معــه أنــه قــام بنشــل مبلــغ مالــي مــن جيبــه‬\n‫أثنــاء وجــوده يف ســوق األغنــام‪ ،‬وطلــب إلزامــه بإعــادة املبلــغ الــذي نشــله‬\n‫منــه ‪ -‬أنكــر املدعــى عليــه نشــل املبلــغ املذكــور أو مشــاهدة املدعــي يف‬\n‫ســوق األغنــام ‪ -‬املدعــى عليــه أديــن يف حكــم جزائــي ســابق بالشــروع‬\n‫يف نشــل أحــد األشــخاص بنفــس الســوق وعليــه ســابقتا ســرقة ونشــل‬\n‫مســجلة ‪ -‬املدعــي لــم يقــدم بينــة موصلــة تثبــت دعــواه إال أن جانبــه‬\n‫يتقــوى بالقرائــن املذكــورة يف أســباب احلكــم فتشــرع بحقــه اليمــن‬\n‫املكملــة ‪ -‬قضــت احملكمــة بنــاء علــى القرائــن وميــن املدعــي املكملــة‬\n‫بإلــزام املدعــى عليــه بإعــادة املبلــغ املدعــى بــه إلــى املدعــي‪ -‬قنــع املدعــي‬\n                                                                                          ‫‪176‬‬\n\f      ‫باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف‬\n                      ‫املوافقــة علــى احلكــم باألكثريــة ‪ -‬مت تنفيــذ احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمة العامة باملدينة‬\n      ‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة باملدينــة املنــورة برقــم ‪ 33532164‬وتاريــخ ‪ 1433/08/18‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331556500‬وتاريــخ ‪ 1433/08/18‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافــق‪ 1433/12/27‬ه ـ حضــر‪ ....../‬مصــري اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم‪ ....‬وأدعــى علــى احلاضــر معــه يف مجلــس احلكــم‬\n      ‫‪ ....../‬مبوجــب اإلقامــة البديلــة برقــم ‪.......‬بقولــه‪ :‬إننــي كنــت متواجــد ًا‬\n      ‫يف ســوق الغنــم باملدينــة بتاريــخ ‪1432/12/7‬ه ـ وكان بحوزتــي وبجيبــي‬\n      ‫األيســر مبلغـ ًا قــدرة واحــد وثالثــون الفـ ًا وخمســون ريــال مــن أجــل شــراء‬\n      ‫أضاحــي وفجــأة فقدتهــا فلتفــت جهــة اليســار فوجــدت هــذا احلاضــر‬\n      ‫املدعــى عليــه وســألته عــن املبلــغ فقــال مــا علــي فيــك فتقدمــت ببــاغ‬\n      ‫لشــرطة املطــار وبعــد حوالــي شــهر ونصــف مت أبالغــي مــن شــرطة‬\n      ‫املطــار بأنــه مت القبــض علــى نشــال يف ســوق الغنــم وطلبــوا منــي احلضــور‬\n      ‫للتأكــد منــه وملــا حضــرت عرضــوا علــي مجموعــة أشــخاص ومــن‬\n      ‫ضمنهــم املدعــى عليــه وال تــزال ذاكرتــي تعــرف املدعــى عليــه ويف‬\n      ‫احلــال أشــرت علــى املدعــى عليــه بأنــه هــو الــذي كان بجانبــي وال أدري‬\n      ‫مــاذا حصــل بعــد ذلــك وأخبرونــي بأنــه هــو الســارق ولــذا فاطلــب احلكــم‬\n      ‫عليــه بدفــع املبلــغ الــذي ســرقه وقــدرة واحــد وثالثــون الفــا وخمســون‬\n      ‫ريــال هكــذا قــرر دعــواه وبعرضــه علــى املدعــى عليــه أنكــر مــا ذكــره‬\n‫‪177‬‬\n\f‫املدعــي جملــة وتفصيــا وقــال أننــي لــم أســرق املبلــغ املذكــور مــن جيــب‬\n‫املدعــي ولــم أشــاهده يف ســوق الغنــم ومــا ذكــره أننــي ســرقت املبلــغ‬\n‫غيــر صحيــح هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى املعاملــة‬\n‫فوجدنــا مــن ضمــن لفاتهــا صــوره مــن القــرار الصــادر مــن احملكمــة‬\n‫اجلزائيــة برقــم ‪ 33202062‬يف ‪1433/4/20‬ه ـ املتضمــن دعــوى‬\n‫املدعــي العــام ضــد املدعــى عليــه مينــي اجلنســية مفادهــا أنــه بتاريــخ‬\n‫‪1432/12/7‬ه ـ تقــدم للجهــة االمنيــة املقيــم مصــري اجلنســية بتعرضــه‬\n‫للنشــل بســوق االغنــام صبــاح اخلميــس ‪1433/12/7‬ه ـ حيــث نشــل منــه‬\n‫مبلــغ قــدرة واحــد وثالثــون الفـ ًا وخمســون ريــال كان يف جنبــه االيســر‬\n‫كمــا أبلــغ املواطــن أنــه أثنــاء تواجــده بســوق األغنــام مــن أجــل شــراء‬\n‫أضاحــي كان بحوزتــه مبلــغ ســبعة وعشــرون ألــف ريــال وأثنــاء احلــراج‬\n‫انشــغل بذلــك ثــم لــم يجــد املبلــغ وبتاريــخ ‪1433/2/12‬ه ـ أبلــغ املواطــن‬\n‫عــن قيــام بإدخــال يــده بجيبــه االيســر مــن اجــل النشــل وعندمــا أحــس‬\n‫بــه قــام بالهــرب داخــل املســلخ وقــام بالتنكــر حيــث قــام برمــي مالبســه‬\n‫ومــن ثــم قــام باإلمســاك بــه وتســليمه الــى دوريــات االمــن وعثــر بحوزتــه‬\n‫علــى بطاقــة احــوال مدنيــة وبعرضــه علــى املدعــو ‪ ...‬أســتطاع التعــرف‬\n‫عليــه وانــه كان بجــواره عندمــا تعــرض للنشــل وباســتجواب املدعــى‬\n‫عليــه اعتــرف بانــه قــام بإدخــال يــده يف جيــب مــن أجــل النشــل وأنــه‬\n‫هــرب فتــم االمســاك بــه وأنتهــى التحقيــق باتهــام املدعــى عليــه بالشــروع‬\n‫يف نشــل أحــد االشــخاص ونشــل مبالــغ ماليــة قــدرة بثمانيــة وخمســون‬\n‫الــف ريــال مــن اشــخاص أخريــن علــى أوقــات متقاربــه كمــا تبــن وجــود‬\n‫ســابقتني عليــه احداهمــا ســرقه واالخــرى نشــل ‪ ....‬الــخ وخلــص حكــم‬\n‫فضيلتــه الــى أثبــات أدانــة املدعــى عليــه اجلنســية بالشــروع يف نشــل أحــد‬\n\n\n                                                                                    ‫‪178‬‬\n\f      ‫االشــخاص واســتعماله لهويــة وطنيــة وتوجــه التهمــه نحــوه مبــا نســب‬\n      ‫اليــه مــن نشــله ملبالــغ ماليــه قدرهــا ثمانيــة وخمســون الــف ريــال مــن‬\n      ‫أشــخاص أخريــن ولعــدم ارتداعــه مبــا ســبق لــه فقــد قــرر تعزيــره بســجنه‬\n      ‫ملــدة ســنه اعتبــارا مــن ‪1433/2/12‬ه ـ وبجلــده خمســة وســبعني جلــده‬\n      ‫تتكــرر عليــه عشــر مــرات ومــن ثــم أبعــاده الــى بــاده وحضــر عودتــه‬\n      ‫مــرة أخــرى وقــد قــرر املدعــى عليــه القناعــة بحكــم فضيلتــه يف حــن‬\n      ‫قــرر املدعــي العــام االعتــراض وصــدق القــرار مــن محكمــة االســتئناف‬\n      ‫مبكــة باألكثريــة برقــم ‪ 33240/495‬يف ‪1433/5/11‬ه ـ أ‪.‬ه ـ حيــث‬\n      ‫احلــال مــا ذكــر فقــد جــرى ســؤال املدعــي هــل لديــه زيــادة بينــه فقــال‬\n      ‫ليــس لــدي ســوى مــا جــاء يف نتيجــة التحقيــق هكــذا أجــاب ونظــر ًا لقــوة‬\n      ‫القرائــن ضــد املدعــى عليــه فقــد جــرى ســؤال املدعــي اليمــن الشــرعية‬\n      ‫علــى دعــواه فقــال أنــا أحلــف أنــه كان بجنبــي أثنــاء فقــد املبلــغ وحلظــة‬\n      ‫فقــد املبلــغ وســألته عــن املبلــغ ولكنــي لــم أســتطع القبــض عليــه حيــث‬\n      ‫كان يلبــس غتــرة حمــراء وعقــال وحســبته ســعودي ولذلــك لــم أســتطع‬\n      ‫القبــض عليــه وقــد تبــن مــن القضايــا االخــرى بانــه كان يلبــس هــذا‬\n      ‫اللبــس مــن اجــل التمويــه وأطلــب إمهالــي الــى االســبوع القــادم ورفعــت‬\n      ‫اجللســة ويف جلســة اخــرى حضــر الطرفــان وقــرر املدعــي اســتعداده‬\n      ‫بــأداء اليمــن علــى انــه حضــر لســوق الغنــم معــه املبلــغ املذكــور وانهــا‬\n      ‫فقــدت منــه وألول وهلــه ســأل املدعــى عليــه عــن املبلــغ وأن املدعــى عليــه‬\n      ‫الصــق النــاس بــه وانــه علــى يقــن مليــون باملائــة علــى ان املدعــى عليــه‬\n      ‫هــو الــذي ســرق املبلــغ املذكــور هكــذا قــرر وحيــث احلــال مــا ذكــر‬\n      ‫ا‬\n      ‫فقــد طلبــت مــن املدعــي اليمــن الشــرعية علــى ذلــك فحلــف قائ ـ ً‬\n      ‫واهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب والشــهادة أننــي حضــرت‬\n\n\n‫‪179‬‬\n\f‫لســوق الغنــم يف املدينــة يف ســبعة ذي احلجــة عــام ‪1432‬ه ـ ومعــي واحــد‬\n‫وثالثــون الفــا وخمســون ريــال ودخلــت الزحــام واملبلــغ معــي كان املدعــى‬\n‫عليــه هــذا احلاضــر اقــرب النــاس والصــق النــاس بــي وســألته حــال فقــد‬\n‫املبلــغ عــن املبلــغ وواهلل العظيــم انــه يف قــرارة نفســي مليــون باملائــة أن‬\n‫املدعــى عليــه هــو الــذي ســرق املبلــغ منــي واهلل علــى مــا أقــول شــهيد‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع‬\n‫علــى القــرار الشــرعي املشــار اليــه املصــدق مــن محكمــة االســتئناف‬\n‫مبكــة واملنصــوص فيــه بثبــوت أدانــة املدعــى عليــه بالشــروع يف نشــل‬\n‫احــد االشــخاص وتوجهــه التهمــة نحــوه بنشــل مبالــغ ماليــه مــن أشــخاص‬\n‫أخريــن واملشــار فيــه الــى بــاغ املدعــي عــن املدعــى عليــه بســرقة املبلــغ‬\n‫ومــا جــاء يف القــرار مــن وجــود ســابقتي ســرقة ونشــل علــى املدعــى عليــه‬\n‫وملــا جــاء يف نتيجــة التحقيــق مــع املدعــى عليــه لــدى هيئــة التحقيــق مــن‬\n‫اعترافــه مبحاولــة نشــل املجنــي عليــه وشــرائه بطاقــة احــوال وطنيــة‬\n‫والقبــض عليــه باجلــرم املشــهود مــن قبــل املدعــي املنــوه عنــه وتعــرف‬\n‫املجنــي عليــه عندمــا عــرض عليــه ووجــود البطاقــة املدنيــة بحوزتــه‬\n‫عنــد القبــض عليــه وتشــابه االســلوب االجرامــي لــه عــن قيامــه بالنشــل‬\n‫وتقــارب الوقــت بــن بــاغ بنفــس الســوق عنــد الداللــن أثنــاء احلــراج ومــا‬\n‫جــاء مــن عمــل التنكــر مــن املدعــى عليــه اثنــاء القبــض عليــه مــن رمــي‬\n‫مالبســه كل ذلــك ممــا يقــوي جانــب املدعــي وملــا قــرره احملققــون مــن‬\n‫ان اليمــن تشــرع يف جانــب اقــوى املتداعيــن وال ســيما مــع قــوة األدلــة‬\n‫وترادفهــا وتكاثرهــا وتشــابه اعمــال املدعــى عليــه وحيــث أدى املدعــي‬\n‫اليمــن الشــرعية بعاليــه فقــد حكمــت علــى املدعــى عليــه بدفــع املبلــغ‬\n‫املدعــى بــه وقــدره واحــد وثالثــون الفــا وخمســون ريــاال هــذا مــا حكمــت‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫بــه فليعلــم وبعرضــه علــى الطرفــن قــرر املدعــي القناعــة وامــا املدعــى‬\n      ‫عليــه فقــرر عــدم القناعــة وقــررت تســليمه صــورة مــن صــك احلكــم‬\n      ‫لتقــدمي االعتراضيــة حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1434/05/20‬ه ـ فقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة باخلطــاب‬\n      ‫رقــم‪ 332088894‬يف ‪ 1434/04/30‬ه ـ وبرفقهــا الصــك الصــادر منــا‬\n      ‫برقــم ‪ 3410162‬يف ‪ 1434/01/12‬ه ـ ومظهــر عليــه بالقــرار رقــم‬\n      ‫‪ 34197584‬يف ‪ 1434/04/24‬ه ـ الصــادر مــن الدائــرة اجلزائية الســابعة‬\n      ‫املتضمــن املوافقــة علــى احلكــم باألكثريــة واهلل املوفــق‪ .‬قاضــي‬\n      ‫اســتئناف ‪ ....‬لــي وجهــة نظــر ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه رئيــس اســتئناف د‪ .‬ختمــه وتوقيعــه ‪ .‬وصلــى اهلل وســلم علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــدة وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ‬\n      ‫حضــر لدينــا مصــري اجلنســية مبوجــب اإلقامــة رقــم باملجلــس الشــرعي‬\n      ‫وقــرر لدينــا بأنــه اســتلم الشــيك رقــم ‪ 005201‬يف ‪1434/7/5‬ه ـ‬\n      ‫املســحوب علــى مصــرف ‪ ...‬مببلــغ وقــدرة واحــد وثالثــون ألفـ ًا وخمســون‬\n      ‫ريــال وهــو كامــل املبلــغ املدعــى بــه وبذلــك تكــون القضيــة منتهيــة لــذا‬\n      ‫جــرى إثباتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":176,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"471f7854724b8311add7acaf68aa58920aea450c7598f8084a425ca5ef0f2594","normalized_text_hash":"fa0cbbefd8d9811be4b9e8554e4918eb6c2802973907fefdd5f2576374741298","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p176-3410162"},{"id":"3f2cf1b6-f417-5bed-9ccb-5fd4a82c3d2f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -تفويض -اجلهات احلكومية يكتفي بالتفويض بخطاب رسمي من صاحب الصالحية -سرقة مستلزمات كهربائية من املال العام -إنكار ملقدار املسروق -بينة غير موصلة -رد مين املدعى عليه على نفي عدد القطع املسروقة -قبول قول الغارم مع ميينه -تفويض يف املرافعة واملخاصمة من صاحب الصالحية -احلكم بإلزام املدعى عليه بدفع قيمة القطع املسروقة الواردة يف معاملة االدعاء العام -رد الدعوى يف غير ذلك.","document_number":"33411618","case_number":"33544297","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/13","year":"1434","subject":"رد مسروق -تفويض -اجلهات احلكومية يكتفي بالتفويض بخطاب رسمي من صاحب الصالحية -سرقة مستلزمات كهربائية من املال العام -إنكار ملقدار املسروق -بينة غير موصلة -رد مين املدعى عليه على نفي عدد القطع املسروقة -قبول قول الغارم مع ميينه -تفويض يف املرافعة واملخاصمة من صاحب الصالحية -احلكم بإلزام املدعى عليه بدفع قيمة القطع املسروقة الواردة يف معاملة االدعاء العام -رد الدعوى يف غير ذلك.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33411618 :‬‬\n                    ‫َر ْق ُم الدعوى‪33544297:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34290573‬تاريخه‪1434/8/7:‬هـ‬\n\n\n‫رد مســروق ‪ -‬تفويض ‪ -‬اجلهات احلكومية يكتفي بالتفويض بخطاب‬\n‫رســمي مــن صاحــب الصالحيــة ‪ -‬ســرقة مســتلزمات كهربائيــة مــن‬\n‫املــال العــام ‪ -‬إنــكار ملقــدار املســروق‪ -‬بينــة غيــر موصلــة‪ -‬رد ميــن املدعــى‬\n‫عليــه علــى نفــي عــدد القطــع املســروقة ‪ -‬قبــول قــول الغــارم مــع ميينــه‬\n‫‪ -‬تفويــض يف املرافعــة واملخاصمــة مــن صاحــب الصالحيــة ‪ -‬احلكــم‬\n‫بإلــزام املدعــى عليــه بدفــع قيمــة القطــع املســروقة الــواردة يف معاملــة‬\n                                 ‫االدعــاء العــام ‪ -‬رد الدعــوى يف غيــر ذلــك‪.‬‬\n\n\n\n\n                                    ‫املادة (‪ )6/47‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت اجلهــة املدعيــة وميثلهــا املفــوض بالترافــع عنهــا بــأن املدعــى عليــه‬\n‫قــام بســرقة عــدد مــن القواطــع الكهربائيــة؛ وطلبــت إلزامــه بتســليمها‬\n‫قيمــة املســروقات ‪ -‬أقــر املدعــى عليــه بســرقة القواطــع الكهربائيــة إال‬\n‫أنــه أنكــر مقــدار املســروقات املذكــورة يف الدعــوى كمــا دفــع بأنهــا‬\n‫تالفــة فظــن بأنــه ال حاجــة لهــا ‪ -‬املدعيــة قدمــت بينــات غيــر موصلــة‬\n‫فيمــا يتعلــق مبقــدار املســروقات‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه‬\n\n                                                                                        ‫‪182‬‬\n\f      ‫بتســليم املدعيــة قيمــة املســروقات التــي أقــر بهــا كمــا قضــت بــرد دعوى‬\n      ‫املدعيــة فيمــا زاد علــى ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم وعارضــت‬\n      ‫عليــه املدعيــة ‪ -‬قــررت محكمــة االســتئناف باألكثريــة املوافقــة علــى‬\n                                                                          ‫احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة الرئيــس برقــم‬\n      ‫‪ 33544297‬وتاريــخ ‪1433/08/25‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 331498271‬وتاريــخ ‪ 1433/08/10‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n      ‫‪1433/08/28‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة صباح ـ ًا‬\n      ‫ا‬ ‫وفيهــا حضــر ســعودي بالســجل املدنــي رقــم ‪ ...‬حــال كونــه وكي ـ ً‬\n      ‫مبوجــب خطــاب تفويــض مــن مشــرف قصــور رقــم ‪/582‬ق ص‪/‬م وتاريــخ‬\n      ‫ا ضــد احلاضــر معــه يف مجلــس احلكــم‬      ‫‪1433/08/11‬ه ـ وادعــى قائ ـ ً‬\n      ‫ا يف تقريــر دعــواه ضــده ‪ :‬إن املدعــى‬ ‫ســعودي بالســجل املدنــي ‪ ...‬قائ ـ ً‬\n      ‫عليــه قــام بتاريــخ ‪1432/11/14‬ه ـ بســرقة قطع نحاســية عددها (‪)393‬‬\n      ‫قطعــة وذلــك مــن قصــر مبكــة املكرمــة وذلــك بعــد قيامــه بقــص قفــل‬\n      ‫البــاب اخلارجــي ملســتودع القصــر وقــد مت تقديــر جميــع القطــع املســروقة‬\n      ‫مببلــغ وقــدره (‪ 30654‬ثالثــون ألــف وســتمائة وأربــع وخمســون ريــال) لــذا‬\n      ‫؛ أطلــب احلكــم علــى املدعــى عليــه وإلزامــه بدفع قيمة القطع النحاســية‬\n      ‫املســروقة وهــو مبلــغ وقــدره (‪ 30654‬ثالثــون ألــف وســتمائة وأربــع‬\n      ‫وخمســون ريــال) هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫بقولــه ‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه مــن ناحيــة ســرقة القطــع‬\n‫‪183‬‬\n\f‫وعددهــا املذكــور يف دعــواه كلــه غيــر صحيح والصحيح أني شــاهدت‬\n‫عــدد مــن املواســير النحاســية التالفــة بجــوار املســتودع وتولــد لــدي‬\n‫إحســاس بأنــه ليــس هنــاك حاجــة لتلــك املواســير وعليــه فقــد قمــت‬\n‫بتحميلهــا داخــل شــنطتي وعددهــا تســعة وثالثــن ماســورة نحاســية وقــد‬\n‫بعتهــا مببلــغ ثالثــة آالف وســبعمائة ريــال ‪ ،‬ومســتعد بإعــادة هــذا املبلــغ‬\n‫هكــذا أجــاب وبســؤال املدعــي وكالــة عــن بينتــه علــى دعــواه فقــال ‪:‬‬\n‫بينتــي هــي مــا يف أوراق املعاملــة املتعلقــة باحلــق العــام ‪ .‬عنــد ذلــك جــرى‬\n‫منــي االطــاع علــى املعاملــة وفيهــا القــرار الشــرعي الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 3383574‬وتاريــخ ‪1433/02/15‬ه ـ واملتضمــن ثبــوت‬\n‫إدانــة املدعــى عليــه بخيانــة األمانــة وأخــذ مــال مؤمتــن عليــه بغيــر وجــه‬\n‫حــق وتعزيــره لقــاء ذلــك بســجنه ســنة وجلــده مائــة وخمســون جلــده كمــا‬\n‫جــرى منــي الرجــوع إلــى أوراق املعاملــة فوجــد مــن بينهــا محضــر القبــض‬\n‫والتفتيــش احملــرر علــى لفــة رقــم ‪ 15‬ولفــه رقــم ‪ 16‬فوجــد أنــه يتضمــن‬\n‫القبــض علــى املدعــى عليــه نظــر ًا ملــا توفــرت مــن معلومــات تفيــد اتهامــه‬\n‫بســرقة قواطــع كهربائيــة نحاســية ولــم جنــد يف احملضــر مــا يفيــد وجود‬\n‫شــيء مــن املســروقات لديــه كمــا جــرى منــي الرجــوع إلــى أوراق املعاملــة‬\n‫ومــن بينهــا إقــرار املدعــى عليــه املــدون علــى صحيفــة ‪ 15‬مــن دفتــر‬\n‫التحقيــق لفــة رقــم ‪ 1‬وهــذا نصــه ‪ (( :‬إقــرار بتاريــخ ‪1432/11/27‬ه ـ‬\n‫أقــر أنــا املدعــو ‪ /‬ســعودي اجلنســية حامــل بطاقــة رقــم وأنــا بكامــل‬\n‫قــواي العقليــة املعتبــرة شــرع ًا وبــدون إجبــار أو اكــراه يف يــوم األربعــاء‬\n‫أو الثالثــاء ويف متــام الســاعة احلاديــة عشــر صباحـ ًا دخلــت املســتودع مــن‬\n‫بــاب الطــوارئ مــن النفــق رقــم أربعــة لكــي أقــوم بترتيــب األبجــورات‬\n‫بداخــل املســتودع بواقــع عمــل كفنــي كهربــاء وشــاهدت القواطــع‬\n\n\n                                                                                       ‫‪184‬‬\n\f      ‫النحاســية ونقلتهــا مبعرفتــي إلــى مــكان قريــب مــن بــاب الطــوارئ الذي‬\n      ‫دخلــت منــه وكنــت أتــردد يوميـ ًا ألشــاهد القواطــع هــل هــي يف مكانهــا‬\n      ‫الــذي وضعتــه بهــا وبواقــع تــرددي علــى القواطــع لــم أتوقــع أحــد اهتــم‬\n      ‫للقواطــع فأغوانــي الشــيطان فقمــت بنقلهــا بيــدي ووضعتهــا يف شــنطة‬\n      ‫الســيارة وعددهــا تســعة وثالثــن قطعــة مــن النحــاس وحملتهــا دفعــة‬\n      ‫واحــدة وعنــد خروجــي مــن القصــر لــم يقــم أحــد بتفتيشــي كمــا هــو‬\n      ‫ـاء وبعــد‬‫معتــاد وخرجــت يف متــام الســاعة الثانيــة عشــر والربــع مسـ ً‬\n      ‫خروجــي مــن القصــر شــاهدت شــخص مــن الذيــن يشــترون علــب‬\n      ‫البيبســي واملعلبــات يف مخطــط احلمــراء وال أعرفــه أبــد ًا وعرضتهــا عليــه‬\n      ‫ووافــق علــى شــرائها مقابــل ثالثــة آالف وســبعمائة ريــال وبعتهــا لــه هــذا‬\n      ‫مــا حــدث بالتفصيــل وعلــى ذلــك أقــر علم ـ ًا أن املســتودع الــذي دخلــت‬\n      ‫وســرقت القواطــع النحاســية منــه يقــع بقصــر ‪ ....‬مبكــة الــذي أعمــل‬\n      ‫فيــه فنــي كهربــاء وعليــه أوقــع املقــر مبــا فيــه بصمتــه شــهود احلــال‬\n      ‫املــازم توقيعــه)) وقــد ذيــل عليــه مبــا نصــه ‪ (( :‬احلمــد هلل وحــده وبعــد ‪:‬‬\n      ‫حضــر لــدي املدعــو وبســؤاله عــن املدعــو بالصحيفــة رقــم ‪15‬صــادق‬\n      ‫عليه حرفي ًا طائع ًا مختار ًا ولذا جرى تصديقه حرر يف ‪1432/11/28‬هـ‬\n      ‫املقــر مبــا فيــه بصمتــه رئيــس احملكمــة اجلزئيــة مبكــة املكرمــة‬\n      ‫توقيعــه )) )) وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا جــاء يف‬\n      ‫ذلــك صحيــح وليــس فيهــا مــا يــدل علــى دعــوى املدعــي وكالــة وبســؤال‬\n      ‫املدعــي وكالــة هــل لديــه زيــادة بينة ســوى مــا يف أوراق املعاملة ؟ فأجاب‬\n      ‫بأنــي أطلــب مهلــة للبحــث وحيــث ال مانــع مــن ذلــك رفعــت اجللســة ثــم يف‬\n      ‫يــوم األربعــاء املوافــق ‪1433/09/06‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫الثانيــة ظهــر ًا وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه املنــوه عنهمــا‬\n\n\n‫‪185‬‬\n\f‫بعاليــه وبســؤال املدعــي وكالــة عمــا وعــد بــه يف اجللســة املاضيــة مــن‬\n‫احضــار البينــة فأجــاب بقولــه ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬\n‫مــن اعتــراف املدعــى عليــه بدخــول املســتودع ‪ ،‬كمــا أن املدعــى عليــه‬\n‫ليــس لــه أيــه صالحيــة لدخــول املســتودع ‪ ،‬واعترافــه بســرقة بعــض‬\n‫القطــع دليــل علــى ســرقة باقيهــا هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال ‪ :‬الصحيــح مــا ذكرتــه ومــا أخذتــه مــن املواســير فهــي‬\n‫تالفــة وهــي مرميــة يف صناديــق النفايــات وأطالــب بإحضــار تصويــر ذلــك‬\n‫بالكاميــرات إن كانــت الدعــوى صحيحــة وبعرضــه علــى املدعــي‬\n‫أجــاب بأنــه ال صحــة ملــا ذكــره املدعــى عليــه ومــا يكــون تالف ـ ًا فإنــه‬\n‫يشــكل لــه جلنــة لتقريــر ذلــك ومن ثــم يباع عن طريــق مناقصة حكومية‬\n‫وأمــا مــا ذكــره مــن تصويــر ذلــك بالكاميــرات فإنــه ال يوجــد لدينــا‬\n‫حاليـ ًا تصويــر لذلــك هكــذا اجــاب ثــم قــرر كل منهمــا اكتفــاؤه مبــا‬\n‫قــدم وعليــه فقــد قــررت رفــع اجللســة للتأمــل ودراســة املعاملــة ثــم يف يــوم‬\n‫األربعــاء املوافــق ‪1433/09/13‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n‫الواحــدة ظهــر ًا وفيهــا حضــر ممثــل اجلهــة املدعيــة واملدعــى عليــه ‪ ...‬املنــوه‬\n‫عنهمــا بعاليــه وبســؤال املدعــى عليــه عــن عــدد القطــع التــي أخذهــا ؟‬\n‫أجــاب إنهــا تســعة وثالثــون ماســورة نحاســية‪ ،‬فبنــاء علــى مــا ســلف مــن‬\n‫الدعــوى واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا القــرار‬\n‫الشــرعي رقــم ‪ 3383574‬وتاريــخ ‪1433/02/15‬ه ـ ‪ ،‬وحيــث طلبــت‬\n‫اجلهــة املدعيــة بواســطة ممثلهــا تكليــف املدعــى عليــه بدفــع قيمــة‬\n‫املســروق وعــدده (‪ )393‬قطعــة نحاســية باملبلــغ املدعــى عليــه ‪ ،‬وحيــث‬\n‫أنكــر املدعــى عليــه عــدد القطــع املســروقة وذكــر أنهــا تســع وثالثــن‬\n‫ماســورة نحاســية ‪ ،‬ولــم يقــم املدعــي بينتــه علــى دعــواه يف عــدد القطــع‬\n\n\n                                                                                          ‫‪186‬‬\n\f      ‫‪ ،‬ومــا جــاء يف القــرار الشــرعي واالقــرار املصــدق شــرع ًا ‪ ،‬ال تــدل علــى‬\n      ‫مــا ذكــره ممثــل اجلهــة املدعيــة يف دعــواه ‪ ،‬ولــم يرغــب ميــن املدعــى‬\n      ‫عليــه علــى نفــي مــا زاد عــن القطــع املقــر بهــا ‪ ،‬وحيــث أن مــا أقــر بــه‬\n      ‫املدعــى عليــه مــن عــدد القطــع وقيمتهــا يفــوق مــا قومــت بــه اجلهــة املدعيــة‬\n      ‫كل قطعــة مــن القطــع النحاســية ‪ ،‬ملــا ســبق فقــد حكمــت مبــا يلــي ‪:‬‬\n      ‫أو ًال ‪ :‬ثبــت لــدي أن بذمــة املدعــى عليــه للشــؤون اخلاصــة ل ـ ـ ‪ ....‬مبلــغ‬\n      ‫وقدره (‪ 3700‬ثالثة آالف وســبعمائة ريال ) قيمة تســع وثالثون ماســورة‬\n      ‫نحاســية أخذهــا بغيــر وجــه حــق ‪ ،‬تــودع يف اخلزينــة العــام للدولــة لصالــح‬\n      ‫الشــؤون اخلاصــة لـ ــ‪ . ....‬ثانيـ ًا ‪ -:‬رددت دعــوى اجلهــة املدعيــة ‪ ...‬يف إلــزام‬\n      ‫املدعــى عليــه مبــا زاد علــى القطــع املذكــورة ‪ ،‬لكونــه لــم يثبــت لــدي‬\n      ‫وأفهمــت ممثلهــا بــأن للجهــة املدعيــة ميــن املدعــى عليــه متــى رغبــت هــذا‬\n      ‫مــا ظهــر لــي وبــه حكمــت وبإعــان احلكــم قــرر املدعــى عليــه القناعــة‬\n      ‫وقــرر ممثــل اجلهــة املدعيــة عدمهــا وطلــب اســتئنافه بالئحــة فجــرى‬\n      ‫تســليمه نســخه مــن الصــك يف نفــس اليــوم وإفهامــه بــأن مــدة االعتــراض‬\n      ‫ثالثــون يومـ ًا اعتبــار ًا مــن تاريــخ هــذا اليــوم وبأنــه إذا لــم يتقــدم بالئحــة‬\n      ‫اعتراضيــة خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم‬\n      ‫القطعيــة ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد آلــه وســلم حــرر‬\n      ‫يف ‪1433/09/13‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال‬\n      ‫نبــي بعــده وبعــد ‪ :‬ففــي هــذا اليــوم األحــد املوافــق ‪1434/03/29‬ه ـ‬\n      ‫افتتحــت اجللســة وكان قــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 331873432‬يف ‪1433/11/15‬ه ـ واملالحــظ عليها بقرار الدائرة‬\n      ‫اجلزائيــة األولــى رقــم ‪ 33447901‬يف ‪1433/11/08‬ه ـ ونــص احلاجــة‬\n      ‫منــه ‪ (( :‬وبدراســة احلكــم وصــورة ضبطــه قررنــا إعادتهــا لفضيلــة‬\n\n\n‫‪187‬‬\n\f‫حاكــم القضيــة ملالحظــة انــه ال توجــد وكالــة مــن اجلهــة املختصــة وإمنــا‬\n‫ملوجــود تفويــض يف املراجعــة وليــس يف الدعــوى واملرافعــة وال بــد مــن‬\n‫ذلــك ‪ .‬إلجــراء مــا يلــزم نحــو مــا أشــير إليــه )) ‪ ،‬وعليــه أجيــب أصحــاب‬\n‫الفضيلــة بأنــه كمــا نــوه يف ضبطــه فــإن اجلهــة املختصــة قــد فوضــت ‪/‬‬\n‫يف املطالبــة واملدافعــة واملرافعــة وقبــول احلكــم واالعتــراض عليــه ‪..‬الــخ‬\n‫مبوجــب خطابهــم رقــم ‪ /582‬ق ص ‪ /‬م يف ‪1433/08/11‬ه ـ املرفــق‬\n‫باملعاملــة ‪ ،‬وحيــث جــرى إكمــال الــازم فقــد قــررت رفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق حــرر يف‬\n‫‪1434/03/29‬ه ـ ‪.‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء‬\n‫املوافــق ‪1434/05/07‬ه ـ افتتحــت اجللســة يف متــام الســاعة الثامنــة‬\n‫صباح ـ ًا ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫رقــم ‪ 332028985‬وتاريــخ ‪1434/04/27‬ه ـ واملرفــق بهــا القــرار رقــم‬\n‫‪ 34189158‬وتاريــخ ‪1434/04/16‬ه ـ ونصــه « وبدراســة مــا أجــاب بــه‬\n‫فضيلتــه غيــر مقنــع وعليــه الرجــوع إلــى قرارنــا رقــم ‪ 33447901‬وتاريــخ‬\n‫‪1433/11/08‬ه ـ وإجــراء مــا يلــزم واهلل املوفــق « أ‪.‬ه ـ وعليــه أجيــب‬\n‫أصحــاب الفضيلــة ‪ -‬وفقهــم اهلل وأيدهــم ‪ ،‬بأنــه هــذه الدعــوى مقامــة‬\n‫مــن جهــة حكوميــة هــي ‪ ، ...‬واملدعــي احلاضــر هــو مفــوض مــن قبــل‬\n‫صاحــب الصالحيــة باخلطــاب املوجــه للمحكمــة برقــم ‪/582‬ق ص‪/‬م‬\n‫يف ‪1433/08/11‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪ )26‬وقــد جــاء فيــه مــا‬\n‫نصــه ‪ (( :‬ولــه احلــق يف املطالبــة واملخاصمــة واملدافعــة واملرافعــة وإحضار‬\n‫البينــات والــرد عليهــا وقبــول احلكــم واالعتــراض عليــه والتوقيــع فيمــا‬\n‫ذكــر )) ‪ ،‬وحيــث أن هــذا التفويــض كافي ـ ًا يف مثــل هــذه احلالــة وال‬\n‫حاجــة إلصــدار وكالــة فقــد نصــت املــادة (‪ )6/47‬مــن نظــام املرافعــات‬\n\n\n                                                                                    ‫‪188‬‬\n\f      ‫الشــرعية علــى أن ‪ (( :‬ممثلــوا اجلهــات احلكوميــة يكتفــى بتفويضهــم‬\n      ‫بخطــاب رســمي مــن صاحــب الصالحيــة إلــى احملكمــة التــي تقــام لديها‬\n      ‫الدعــوى )) ‪ ،‬فلمــا ســبق فإنــه لــم يظهــر لــي ســوى مــا أجريتــه وقــررت‬\n      ‫إحلاقــه لصكــه وســجله ومــن ثــم إعادتهــا ألصحــاب الفضيلــة قضــاة‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة إلكمــال الزمهــا ‪ ،‬أعانهــم اهلل‬\n      ‫ووفقهــم ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n      ‫أجمعــن حــرر يف ‪1434/05/07‬ه ـ ‪.‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم األحــد املوافــق ‪1434/07/09‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫الثانيــة عشــر ظهــر ًا ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة‬\n      ‫برقــم ‪ 332028985‬وتاريــخ ‪1434/06/14‬ه ـ املقيــدة بهــذه احملكمــة‬\n      ‫برقــم ‪ 332028985‬وتاريــخ ‪1434/06/16‬ه ـ واملرفــق بهــا القــرار رقــم‬\n      ‫‪ 34227224‬وتاريــخ ‪1434/05/29‬ه ـ ونصــه « وبدراســة مــا أجــاب بــه‬\n      ‫فضيلتــه وجــد غيــر مقنــع واملــادة التــي استشــهد بهــا خاصــة باهــل‬\n      ‫الصفــات االعتباريــة كرؤســاء ومــدراء الدوائــر احلكوميــة ‪ ،‬فعلــى‬\n      ‫فضيلتــه الرجــوع إلــى قرارنــا الســابق وإجــراء مقتضــاه واهلل املوفــق «أ‪.‬ه ـ‬\n      ‫وعليــه أجيــب أصحــاب الفضيلــة ‪-‬وفقهــم اهلل‪ :-‬بــأن صاحــب احلــق‬\n      ‫اخلــاص هــو جهــة حكوميــة ‪ ،‬واملــال املســروق هــو مــن أمــوال الدولــة ‪،‬‬\n      ‫وقــد ســبق أن كاتبــت املشــرف علــى مكتــب االدعــاء بهــذه احملكمــة‬\n      ‫بكتابــي رقــم ‪ 33257001‬يف ‪1433/02/14‬ه ـ إبــان نظــر الدعــوى‬\n      ‫العامــة مستفســر ًا عــن ملكيــة املــال املســروق ‪ ،‬فوردتنــي إفادتــه‬\n      ‫بكتابــه ذا الرقــم ه م ‪/2/‬ب‪ 167/‬يف ‪1433/02/15‬ه ـ ‪ ،‬املرفــق‬\n      ‫بالطــرد املرفــق باملعاملــة لفــة رقــم (‪ )74‬وبرفقــه كتــاب املشــرف علــى‬\n      ‫قصــور ‪ ...‬املــؤرخ يف ‪1433/02/14‬ه ـ املرفــق بالطــرد املرفــق باملعاملــة‬\n\n\n‫‪189‬‬\n\f‫لفــة رقــم (‪ )73‬واملتضمنــة جميع ـ ًا أن ملكيــة املواســير النحاســية‬\n‫املذكــورة يف الدعــوى ‪ ،‬تعــود إلــى أمــاك الدولــة ( وزارة املاليــة ) وأن‬\n‫مــا يبــاع منهــا يــودع قيمتــه بــوزارة املاليــة ‪ ،‬وعليــه فــا حاجــة حينئــذ‬\n‫إلصــدار وكالــة ‪ ،‬بــل يكتفــى بالتفويــض حســب التعليمــات والتــي‬\n‫ســبق إيرادهــا بعاليــه ‪ ،‬لذلــك فإنــه لــم يظهــر لــي ســوى مــا أجريــت‬\n‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف لتدقيقهــا كاملتبــع وإعمال‬\n‫مقتضــى املــادة (‪ )188‬مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/07/09‬هــ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/09/08‬ه ـ عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪332028985‬‬\n‫وتاريــخ ‪1434/08/22‬ه ـ واملقيــدة بأســاس هــذه احملكمــة رقــم‬\n‫‪ 332028985‬وتاريــخ ‪1434/08/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف رقــم ‪34290573‬‬\n‫وتاريــخ ‪1434/08/07‬ه ـ واملــدون علــى ظهــر الصك املتضمن (وبدراســة‬\n‫احلكــم وصــورة ضبطــه قررنــا باألكثريــة املوافقــة علــى احلكــم) لــذا‬\n‫جــرى حتريــر ذلــك وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل‬\n                   ‫على نبينا محمد وآله وسلم حرر يف ‪1434/09/08‬هـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":182,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8cbc51a031c6aea0b23b63093ae4d304a60b7e21ca4cf61dab23c29c4180fa56","normalized_text_hash":"e7ad3e79a4d1ffeefda3d08433cd9be75f0634d65bf2e5179331093844a85b99","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p182-33411618"},{"id":"c4bd8b2b-c179-54cd-8ff6-da6a0df48033","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مغصوب -زوجة تدعي على زوجها رد مبلغ مالي مت االستيالء عليه من حساب مصريف -غياب املدعى عليه رغم تبليغه -اليمن تشرع يف جانب أقوى املتداعين -البينة :كشف احلساب وحلف اليمن -ثبوت الدعوى -حكم حضوري -التماس إعادة النظر -رفض االلتماس بعد النظر يف موضوعه.","document_number":"33442131","case_number":"33546412","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/29","year":"1434","subject":"مطالبة برد مغصوب -زوجة تدعي على زوجها رد مبلغ مالي مت االستيالء عليه من حساب مصريف -غياب املدعى عليه رغم تبليغه -اليمن تشرع يف جانب أقوى املتداعين -البينة :كشف احلساب وحلف اليمن -ثبوت الدعوى -حكم حضوري -التماس إعادة النظر -رفض االلتماس بعد النظر يف موضوعه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/29 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33442131 :‬‬\n                          ‫َر ْق ُم الدعوى‪33546412 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3417357‬تاريخه‪1434/1/20:‬هـ‬\n\n\n       ‫مطالبــة بــرد مغصــوب ‪ -‬زوجــة تدعــي علــى زوجهــا رد مبلــغ مالــي مت‬\n       ‫االســتيالء عليــه مــن حســاب مصــريف ‪ -‬غيــاب املدعــى عليــه رغــم تبليغــه‬\n       ‫‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬البينــة‪ :‬كشــف احلســاب‬\n       ‫وحلــف اليمــن ‪ -‬ثبــوت الدعــوى ‪ -‬حكــم حضــوري‪ -‬التمــاس إعــادة‬\n                             ‫النظــر‪ -‬رفــض االلتمــاس بعــد النظــر يف موضوعــه‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول ابــن القيــم رحمــه اهلل يف إعــام املوقعــن (‪( :)101/1‬والــذي‬\n       ‫جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعيــن ‪..‬إلخ)‪.‬‬\n       ‫‪ -2‬مــا قــرره جمــع مــن أهــل العلــم مــن القضــاء علــى الغائب املســتتر وإن‬\n       ‫لــم يكــن مــع املدعــى بينــة حتــى ال يكــون االمتنــاع طريقـ ًا إلــى إســقاط‬\n       ‫احلقــوق التــي نصــب القاضــي حلفظهــا‪ .‬انظــر أدب القاضــي للمــاوردي‬\n                                                                             ‫(‪.)323/2‬‬\n                                        ‫‪ -3‬األصل امتالك اإلنسان ما يف حوزته‪.‬‬\n       ‫‪ -4‬املــواد (‪ )1/55‬و(‪ )3/195‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات‬\n                                                                          ‫الشــرعية ‪.‬‬\n\n\n\n       ‫ادعــت املدعيــة بــأن املدعــى عليــه زوجهــا وقــد قــام بتحويل وســحب مبالغ‬\n       ‫ماليــة مفصلــة يف دعواهــا مــن حســابها اخلــاص إلــى حســابه اخلــاص بعــد‬\n‫‪191‬‬\n\f‫أن قــام بحبســها يف بيتــه وأخــذ بطاقــة الصــراف اآللــي اخلاصــة بها منها‪،‬‬\n‫ولــذا فقــد طلبــت احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n‫إليهــا‪ -‬املدعــى عليــه لــم يحضــر مــع تبلغــه مبوعــد اجللســة لــذا فقــد‬\n‫قــررت احملكمــة مواصلــة الســير يف الدعــوى بغيابــه وطلبت مــن املدعية‬\n‫تقــدمي بينتهــا فذكــرت أن بينتهــا هــي كشــف احلســاب لــدى املصــرف‬\n‫وباالطــاع عليــه وجدتــه احملكمــة يتضمــن حتويــات وســحوبات ماليــة‬\n‫مطابقــة لدعــوى املدعيــة‪ -‬املدعيــة تقــوى جانبهــا مبــا قدمتــه مــن بينــة‬\n‫مــع تغيــب املدعــى عليــه عــن اجللســة مــع تبلغــه باحلضــور لــذا فقــد وجهــت‬\n‫احملكمــة لهــا اليمــن املكملــة لبينتهــا فأدتهــا طبــق مــا طلــب منهــا‪-‬‬\n‫قضــت احملكمــة حضوري ـ ًا بإلــزام املدعــى عليــه بــأن يدفــع للمدعيــة‬\n‫املبلــغ املدعــى بــه‪ -‬قنعــت املدعيــة باحلكــم‪ -‬تقــدم املدعى عليــه بالتماس‬\n‫ال وأحالتــه للمحكمــة‬     ‫إعــادة نظــر فقبلتــه محكمــة االســتئناف شــك ً‬\n‫االبتدائيــة للنظــر يف موضوعــه‪ -‬مبواجهــة املدعــى عليــه بالدعــوى أقــر‬\n‫بالتحويــات والســحوبات املاليــة مــن حســاب املدعيــة ودفــع بــأن تلــك‬\n‫األمــوال هــي يف األصــل لــه وقــد أخذتهــا املدعيــة منــه بغيــر حــق فقــام‬\n‫باســتردادها منهــا‪ -‬طلبــت احملكمــة مــن املدعــى عليــه تقــدمي بينــة علــى‬\n‫مــا دفــع بــه فقــدم بينــات غيــر موصلــة ولــم يقبــل ميــن املدعيــة علــى نفــي‬\n‫ذلــك الدفــع‪ -‬قضــت احملكمــة برفــض االلتمــاس موضوعــا وأفهمــت‬\n‫املدعــى عليــه بــأن لــه ميــن املدعيــة متــى مــا طلبهــا‪ -‬اعتــرض املدعــى‬\n‫عليــه علــى احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‬\n\n\n\n\n                                                                                        ‫‪192‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع املســاعد برقــم ‪ 33546412‬وتاريــخ ‪1433/08/25‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331601376‬وتاريــخ ‪1433/08/25‬ه ـ‬\n      ‫ففــي يــوم األحــد املوافــق‪ 143/09/10‬ه ـ افتتحــت اجللســة الســاعة ‪45‬‬\n      ‫‪ 12 :‬وفيهــا حضــرت (‪ ).....‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم(‪ ).....‬واملعــرف بهــا مــن قبــل أخيهــا (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬وادعــت علــى الغائــب عــن مجلــس احلكــم‬\n      ‫الشــرعي قائلــة يف دعواهــا إن املدعــى عليــه الغائــب عــن املجلــس‬\n      ‫الشــرعي زوجــي قــد قــام بحبســي يف بيتــه مــن تاريــخ ‪1432/08/20‬ه ـ‬\n      ‫حتــى تاريخ‪1432/09/10‬ه ـ وأخــذ منــي بطاقــة الصــراف اآللــي‬\n      ‫اخلاصــة بــي وقــام بتحويــل مبلــغ وقــدره (‪ )200,000‬مائتــا ألــف ريــال‬\n      ‫مــن حســابي اخلــاص يف (‪ ).....‬حلســابه اخلــاص يف (‪ ).....‬وأيض ـ ًا قــام‬\n      ‫بســحب مبلــغ نقــدي قــدره (‪ )50,000‬خمســون ألــف ريــال أطلــب احلكــم‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه وقــدره (‪ )250,000‬مائتــان‬\n      ‫وخمســون ألــف ريــال هــذه دعــواي وقــد ســبق أن تبلــغ املدعــى عليــه‬\n      ‫مبوعــد اجللســة يــوم األحــد املوافــق ‪1433/09/10‬ه ـ الســاعة العاشــرة‬\n      ‫حســب منــوذج التبليــغ املرفــق باملعاملــة ولــم يحضــر وملــا ســبق واســتناد ًا‬\n      ‫علــى الفقــرة (‪ )1‬مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية والئحتهــا التنفيذيــة ونصهــا (إذا تبلــغ املدعــى عليــه لشــخصه‬\n      ‫أو وكيلــه الشــرعي يف القضيــة نفســها مبوعــد اجللســة أو أودع هــو أو‬\n\n‫‪193‬‬\n\f‫وكيلــه مذكــرة بدفاعــه للمحكمــة قبــل اجللســة فيعــد احلكــم يف‬\n‫حقــه حضوريـ ًا ســواء أكان غيابــه قبــل قفــل بــاب املرافعــة أم بعده)‪.‬أ‪.‬ه ـ‬\n‫فلــذا قــررت الســير يف القضيــة فســألت املدعيــة هــل لديهــا بينــة علــى‬\n‫ذلــك فقالــت نعــم لــدي كشــف حســاب لــدى املصــرف وقــد راجعتهــم‬\n‫لطلبــه فرفضــوا حتــى أحضــر بطاقــة العائلــة وهــي ليســت معــي وإمنــا مــع‬\n‫زوجــي وليــس لــي عالقــة بــه اآلن وغيــر متواصــل معــي هكــذا أجابــت‬\n‫وألجــل الكتابــة ملصــرف (‪ ).....‬لتزويدنــا بكشــف حســاب للمدعيــة‬\n‫ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهــا مــن أخيهــا (‪).....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وقــد ســبق الكتابــة‬\n‫ملصــرف (‪ ).....‬بخطابنــا ذي الرقــم(‪ ).....‬وتاريــخ ‪1433/09/13‬ه ـ بشــأن‬\n‫تزويدنــا بكشــف حســاب للمدعيــة خــال الفتــرة مــن ‪1432/8/18‬ه ـ‬\n‫إلــى ‪1432/09/10‬ه ـ وكذلــك إفادتنــا بالعمليــات املتعلقــة بحســاب‬\n‫املدعــى عليــه ولــم يردنــي منهــم أي إفــادة وقــد أبــرزت املدعيــة كشــف‬\n‫حســاب صــادر مــن مصــرف (‪ ).....‬فــرع (‪ ).....‬وباالطــاع عليــه تضمــن‬\n‫مــا يلــي حتويــل مــن حســاب املدعيــة إلــى حســاب املدعــى عليــه بتاريــخ‬\n‫‪1432/08/24‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬عشــرون ألــف ريــال‬\n‫وتاريــخ ‪1432/08/25‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون‬\n‫ألــف ريــال وتاريــخ ‪1432/08/26‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬‬\n‫عشــرون ألــف ريــال وتاريــخ ‪1432/08/27‬ه ـ مت حتويــل مبلــغ وقــدره‬\n‫(‪ )20,000‬عشــرون ألــف ريــال وتاريــخ ‪1432/08/28‬ه ـ مت حتويــل مبلــغ‬\n‫وقدره (‪ )20,000‬عشرون ألف ريال وتاريخ ‪1432/08/29‬هـ مت حتويل‬\n‫مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال وتاريخ‪1432/08/30‬ه ـ‬\n‫مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال تاريــخ‬\n\n\n                                                                                  ‫‪194‬‬\n\f      ‫‪1432/09/01‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال‬\n      ‫وتاريــخ ‪1432/09/02‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون‬\n      ‫ألــف ريــال وتاريــخ ‪1432/09/03‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬‬\n      ‫عشــرون ألــف ريــال فيكــون مجمــوع مــا مت حتويلــه مــن حســاب املدعيــة‬\n      ‫حلســاب املدعــى عليــه مبلــغ وقــدره (‪ )200,000‬مئتــا ألــف ريــال ثــم أنــه‬\n      ‫مــن تاريــخ ‪1432/08/24‬ه ـ إلــى تاريــخ ‪1432/09/03‬ه ـ مت ســحب‬\n      ‫مبلــغ وقــدره (‪ )50,000‬خمســون ألــف ريــال وتفصيلــه كالتالــي بتاريــخ‬\n      ‫‪1432/08/24‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال‬\n      ‫وبتاريــخ ‪1432/08/25‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف‬\n      ‫ريــال وبتاريــخ ‪1432/08/26‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة‬\n      ‫آالف ريــال وبتاريــخ ‪1432/08/28‬ه ـ مت ســحب مبلــغ وقــدره (‪)5,000‬‬\n      ‫خمســة آالف ريــال وبتاريــخ ‪1432/08/29‬ه ـ مت ســحب مبلــغ وقــدره‬\n      ‫(‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/08/30‬ه ـ مت ســحب مبلــغ‬\n      ‫وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/09/01‬ه ـ مت ســحب‬\n      ‫مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/09/02‬ه ـ‬\n      ‫مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ‬\n      ‫‪1432/09/03‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال‬\n      ‫ثــم جــرى منــي ســؤال املدعيــة هــل لديهــا زيــادة بينــه علــى مــا ذكرتــه‬\n      ‫فأجابــت بقولهــا ليــس لــدي ســوى مــا ذكرتــه ومبــا أن املدعــى عليــه قــد‬\n      ‫تغيــب عــن اجللســة مــع تبلغــه باحلضــور إضافــة إلــى البينــة التــي قدمتهــا‬\n      ‫املدعيــة يرجــح قــوة جانبهــا لــذا فقــد أفهمتهــا بــأن اليمــن متوجهــة عليهــا‬\n      ‫يف إثبــات صحــة دعواهــا وعــدم ســداد املدعــى عليــه للمبلــغ املدعــى‬\n      ‫بــه أو بعضــه فاســتعدت باحللــف فجــرى منــي تخويفهــا مبغبــة اليمــن‬\n\n\n‫‪195‬‬\n\f‫الكاذبــة ففهمــت ذلــك وحلفــت قائل ـ ًة‪( :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أن املدعــى عليــه قــد قــام بأخــذ بطاقــة الصــراف اآللــي اخلــاص بــي‬\n‫واختلــس مــن حســاباتي مبلغ ـ ًا وقــدره (‪ )250,000‬مائتــان وخمســون‬\n‫ألــف ريــال مــن غيــر علمــي وال موافقتــي أقســم بــاهلل علــى ذلــك) هكــذا‬\n‫حلفــت فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة ومبــا أن املدعــى عليــه‬\n‫قــد تبلــغ لشــخصه نظام ـ ًا مبوعــد اجللســة ولــم يحضــر ونظــر ًا ملــا ورد‬\n‫يف الالئحــة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية والئحتهــا التنفيذيــة ومبــا أن بينــة املدعيــة بينــة غيــر موصلــة‬\n‫إال أن غيــاب املدعــى عليــه عــن املجلــس الشــرعي مــع تبلغــه لشــخصه‬\n‫يرجــح قــوة جانــب املدعيــة واليمــن تتوجــه علــى أقــوى املتداعــن ولهــذا‬\n‫قــال ابــن القيــم رحمــه اهلل يف إعــام املوقعــن ‪ 101/1‬مــا نصــه (والــذي‬\n‫جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعيــن فــأي‬\n‫اخلصمــن ترجــح جانبــه جعلــت اليمــن مــن جهتــه وهــذا مذهــب اجلمهــور‬\n‫كأهــل املدينــة وفقهــاء احلديــث كاإلمــام أحمــد والشــافعي ومالــك‬\n‫وغيرهــم) ونظــر ًا ملــا قــرره جمــع مــن أهــل العلــم مــن القضــاء علــى الغائــب‬\n‫املســتتر وإن لــم يكــن مــع املدعــى بينــة حتــى ال يكــون االمتنــاع طريقـ ًا‬\n‫إلــى إســقاط احلقــوق التــي نصــب القاضــي حلفظهــا انظــر أدب القاضــي‬\n‫للمــاوردي ( ‪ )323/2‬ومبــا أن املدعيــة حلفــت اليمــن املطلوبــة منها كما‬\n‫ـدي صحــة دعــوى املدعيــة وحكمــت‬        ‫هــو مفصــل أعــاه لــذا فقــد ثبــت لـ َّ‬\n‫علــى املدعــى عليــه حكمـ ًا حضوريـ ًا بــأن يدفــع للمدعيــة املبلــغ املدعــى‬\n‫بــه وقــدره (‪ )250,000‬مائتــان وخمســون ألــف ريــال والغائــب علــى حجتــه‬\n‫متــى حضــر ‪ ،‬وبعــرض احلكــم علــى املدعيــة قنعــت بــه وقــررت إكمــال‬\n‫مــا يلــزم حيــال إبــاغ املدعــى عليــه الغائــب باحلكــم حســب التعليمــات‬\n\n\n                                                                                         ‫‪196‬‬\n\f      ‫‪ ،‬ثــم رفــع كامــل املعاملــة حــال االقتضــاء إلــى محكمــة االســتئناف‬\n      ‫لدراســة احلكــم وتدقيقــه حســب املتبــع ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/10/24‬ه ـ‬\n                                                        ‫الســاعة العاشــرة والنصــف ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردنــا خطــاب رئيــس محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف رقــم ‪341184568‬‬\n      ‫وتاريخ‪1434/06/10‬ه ـ وبرفقــه قــرار الدائــرة اجلزائيــة اخلامســة‬\n      ‫رقــم‪ 34225202‬وتاريخ‪1434/05/28‬ه ـ املتضمــن (احلمــد هلل وحــده‬\n      ‫والصــاة والســام علــى مــن ال نبـ ّـي بعــده‪ ،‬وبعــد‪ :‬فقــد جــرى منــا نحــن‬\n      ‫قضــاة الدائــرة اجلزائيــة اخلامســة االطــاع علــى إحالــة ســماحة رئيــس‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪34223369‬‬\n      ‫وتاريخ‪1434/05/14‬ه ـ املشــفوع بهــا صحيفــة االلتمــاس املقدمــة مــن‬\n      ‫(‪ ).....‬املقيــدة برقــم ‪ 341184568‬وتاريــخ ‪1434/05/14‬ه ـ املتضمنــة‬\n      ‫التمــاس املذكــور إعــادة النظــر يف احلكــم الصــادر مــن فضيلــة‬\n      ‫الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة بينبــع برقــم‪33442131‬‬\n      ‫وتاريخ‪1433/10/29‬ه ـ املصــدق مــن محكمــة االســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة برقــم ‪ 3417357‬وتاريخ‪1434/01/20‬ه ـ وبدراســة‬\n      ‫ـاء علــى االلتمــاس املقــدم مــن (‪ ).....‬بشــأن احلكــم رقــم‬   ‫املعاملــة وبنـ ً‬\n      ‫‪ 33442131‬وتاريخ‪1433/10/29‬ه ـ واحملكــوم فيــه عليــه غيابي ـ ًا‬\n      ‫وحيــث تقــدم وبطلــب ســماع رده لــذا حتــال لفضيلتــه احلاكــم لســماع‬\n      ‫رده علــى الدعــوى ومــن ثــم إجــراء الــازم وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضي‬\n      ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه)‬\n\n\n‫‪197‬‬\n\f‫ا‪.‬ه ـ عليــه ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/06/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الواحــدة والنصــف وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عــن دعــوى املدعيــة أجــاب‬\n‫ا مــا ذكرتــه املدعيــة مــن قيامــي بتحويــل مبلــغ وقــدره (‪)200,000‬‬     ‫قائـ ً‬\n‫مائتــا ألــف ريــال مــن حســابها إلــى حســابي يف مصــرف (‪ ).....‬وقيامــي‬\n‫بســحب مبلــغ نقــدي قــدره(‪ )50,000‬خمســون ألــف ريــال مــن حســابها‬\n‫عبــر الصــراف اآللــي فصحيــح ولكــن بالنســبة ملبلــغ التحويــل فــإن‬\n‫املدعيــة قــد قامــت قبــل حوالــي ســنة ونصــف بالدخــول إلــى حســابي عــن‬\n‫طريــق االنترنــت نظــر ًا لكونهــا تعــرف الرقــم الســري حلســابي وقامــت‬\n‫بتحويــل مبلــغ وقــدره (‪ )100,000‬مائــة ألــف ريــال مــن حســابي حلســابها‬\n‫الشــخصي وبعدهــا كذلــك قامــت بنفــس العمليــة وقامــت بتحويــل مبلــغ‬\n‫وقــدره (‪ )100,000‬مائــة ألــف ريــال مــن حســابي حلســابها الشــخصي‬\n‫مبــا مجموعــه (‪ )200,000‬مائتــا ألــف ريــال ثــم تبــن لــي ذلــك فســألتها‬\n‫عــن تلــك العمليــة فأخبرتنــي أنهــا تريــد بــأن تتفاخــر بذلــك علــى أخوتهــا‬\n‫وبعدهــا بفتــرة قمــت بإجــراء التحويــل املذكــور يف دعواهــا اســترداد ًا‬\n‫للمبلــغ الــذي أخذتــه منــي بغيــر حــق وأمــا بالنســبة ملــا ذكرتــه مــن‬\n‫قيامــي بســحب مبلــغ (‪ )50,000‬خمســون ألــف ريــال نقــد ًا مــن الصــراف‬\n‫اآللــي فصحيــح بــل ســحبت أكثــر مــن ذلــك نظــر ًا ألن جميــع املبالــغ‬\n‫التــي بحســابها تعــود لــي شــخصي ًا وأنــا مــن قمــت بإيداعهــا والتحويــل‬\n‫فيهــا نظــر ًا ألننــي قمــت بإنشــاء ذلــك احلســاب لهــا مــن أجــل التســجيل‬\n‫بحافــز وبعدهــا قمــت باســتخدامه نظــر ًا لعــدم نــزول حافــز لهــا وبإذنهــا‬\n‫لــذا أطلــب إلغــاء احلكــم الصــادر علــي بدفــع تلــك املبالــغ للمدعيــة‬\n‫هكــذا أجــاب ثــم جــرى رفــع اجللســة لطلــب املدعيــة وســماع جوابهــا‬\n\n\n                                                                                     ‫‪198‬‬\n\f      ‫عــن دفــع املدعــى عليــه ويف جلســة أخــرى حضــرت املدعيــة واملعــرف‬\n      ‫بهــا مــن قبــل أخيهــا وحضــر حلضورهــا املدعــى عليــه وبعــرض إجابــة‬\n      ‫املدعــى عليــه علــى املدعيــة قــررت قائلــة مــا ذكــره املدعــى عليــه غيــر‬\n      ‫ا فأنــا ال أعــرف حســاباته وال أرقامهــا الســرية‬   ‫صحيــح جمل ـ ًة وتفصي ـ ً‬\n      ‫ولــم أدخــل عليهــا قــط ولــم أقــم بتحويــل مبلــغ (‪ )200,000‬مائتــن ألــف‬\n      ‫ريــال مــن حســابه إلــى حســابي ولــم أتقــدم علــى حافــز نظــر ًا لكونــي‬\n      ‫لــدي عمــال باســمي وأمــا مــا ذكــره مــن أن جميــع املبالــغ التــي بحســابي‬\n      ‫تعــود لــه شــخصي ًا فغيــر صحيــح وأمــا مــا ذكــره مــن أن مــن يقــوم بإيــداع‬\n      ‫املبالــغ بحســابي والتحويــل إليــه فصحيــح ذلــك أن بينــي وبينــه شــراكة‬\n      ‫وهــي عبــارة عــن اســتيراد أعشــاب مــن مصــر وكان عملــي هــو عمــل‬\n      ‫دعايــة علــى االنترنــت واســتقبال االتصــاالت وفــرز تلــك األعشــاب‬\n      ‫حــن وصولهــا وعملــه هــو القيــام باالســتيراد وكانــت الشــراكة بيننــا‬\n      ‫مناصفــة وكان يقــوم بدفــع مســتحقاتي عــن طريــق التحويــل احلســابي‬\n      ‫أو اإليــداع نهايــة كل شــهر هكــذا أجابــت وبعرضــه علــى املدعــى عليــه‬\n      ‫قــرر بقولــه مــا ذكرتــه املدعيــة غيــر صحيــح والصحيــح مــا ذكرتــه‬\n      ‫فســألت املدعــى عليــه هــل لديــه بينــة تشــهد بصحــة قيــام املدعيــة‬\n      ‫بتحويــل مبلــغ (‪ )200,000‬مائتــن ألــف ريــال علــى دفعتــن وأن املــال‬\n      ‫الــذي بحســاب املدعيــة هــو مالــه وعائــد لــه وليــس للمدعيــة منــه نصيــب‬\n      ‫فأجــاب بقولــه نعــم لديــه بينــة واطلــب مهلــة إلحضارهــا فأجبتــه لطلبــه‬\n      ‫ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهــا مــن قبــل ابــن أخيهــا‬\n      ‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي (‪ ).....‬وحضــر حلضورهــا‬\n      ‫املدعــى عليــه وبســؤال املدعــى عليــه هــل أحضــر بينتــه التــي اســتمهل مــن‬\n      ‫أجلهــا يف اجللســة املاضيــة فأجــاب بقولــه نعــم وأبــرز كشــف حســاب‬\n\n\n‫‪199‬‬\n\f‫صــادر مــن مصــرف (‪ ).....‬لرقــم احلســاب واملتضمــن حتويــل مــن احلســاب‬\n‫املذكــور إلــى حســاب رقــم (‪ ).....‬باســم مبلــغ وقــدره (‪ )100,000‬مائــة‬\n‫ألــف ريــال وحتويــل مــن احلســاب املذكــور إلــى حســاب رقــم باســم مبلــغ‬\n‫وقــدره (‪ )100,000‬مائــة ألــف ريــال فســألت املدعــى عليــه هــل لديــه‬\n‫زيــادة بينــة تشــهد بــأن الــذي قــام بالتحويــل هــي املدعيــة وأن املبلــغ الــذي‬\n‫بحســاب املدعيــة واملبلــغ الــذي قــام بســحبه مــن الصــراف اآللــي عائــد لــه‬\n‫وليــس للمدعيــة منــه نصيــب فأجــاب بقولــه ليــس لــدي ســوى مــا ذكرتــه‬\n‫فأفهمتــه أن لــه ميــن املدعيــة علــى نفــي مــا ادعــاه فقــال ال أطلــب ميينهــا‬\n‫فكــررت عليــه ذلــك ثــاث مــرات فرفــض ميينهــا لــذا وملــا تقــدم بيانــه‬\n‫مــن ادعــاء املدعــى عليــه بــأن املــال الــذي بحســاب املدعيــة مالــه ومبــا أن‬\n‫األصــل امتــاك اإلنســان مــا يف حوزتــه واحلســاب البنكــي يعتبــر ملــك ًا‬\n‫خاصـ ًا للشــخص وال يصــار عنــه إال ببينــة وليــس لــدى املدعــى عليــه بينــة‬\n‫موصلــة تشــهد بصحــة ادعائــه وقــد رفــض ميــن املدعيــة بنفــي مــا ادعــاه‬\n‫لــذا فــا زلــت علــى مــا حكمــت بــه ســابق ًا وأفهمــت املدعــى عليــه بــأن‬\n‫لــه ميــن املدعيــة متــى مــا طلبهــا وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n‫عــدم قناعتــه بــه وطلــب االســتئناف مســتعد ًا بتقــدمي الئحــة اعتراضيــة‬\n‫فأجبتــه لطلبــه وأفهمتــه بــأن عليــه مراجعــة احملكمــة خــال عشــرة أيــام‬\n‫الســتالم نســخة مــن الصــك ومــن ثــم تقــدمي الئحتــه االعتراضيــة خــال‬\n‫ثالثــن يومـ ًا مــن تاريــخ االســتالم ففهم ذلك وبــاهلل التوفيق ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/03‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n‫بينبــع والقائــم بعمــل املكتــب القضائــي اخلامــس مبوجــب قــرار فضيلــة‬\n‫رئيــس احملكمــة العامــة بينبــع املســاعد رقــم ‪ 341935902‬وتاريــخ‬\n\n\n                                                                                         ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":191,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"167a2eb86f25de62b7614a0771d75ce4523af1f66515e42fd7d9ce4b961a82b3","normalized_text_hash":"5fa8118d1496f73fac0a9c0fcc6e446bf23c3e5340906176dfb177288f11229f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p191-33442131"},{"id":"a973a449-c57b-5de1-ad42-bbe64a390e03","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيكني -اإلقرار بالسرقة يف املعاملة اجلزائية -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -إلزام املدعى عليه بسداد املبلغ املدعى به .","document_number":"34194629","case_number":"33547446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيكني -اإلقرار بالسرقة يف املعاملة اجلزائية -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -إلزام املدعى عليه بسداد املبلغ املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34194629 :‬‬\n                          ‫َر ْق ُم الدعوى‪33547446:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34363824‬تاريخه‪1434/11/19:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق تزويــر شــيكني ‪ -‬اإلقــرار‬\n      ‫بالســرقة يف املعاملــة اجلزائيــة ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار بحــق‬\n                      ‫اآلدمــي ‪ -‬إلــزام املدعــى عليــه بســداد املبلــغ املدعــى بــه ‪.‬‬\n\n\n\n\n                                                 ‫‪ .1‬قاعدة‪ :‬اإلقرار حجة على من أقر ‪.‬‬\n                                                            ‫‪ .2‬قاعدة‪ :‬ال عذر ملن أقر ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بتزويــر توقيعــه علــى شــيكني مــن‬\n      ‫الشــيكات اخلاصــة بــه ثــم قــام بصرفهمــا لصالــح نفســه دون وجــه حــق ؛‬\n      ‫وطلــب إلزامــه بســداد قيمــة الشــيكني املذكوريــن لــه ‪ -‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى جملــة وتفصيــا ‪ -‬املدعــى عليــه لــه إقــرار مصــدق شــرعا‬\n      ‫مبــا جــاء يف الدعــوى وتؤيــده األحــكام الصــادرة ضــده للحــق العــام ‪-‬‬\n      ‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي قيمــة الشــيكني‬\n      ‫املزوريــن الذيــن قــام بصرفهمــا لصالــح نفســه ‪ -‬عــارض املدعــى عليــه‬\n        ‫علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫ببريــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم ‪ 33547446‬وتاريــخ ‪ 1433/08/26‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331605130‬وتاريــخ ‪ 1433/08/26‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/10/23‬ه ـ افتتحــت اجللســة ونظــرا لكونــه قد مت‬\n‫حتديــد موعــد لنظــر هــذه الدعــوى يف متــام الســاعة احلاديــة عشــر صباحــا‬\n‫املقامــة مــن ضـ ــد بخصــوص مطالبــة ماليــة ونظــرا لعــدم حضــور املدعــي‬\n‫وال وكيــا عنــه ولــم يقــدم لنــا عــذرا مقبــوال لــذا جــرى منــا شــطب هــذه‬\n‫الدعــوى للمــرة األولــى حســب التعليمــات املرعيــة واســتنادا إلــى املــادة‬\n‫(‪ )53‬مــن نظــام املرافعــات الشــرعية ‪ ،‬وبــاهلل التوفيــق ‪ ،‬ويف يــوم األثنــن‬\n‫املوافــق ‪1433/12/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬فادعــى علــى احلاضــر معــه‬\n‫ا يف تقريــر دعــواه‬  ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬قائـ ً‬\n‫عليــه إن هــذا احلاضــر املدعــى عليــه ســبق أن قــام بســرقة عــدة شــيكات‬\n‫مــن مكتبــي مــن حســابات متفرقــة وقــد صــرف شــيكني منهــا األول‬\n‫ميثــل مبلغ ـ ًا وقــدره مائــة وثمانــون ألــف ريــال واملســحوب علــى مصــرف‬\n‫‪ ...‬والثانــي ميثــل مبلغ ـ ًا وقــدره مائــة وســتون ألــف ريــال واملســحوب علــى‬\n‫البنــك ‪ ...‬وقــام بصرفهمــا وقــد أديــن بالســرقة وحكــم عليــه باحلــق العــام‬\n‫ووجــدت الشــيكات يف بيتــه محــاو ًال تطبيــق توقيعــي ‪ ،‬أطلــب احلكــم‬\n‫عليــه وإلزامــه بســداد مبلــغ هذيــن الشــيكني وقدرهــا ثالثمائــة وأربعــون‬\n‫ا‬\n‫ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n\n                                                                                      ‫‪204‬‬\n\f      ‫مــا ذكــره املدعــي يف دعــواه غيــر صحيــح هكــذا أجــاب وحيــث أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي طلبــت مــن املدعــي البينــة علــى دعــواه فقــال‬\n      ‫بينتــي موجــودة لــدى األدلــة اجلنائيــة وهيئــة التحقيــق واالدعــاء العــام‬\n      ‫لإلفــادة عــن ذلــك لــذا جــرى رفــع اجللســة حلــن ورود اإلجابــة ‪ ،‬ويف‬\n      ‫يــوم االثنــن املوافــق ‪ 1434/04/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫الطرفــان وقــد جــرى االطــاع علــى محضــر التحقيــق احملضــر فئــة (‬\n      ‫‪ 12‬صفحــة ‪ ) 1‬ووجــد فيــه إقــرارا منســوبا للمدعــى عليــه وهــذا نصــه‬\n      ‫(نعــم أنــا أقــر بطوعــي واختيــاري أننــي دخلــت إلــى إدارة معــرض ‪ ...‬يف‬\n      ‫طريــق املعــارض وقمــت بأخــذ مجموعــة مــن شــيكات مــن اإلدارة ثــم‬\n      ‫بعــد ذلــك قمــت بكتابــة اســمي عليهــا وتدويــن مبلــغ مائــة وثمانــن ألــف‬\n      ‫علــى أحدهمــا ومبلــغ مائــة وســتني ألــف ريــال علــى شــيك ثانــي ثــم قمــت‬\n      ‫بصرفهــا لصاحلــي بعــد التوقيــع عليهــا باملطابقــة مــع صورة شــيك أخذتها‬\n      ‫مــن نفــس املــكان وقــد احتفظــت مبــا تبقــى مــن الشــيكات يف غرفتــي‬\n      ‫يف بيــت والــدي كمــا أقــر بأنــي قمــت بأخــذ شــيكات مــن مؤسســة ‪...‬‬\n      ‫وعددهــا اثنــان صرفــت أحدهــا مببلــغ مائــة وعشــرون ألــف ريــال والثانــي‬\n      ‫(( مببلــغ مئــة وســتني )) مببلــغ ســتني ألــف ريــال كمــا أنــي فعلــت ذلــك‬\n      ‫بعــد كتابــة اســمي والتوقيــع علــى الشــيكات مبطابقــة صــورة أخذتهــا‬\n      ‫مــن نفــس املكتــب كمــا أنــي اشــتريت رافعــة مــن ‪ ...‬وســلمتهم إيصــال‬\n      ‫إيــداع شــيك مقاصــة علــى ‪ ...‬علــى حســاب لــي ليــس بــه رصيــد واســتلمت‬\n      ‫الرافعــة ولــم أســدد املبلــغ كمــا أننــي اشــتريت حراثــة مــن شــركة ‪..‬‬\n      ‫بقيمــة مئــة وثالثــن ألــف ريــال وســلمتهم إيصــال إيــداع شــيك مقاصــة‬\n      ‫علــى بنــك ‪ .......‬علــى حســاب لــي ليــس بــه رصيــد واســتلمت احلراثــة مــن‬\n      ‫الشــركة وبعتهــا بســبعني ألــف ريــال كمــا بعــت الرافعــة بأربعــن ألــف‬\n\n\n‫‪205‬‬\n\f‫ريــال كمــا أقــر جميــع مــا ضبــط يف غرفتــي مــن شــيكات عائــد لــي و‬\n‫كذلــك الدفتــر الــذي وجــد بــه تواقيــع مختلفــة وقــد جمعــت الشــيكات‬\n‫مــن أماكــن مختلفــة علمــا بأننــي أعانــي مــن مــرض نفســي منــذ أربــع‬\n‫ســنوات) كمــا وجــد فيــه‪ ( :‬س‪ /‬أنــت متهــم بســرقة شــيكات مــن إدارة‬\n‫معــرض وتدويــن أحدهمــا باســمك وتوقيعــه تزويــرا وصرفــه مببلــغ مائــة‬\n‫وثمانــن ألــف ريــال وصــرف آخــر بعــد تدوينــه لصاحلــك وتوقيــع صاحــب‬\n‫الشــيك تزويــرا مببلــغ مائــة وســتني ألــف ريــال فمــا قولــك ؟ ج‪ /‬نعــم‬\n‫صحيــح‪ .‬س‪ /‬كيــف حصلــت عليهــا؟ ج‪ /‬توقفــت عنــد صــاة املغــرب‬\n‫بالغــرب مــن مؤسســة ودخلــت املؤسســة لكــي أتوضــأ وكان مكتــب‬\n‫احملاســب مفتوحــا فدخلــت وأخــذت الشــيكات وأذكــر أن عددهــا‬\n‫عشــرة فصرفــت منهــا اثنــن وباقــي الشــيكات وضعتهــا بالبيــت‪ .‬س‪/‬‬\n‫اســتعنت للكشــف عــن احلســاب وهــل يغطــي أم ال؟ ج‪ /‬اســتعنت باملدعــو‬\n‫لكشــف حســاب ‪ ...‬وقــدم لــي خدمــة شــخصية وال عالقــة لــه باملوضــوع‬\n‫أمــا بحســابات ‪ ...‬لــم أســتطع كشــف احلســاب مــع أننــي ســألت أكثــر‬\n‫مــن واحد)‪.‬وهــذا اإلقــرار مصــدق عليــه مــن احملكمــة اجلزائيــة ببريــدة‬\n‫ونصــه‪( :‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق‬\n‫‪1430/11/16‬ه ـ وبعــد نهايــة الــدوام الرســمي ويف مكتبــي باحملكمــة‬\n‫اجلزئيــة ببريــدة ويف الســاعة الثانيــة ظهــرا وخمس وثالثــن دقيقة أحضر‬\n‫وجــرى تــاوة األوراق مــن الصفحــة (‪ )1‬حتــى الصفحــة (‪ )5‬علــى املقــر‬\n‫فصــادق عليهــا بطوعــه واختيــاره وهــو مــدرك للزمــان واملــكان ولــذا‬\n‫جــرى املصادقــة عليــه الســاعة الثانيــة والدقيقــة خمــس وثالثــن وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن قالــه القاضــي‬\n‫باحملكمــة اجلزئيــة ببريــدة‪ .‬املقــر مبــا فيــه توقيعــه كاتبــه الواصــل‬\n\n\n                                                                                ‫‪206‬‬\n\f      ‫توقيعــه القاضــي باحملكمــة اجلزئيــة ببريــدة ختمــه وتوقيعــه) وبعرضــه‬\n      ‫عليــه قــال مــا جــاء فيــه غيــر صحيــح كمــا وجــد علــى الصفحــة رقــم‬\n      ‫(‪ )3،2،1‬إقــرار منســوب للمدعــى عليــه وهــي عبــارة عــن وقائــع ونصهــا‪:‬‬\n      ‫(الواقعــة احلاديــة عشــرة‪ :‬قمــت بســرقة شــيكات مــن معــرض مــن‬\n      ‫معرضه ‪ ،...‬وزورت التوقيع على أحد الشــيكات‪ ،‬وكتبته مببلغ مائة‬\n      ‫وثالثــة عشــرة ألــف ريــال لصالــح معــرض بالدمــام‪ ،‬وأودعتــه يف حســابه‬\n      ‫بعــد أن اشــتريت منهــم ‪ ،...‬ثــم رجعــت إلــى وطلبــت إقالتــي مــن البيعــة‬\n      ‫فأعطانــي شــيكا باملبلــغ وكنــت يف الواقعــة منتحــا شــخصية‪.......‬‬\n      ‫الواقعــة الثانيــة عشــرة‪ :‬قمــت بأخــذ شــيك مــن معــرض وزورت توقيعــه‪،‬‬\n      ‫وكتبتــه وصرفتــه لصاحلــي‪ ،‬مببلــغ مائــة وثمانيــة وثالثــن ألــف ريــال‪.‬‬\n      ‫كمــا قمــت بأخــذ شــيك مــن معــرض ‪ ،‬ودونتــه مببلــغ وقــدره ثمانيــة‬\n      ‫وأربعــن ألــف‪ ،‬بعــد أن زورت توقيعــه‪ ،‬باســم املســتفيد‪ :‬الــذي أنتحــل‬\n      ‫شــخصيته‪ ،‬وصرفتــه نقــدا مبوجــب البطاقــة التــي أحملهــا) وبعرضهــا‬\n      ‫عليــه قــال مــا جــاء فيــه غيــر صحيــح فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة واالطــاع علــى املعاملــة ومنهــا الصــك الصــادر مــن احملكمــة‬\n      ‫اجلزائيــة برقــم ‪ 2/248‬يف ‪1431/5/21‬ه ـ واملصــدق مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪/137‬ج ‪ /2‬أ يف ‪1432/2/15‬ه ـ واالطــاع‬\n      ‫علــى القــرار الصــادر مــن ديــوان املظالــم برقــم ‪1432/7/6/84‬ه ـ ومبــا‬\n      ‫أن املدعــى عليــه أقــر واإلقــرار حجــة علــى مــن أقــر وال عــذر ملــن أقــر‪،‬‬\n      ‫ملــا ســبق كلــه فقــد حكمــت علــى املدعــى عليــه وألزمتــه بســداد املبلــغ‬\n      ‫املدعــى بــه وقــدره ثالثمائــة وأربعــون ألــف ريــال للمدعــي حــاال وبعــرض‬\n      ‫احلكــم عليــه قــرر عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة‬\n      ‫اعتراضيــة فأجيــب لطلبــه وجــرى تزويــده بنســخة مــن احلكــم لتقــدمي‬\n\n\n‫‪207‬‬\n\f‫الالئحــة االعتراضيــة وأفهــم أن لــه مــدة ثالثــن يومــا مــن تاريــخ اليــوم‬\n‫‪1434/4/22‬ه ـ بعدهــا يســقط حقــه يف االعــراض ففهــم ذلــك وبــاهلل‬\n‫الوفيــق ‪.‬وصلــى اهلل وســلم علــى نبيينــا محمــد حــرر يف ‪1434/4/22‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ويف‬\n‫يــوم األربعــاء ‪1435/01/03‬ه ـ افتتحــت اجللســة وقــد وردتنــي املعاملــة‬\n‫مــن محكمــة االســتئناف بالقصيــم رفــق خطــاب فضيلــة رئيســها رقــم‬\n‫‪ 342293524‬يف ‪1434/11/27‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 34/2293524‬يف ‪1434/12/02‬ه ـ واملرفــق بهــا قــرار الدائــرة احلقوقية‬\n‫الثانيــة مبحكمــة االســتئناف رقــم ‪ 34363824‬يف ‪1434/11/19‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم الصــادر منــي برقــم ‪ 34194629‬يف‬\n‫‪1434/04/22‬ه ـ واهلل املوفــق ولــذا جــرى إثباتــه والتهميــش مبوجبــه‬\n‫علــى الضبــط وســجل الصــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                  ‫نبيينــا محمــد حــرر يف ‪1435/01/03‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":203,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c2d095fd3b34349efccf5e2030f40105e7825d5be3d3e360ddf131f1d0a53afb","normalized_text_hash":"9dcc1f02d1cd881ee895561a84753e48485b9530b51da8912dc02253b5a4be56","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p203-34194629"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"20900b20-9128-597b-aad5-1aa1bdcac7eb","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -اعتراف املتهمني على بعضهم جائز إذا لم يدفع الواحد منهم عن نفسه الضرر- إقرار بعض املتهمن دون البعض -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى .","document_number":"3436738","case_number":"33442161","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"مطالبة برد مسروق -اشتراك يف سرقة من منزل -اعتراف املتهمني على بعضهم جائز إذا لم يدفع الواحد منهم عن نفسه الضرر- إقرار بعض املتهمن دون البعض -عدم قبول الرجوع عن اإلقرار بحق آلدمي -قبول قول املدعي مع ميينه -ثبوت الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/2/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3436738 :‬‬\n                         ‫َر ْق ُم الدعوى‪33442161:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34221040‬تاريخه‪1434/5/25:‬هـ‬\n\n\n      ‫مطالبة برد مســروق ‪ -‬اشــتراك يف ســرقة من منزل ‪ -‬اعتراف املتهمني‬\n      ‫علــى بعضهــم جائــز إذا لــم يدفــع الواحــد منهــم عــن نفســه الضــرر‪-‬‬\n      ‫إقــرار بعــض املتهمــن دون البعــض‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار‬\n              ‫بحــق آلدمــي‪ -‬قبــول قــول املدعــي مــع ميينــه ‪ -‬ثبــوت الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا أســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                          ‫حكمه ‪.‬‬\n\n\n\n\n      ‫ادعى املدعي بأن املدعى عليهم اشــتركوا يف ســرقة ذهب ومجوهرات‬\n      ‫ومبالــغ ماليــة مــن منزلــه ؛ وطلــب إلزامهــم بإعــادة املســروقات أو تســليمه‬\n      ‫قيمتهــا ‪ -‬أنكــر املدعــى عليهــم دعــوى املدعــي جتاههــم جملــة وتفصيال‬\n      ‫‪ -‬املدعــى عليهــم لهــم إقــرارات مصدقــة شــرعا بالســرقة ‪ -‬مــن املقــرر‬\n      ‫شــرعا أن املــرء مؤاخــذ بإقــراره وأن اليمــن تشــرع يف جانــب أقــوى‬\n      ‫املتداعيــن ‪ -‬قــررت احملكمــة توجيــه اليمــن إلــى املدعــي عليــه علــى‬\n      ‫صحــة دعــواه فأداهــا طبــق مــا طلــب منهــا ‪ -‬قضــت احملكمــة بإلــزام‬\n      ‫املدعــى عليهــم بتســليم املدعــي قيمــة املســروقات علــى أن تــوزع بينهــم‬\n      ‫بالتســاوي ولــكل واحــد منهــم الرجــوع علــى االخــر مبــا يعتقــد انــه اخــذ‬\n‫‪163‬‬\n\f‫زيــادة مــن قيمــة املســروقات ‪ -‬عــارض املدعــى عليهــم علــى احلكــم ‪-‬‬\n                  ‫قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمة العامة باملدينة‬\n‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة باملدينــة املنــورة برقــم ‪ 33442161‬وتاريــخ ‪1433/07/02‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331224190‬وتاريــخ ‪1433/6/30‬ه ـ حضــر‬\n‫‪ /‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى علــى كل مــن ‪/‬‬\n‫ســعودي بالســجل املدني رقم ‪ /‬ســعودي بالســجل املدني رقم ‪ /‬ســعودي‬\n‫بالســجل املدنــي رقــم مبوجــب اإلقامــة رقــم قائــا بانهــم قامــوا بســرقة‬\n‫منزلــي الواقــع يف حــي الهجــرة عــن طريــق كســر األبــواب الرئيســية‬\n‫وأبــواب الغــرف اخلاصــة بغــرف النــوم وقامــوا بســرقة ذهــب تقــدر قيمتــه‬\n‫بأربعمائــة ألــف ريــال منهــا أربعــن جنيــه ذهــب ســعودي وســرقة مبلــغ‬\n‫مائــة وخمســة وســبعني ألــف ريــال نقــدا وكذلــك مبلــغ ســتة عشــر‬\n‫ألــف دوالر امريكــي ومنهــا ســرقة خــوامت ياقــوت واملــاس ذكــرى‬\n‫مــن الوالــد تقــدر قيمتهــا ســبعني ألــف ريــال وقيمــة إصــاح األبــواب‬\n‫التــي قامــوا بتكســيرها مبلــغ أربعــة االف ريــال اطلــب احلكــم عليهــم‬\n‫بإعــادة املســروقات او قيمتهــا التــي ذكرتهــا بدعــواي هكــذا ادعــى‬\n‫وقــد حضــر مــن املدعــى عليهــم الســجني املدعــو ‪ /‬وبســؤاله اإلجابــة‬\n‫علــى الدعــوى أجــاب قائــا بــان مــا ذكــره املدعــي غيــر صحيــح إطالقــا‬\n‫واملنــزل دخــل بــه ‪ /‬أمــا أنــا فقــد كنــت معهــم يف الســيارة ولــم اعلــم‬\n‫بانهــم يريــدون الســرقة وملــا نزلــوا مــن الســيارة بقيــت بالســيارة عندمــا‬\n\n                                                                                    ‫‪164‬‬\n\f      ‫خرجــوا باملســروقات وهــى عبــارة عــن شــنطة صغيــرة وشــنطة مكيــاج‬\n      ‫وبهــا علــب الذهــب وقــد تقاســموا املســروقات ببيــت ‪ /‬ولــم يعطونــي منهــا‬\n      ‫شــئيا وهــذا مثبــت يف محاضــر البحــث اجلنائــي هكــذا قــرر وإلحضــار‬\n      ‫بقيــة املتهمــن والرجــوع إلــى اوراق املعاملــة لرصــد مــا يوجــد بهــا مــن‬\n      ‫اثباتــات رفعــت اجللســة ثــم حضــر املدعــي وحضــر مــن املدعــى عليهــم‪/‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ /‬ســعودي بالســجل املدنــي رقــم وبتــاوة‬\n      ‫الدعــوى عليهمــا قــرر قائــا بــان مــا ذكــره املدعــي يف دعــواه غيــر‬\n      ‫صحيــح إطالقــا هكــذا قــرر وللرجــوع إلــى أوراق املعاملــة لرصــد مــا‬\n      ‫يوجــد بهــا مــن اثباتــات وإحضــار ‪ /‬رفعــت اجللســة ثــم حضــر املدعــي‬\n      ‫وحضــر مــن املدعــى عليهــم ‪ /‬ســعودي بالســجل املدنــي رقــم وبســؤال‬\n      ‫املدعــي قــرر قائــا بــان مــا جــاء بهــا غيــر صحيــح هكــذا قــرر وبالرجــوع‬\n                                ‫إلــى اعتــراف ‪ /‬وجــد هــذا نصــه ‪:‬ـ الثالــث عشــر ‪:‬‬\n      ‫يف إجــازة عيــد األضحــى املاضــي قمــت إنــا ومعــي كال مــن املدعــو‬\n      ‫‪ /‬واملدعــو ‪ /‬واملدعــو ‪ ....‬بســرقة فيــا مبخطــط ‪ ....‬خلــف مغاســل ‪....‬‬\n      ‫للســيارات حيــث ذكــرا لنــا املدعــو‪ /‬بــأن صديقتــه اإلندونيســية ‪....‬‬\n      ‫كانــت تعمــل مبشــغل مجــاور للفيــا وإنهــا تعــرف اخلادمــة املنزليــة التــي‬\n      ‫تعمــل بنفــس الفيــا وذكــرت لهــم اخلادمــة بأنهــم ســافروا إلــى محافظــة‬\n      ‫جــده وقــال بــأن ‪ ....‬تقــول إن الفيــا مليــان وفعــا اجتهنــا للفيــا وقــت‬\n      ‫أذان الفجــر بســيارتي ‪ ....‬ونزلنــا عنــد املغســلة مــن اخللــف ونقــز وفتــح‬\n      ‫البــاب ونــزل ومعــه عتلــة وراح وبعدهــا نزلــت أمــام الفيــا ورحــت بعيــد‬\n      ‫عــن الفيــا وكانــوا جميعهــم البســن قفــازات الف شــال علــى وجهــه‬\n      ‫داخــل احلــوش داخــل الفيــا وكان قلــق جــدا ويتصــل علــي كل دقيقــه‬\n      ‫ويذكــر بــان العيــال تأخــروا وبعــد حوالــي ســاعتني وأكثــر اتصــل وقــال‬\n\n\n‫‪165‬‬\n\f‫تعــاال عنــد البــاب ورحــت لهــم وخرجــوا مــن الفيــا وكانــا مــع كيــس‬\n‫كبيــرا بــه جميــع املســروقات واجتهنــا إلــى بيــت‪ /‬وقــام بتوزيــع الذهــب‬\n‫علــى حــده واالكسســورات علــى حــده وأعطانا منها طقــم ذهب وأعطى‬\n‫خــوامت وباقــي الذهــب وزعهــا أجــزاء اخلــوامت يف كيــس والبناجــر يف‬\n‫كيــس والسالســل يف كيــس ويف اليــوم التالــي طلعــت إنــا وزوجتــي يف‬\n‫ســيارتي حملافظــة جــده و وزوجتــه يف ســيارته حملافظــة جــده وتقابلنــا‬\n‫وســكنا يف فنــدق قريــب مــن ســوق ‪ ....‬وثانــي يــوم الصبــاح وذهبــت انــا‬\n‫وزوجــة‪ /‬إلــى الســوق لبيــع الذهــب وقامــت زوجــة ‪ /‬ببيــع الذهــب كامــا‬\n‫وال أعلــم كــم مبلــغ الذهــب الــذي باعتــه وأعطانــي نصيبــي تســعة أالف‬\n‫وأعطــى ‪ ....‬تســعة أالف نصيبــه حيــث طلــب ‪ ....‬مــن ‪ ....‬إن يعطــي املبلــغ‬\n‫ألخيــه ‪ .‬كمــا جــرى االطــاع علــى محضــر االســتدالل املذكــور وهــذا‬\n‫نصــه ‪ :‬الثالثــة عشــر ‪ :‬ثــم طلــب الســجني املذكــور التوجــه الــى مخطــط‬\n‫‪ ....‬وقــام بالداللــة واالرشــاد علــى احــدى الفلــل الواقعــة خلــف مغســلة ‪....‬‬\n‫واتضــح ان املنــزل عائــد للمدعــو‪ /‬وذكــر بــان الســرقة كانــت اثنــاء‬\n‫صــاة الفجــر قبــل شــهرين تقريبــا حيــث قامــت املــرأة‪ .... /‬اإلندونيســية‬\n‫بداللتهــم علــى املنــزل حيــث كانــت تعمــل يف الفلــة املجــاورة للفيــا‬\n‫املســروقة وقامــت باالتصــال علــى ‪ /‬وأشــارت لــه مــن فــوق الســطح علــى‬\n‫الفيــا العائــدة وذكــر بــأن املشــاركني لــه يف هــذه الســرقة كال مــن‬\n‫واملرأة ‪ .... /‬االندونيســية والتي قامت بداللتهم على املنزل وأن الســيارة‬\n‫املســتخدمة يف هــذه الســرقة هــي ‪ ....‬اللــون ابيــض ‪2006‬م مســتأجرة‬\n‫مــن مكتــب ‪ ....‬كمــا جــرى االطــاع علــى اعتــراف ‪ /‬وهــذا نصــه ‪:‬ـ‬\n‫‪ -44‬يف اجــازة عيــد االضحــى مــن عــام ‪1428‬ه ـ قمــت ومعــي ‪ /‬بالتوجــه‬\n‫علــى ســيارة مــن نــوع ‪ ....‬عائــده للمدعــو ‪ /‬وكان الوقــت حوالــي الســاعة‬\n\n\n                                                                                      ‫‪166‬‬\n\f      ‫ا وعندمــا وصلنــا للفيــا الواقعــة مبخطــط ‪ ....‬خلــف‬        ‫احلاديــة عشــر لي ـ ً‬\n      ‫ســوبر ماركــت ‪ ....‬قمــت بالنــزول مــن الســيارة وقمــت بالقفــز مــع ســور‬\n      ‫الفيــا بعــد أن قــام املدعــو ‪ /‬ومتكنــت مــن فتــح بــاب العمــارة اخلارجــي‬\n      ‫وبعــد ذلــك قــام بدخــول الفيــا وانــا ذهبــت وأوقفــت الســيارة بعيــد ًا عــن‬\n      ‫املنــزل ثــم عــدت لهــم ودخلــت املنــزل معهــم وكنــت أقــوم بــدور املراقبــة‬\n      ‫مــن حــوش العمــارة ومعــي ‪ /‬بينمــا قــام ‪ /‬بدخــول الفيــا ‪ .‬ومعهــم مفتــاح‬\n      ‫عجــل اســتخدموه بفــرز االبــواب الداخليــة للفيــا وبعــد نصــف ســاعة‬\n      ‫تقريب ـ ًا خــرج مــن الفيــا ومعهــم شــنطة دراســية صغيــرة بهــا مجموعــة‬\n      ‫مــن علــب املجوهــرات ومعهــم كذلــك كيــس ملــيء باملجوهــرات وبعــد‬\n      ‫ذلــك خرجنــا جميعــا مــن املنــزل وركبنــا الســيارة ‪ ....‬العائــدة وقامــوا‬\n      ‫بإنزالــي عنــد ســيارتي الواقعــة باجلــرف ولــم يعطونــي نصيبــي مــن هــذه‬\n      ‫الســرقة ‪ .‬كمــا جــرى االطــاع علــى محضــر االســتدالل ‪ ....‬املذكــور‬\n      ‫الــذي هــذا نصــه ‪ -1 :‬قــام املتهــم ‪ ....‬بالداللــة واإلرشــاد علــى منــزل يقــع‬\n      ‫مبخطــط ‪ ....‬خلــف أســواق ‪ ....‬واتضــح بــأن املنــزل للمدعــو ‪ /‬وقــد ذكــر‬\n      ‫املتهــم بــأن األشــخاص الذيــن شــاركوه يف الســرقة كال مــن املدعــو ‪/‬‬\n      ‫واملدعــو ‪ ./‬كمــا جــرى االطــاع علــى اعتــراف ‪ /‬وهــذا نصــه ‪-1 :‬قبــل‬\n      ‫شــهرين تقريبــا قمــت ومعــي كال مــن املدعــو ‪ /‬واملدعــو ‪ /‬واملدعــو ‪/‬‬\n      ‫بســرقة فيــا تقــع يف مخطــط ‪ ....‬حيــث توجهنــا الــى الفيــا علــى ســيارة‬\n      ‫مــن نــوع ‪ ....‬وكان ذلــك الســاعة الرابعــة فجــرا تقريبــا واذكــر انــه عنــد‬\n      ‫وصولنــا إلــى الفيــا قــام ‪ ....‬بالقفــز إلــى داخــل الفيــا وفتــح لنــا البــاب‬\n      ‫الرئيســي ثــم قمــت أنــا بدخــول الفيــا وكان‪ /‬يرتديــان قفــازات علــى‬\n      ‫أيديهــم ومعهــم كذلــك (عتلــه) وقــام بكســر البــاب الداخلــي للفيــا‬\n      ‫بواســطة العتلــة بينمــا كنــت أنــا أقــوم بــدور املراقبــة مــن داخــل حــوش‬\n\n\n‫‪167‬‬\n\f‫الفيــا وقــام بالدخــول الــى داخــل الفيــا وبعــد ســاعتني تقريبــا خــرج‬\n‫مــن داخــل الفيــا وكان يحمــل شــنطة كبيــرة ســوداء اللــون وكذلــك‬\n‫كيــس كان يحمــل شــنطة زرقــاء اللــون ثــم قــام باالتصــال علــى ‪/‬‬\n‫وطلــب منــه احضــار الســيارة امــام العمــارة وعنــد حضــور ‪ /‬خرجنــا‬\n‫مــن الفيــا وركبنــا مــع ومعنــا األكيــاس وتوجهنــا إلــى منــزل املدعــو‪/‬‬\n‫وقــام بإحضــار صحــن وســكب فيــه مــادة الكلوركــس وأخــذ يخــرج‬\n‫املجوهــرات قطعــة قطعــة ويقــوم بغمســها يف الكلوركــس ملعرفــة‬\n‫الذهــب مــن االكسســوار وقــام بتعبئــة الذهــب يف اربعــة اكيــاس‬\n‫(اكيــاس فحــم ) واتفقنــا ان يذهــب مــع ‪ /‬عائلتــه مــع ‪ /‬عائلتــه الــى‬\n‫جــدة لتصريــف الذهــب هنــاك وفعــا ذهبــا الــى هنــاك وقامــوا هنــاك‬\n‫بتصريــف الذهــب وبيعــه وبعــد اربعــة ايــام تقريبــا اتصــل علــي املدعــو‪/‬‬\n‫وقــال لــي لقــد بعــت الذهــب ونصيبــك مــن البيعــة تســعة االف ريــال‬\n‫(‪ )9000‬وفعــا قــام بإعطائــي هــذا املبلــغ ‪ .‬كمــا جــرى االطــاع علــى‬\n‫محضــر االســتدالل املذكــور الــذي هــذا نصــه ‪:‬ـ ‪/1‬قــام املذكــور‬\n‫بالداللــة علــى فيــا واقعــه مبخطــط ‪ .....‬خلــف مغســلة ‪ .....‬واتضــح بأنهــا‬\n‫فيــا املدعــو ‪ /‬والتــي تعرضــت للســرقة وقــام بالبالغ لدى مركز شــرطة‬\n‫قبــاء وذكــر املتهــم بــان الــذي شــاركه يف الســرقة كال مــن املدعــو ‪/‬‬\n‫واملدعــو ‪ /‬والــذي قــام بالداللــة علــى املنــزل املــرأة ‪ /‬إندونيســية اجلنســية‬\n‫‪.‬ا ‪0‬ه ـ ثــم ســألت عــن اعترافهــم املســجل شــرعا فقــررا كل واحــد منهما‬\n‫قائــا بــان مــا جــاء يف االعتــراف غيــر صحيــح هكــذا قــرر ثــم ســألت‬\n‫املدعــي مــا نــوع جنيــه الذهــب فقــرر قائــا بأنــه جنيــه ذهــب ســعودي‬\n‫ثــم قــرر قائــا باننــي قــد ذكــرت يف دعــواي أن قيمــة الذهــب اجمــاال‬\n‫مبلــغ اربعمائــة الــف ريــال ولكــن حصــل خطــأ يف الكتابــة ومســتعد‬\n\n\n                                                                                       ‫‪168‬‬\n\f      ‫باحللــف علــى صحــة مــا ادعيــت بــه هكــذا قــرر) ثــم ســألت املدعــي كــم‬\n      ‫تســاوي قيمــة اجلنيهــات الذهــب فقــرر قائــا بــان قيمــة جنيــه الذهــب‬\n      ‫يف ذلــك الوقــت تقــارب ســتمائة ريــال أمــا اآلن فهــو فــوق األلــف ريــال‬\n      ‫ســعودي وال مانــع لــدي مــن احتســاب قيمــة اجلنيهــات مبــا اشــتريته بــه‬\n      ‫تقريبــا وضمــه إلــي قيمــة الذهــب األخــرى ليصبــح اإلجمالــي اربعمائــة‬\n      ‫ألــف ريــال ســعودي هكــذا قــرر ثــم ســالته هــل يحلــف علــى صحــة مــا‬\n      ‫ادعــى بــه فقــال نعــم فعرضــت عليــه اليمــن التالــي نصهــا ( واهلل العظيــم‬\n      ‫ان منزلــي الواقــع يف مخطــط ‪ .....‬بجــوار صيدليــة ‪ .....‬تعــرض للســرقة‬\n      ‫وان قيمــة املســروقات هــي كمــا يلــي ذهــب تعــادل قيمتــه اربعمائــة ألــف‬\n      ‫ريــال ســعودي وكذلــك ســتة عشــر ألــف دوالر امريكــي ومبلــغ مائــه‬\n      ‫وخمســة وســبعني ألــف ريــال نقــدا وإصــاح االبــواب مــن الســرقة مببلــغ‬\n      ‫اربعــة االف ريــال واهلل العظيــم ) فحلفهــا علــى الوجــه املســطور بعاليــه‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وعلــى اعترافــات بعــض‬\n      ‫املدعــى عليهــم وكذلــك محاضــر االســتدالل وحيــث أن شــهادة بعــض‬\n      ‫املتهمــن علــى بعــض مقبولــة خاصــة وان املدعــى عليهــم يعتبــرون عصابــه‬\n      ‫مــع مجموعــة أخــرى حصــل منهــا ســرقات كثيــرة ممــا يــدل علــى صحــة‬\n      ‫الدعــوى اجتــاه اجلميــع وحيــث ان املدعــى قــد حلــف اليمــن الالزمــة‬\n      ‫لصحــة دعــواه لــذا كلــه فقــد ثبــت لــدي حصــول ســرقة بيــت املدعــي‬\n      ‫وتقــدر قيمــة املســروقات كمــا جــاء بدعــوى املدعــي لــذا كلــه فقــد‬\n      ‫الزمــت كل مــن ‪ /‬اجلنســية بدفــع مبلــغ خمســمائة وتســعة وســبعني الــف‬\n      ‫ريــال ســعودي وكذلــك ســتة عشــر الــف دوالر امريكــي للمدعــي تــوزع‬\n      ‫بينهــم بالتســاوي ولــكل واحــد منهــم الرجــوع علــى االخــر مبــا يعتقــد‬\n      ‫انــه أخــذ زيــادة مــن قيمــة املســروقات وبــه حكمــت وابلغــت كل مــن‬\n\n\n‫‪169‬‬\n\f‫ذلــك فقــرر كل واحــد منهــم عــدم القناعــة باحلكــم وجــرى تســليم كل‬\n‫واحــد منهمــا صــورة مــن صــك احلكــم لتقــدمي اعتراضــه عليــه يف مــدة‬\n‫ثالثــن يومــا وافهــم كل واحــد منهمــا بانــه اذا انتهــت مــدة االعتــراض‬\n‫ولــم يقــدم اعتراضــه فــان حقــه يف االعتــراض وطلــب االســتئناف يعتبــر‬\n‫ســاقطا فقــال كل واحــد منهمــا فهمــت ذلــك وامــرت ببعــث صــورة مــن‬\n‫صــك احلكــم إلــى الســجني ‪ /‬اجلنســية لتقــدمي اعتراضــه عليــه يف مــدة‬\n‫ثالثــن يومــا مــن تاريــخ اســتالمه لصــورة صــك احلكــم وصلــى اهلل علــى‬\n            ‫ســيدنا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/2/12‬ه ـ ‪.‬‬\n‫فبعــد رفــع صــك احلكــم رقــم ‪ 3436738‬يف ‪1434/2/13‬ه ـ املتعلــق‬\n‫بدعــوى ضــد ورفقــاه عــاد مصدق ـ ًا مــن محكمــة االســتئناف بقرارهــم‬\n‫رقــم ‪ 34221040‬يف ‪1434/5/25‬ه ـ وهــذا نصــه ‪ :‬احلمــد هلل والصــاة‬\n‫والســام علــى رســول اهلل وبعــد نحــن رئيــس وقضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى‬\n‫االطــاع منــا علــى الصــك رقــم ‪ 3436738‬يف ‪1434/2/13‬ه ـ الصــادر‬\n‫مــن فضيلــة الشــيخ القاضــي باحملكمــة العامــة باملدينــة املنــورة املتضمــن‬\n‫دعــوى املدعــي ضــد ورفقاه املتهمني بســرقة منــزل املدعي احملكوم فيه‬\n‫مبــا دون باطنــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه واللوائــح االعتراضيــة‬\n‫تقــررت املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق ‪ .‬حــرر يف ‪1434/7/3‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪170‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":163,"source_page_end":170,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3295af0928725240d778d208550811e506b300dbd8be69a9e73ddba41fa0cf45","normalized_text_hash":"925fb27b0b495aa6fe4d1f55dc0d7e4448725aa05ad4793ddb2404c4b1be782a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p163-3436738"},{"id":"66dcbc9f-3b3c-56b4-b932-2e63e4c49001","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -االقرار باستالم الذهب ومبلغ مالي مقابل املبالغ احملولة من حساب املدعي -احلكم بدفع املبلغ املدعى به -إفهام بالرجوع على من","document_number":"33451680","case_number":"33452309","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض ف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/13","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -االقرار باستالم الذهب ومبلغ مالي مقابل املبالغ احملولة من حساب املدعي -احلكم بدفع املبلغ املدعى به -إفهام بالرجوع على من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/13 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33451680 :‬‬\n                           ‫َر ْق ُم الدعوى‪33452309:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3410255‬تاريخه‪1434/1/12:‬هـ‬\n\n\n       ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف ‪ -‬االقــرار‬\n       ‫باســتالم الذهــب ومبلــغ مالــي مقابــل املبالــغ احملولــة مــن حســاب‬\n       ‫املدعــي ‪ -‬احلكــم بدفــع املبلــغ املدعــى بــه ‪ -‬إفهــام بالرجــوع علــى مــن‬\n                                                                               ‫غــره ‪.‬‬\n\n\n\n\n       ‫مــا اســتند اليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n       ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه قــام بالتحايــل علــى موكلــه‬\n       ‫بانتحــال شــخصية موظــف يف أحــد املصــارف ثــم قــام بتحويــل مبالــغ‬\n       ‫ماليــة مــن حســابات موكلــه إلــى أحــد متاجــر الذهــب وقبــض مقابلهــا‬\n       ‫كميــة مــن الذهــب لصالــح نفســه ؛ ولــذا فقــد طلــب إلزامــه بتســليم‬\n       ‫موكلــه تلــك املبالــغ ‪ -‬أقــر املدعــى عليــه باســتالم الذهــب املذكــور‬\n       ‫يف الدعــوى وباقــي املبلــغ الــذي مت حتويلــه ودفــع بأنــه فعــل ذلــك لصالــح‬\n       ‫أحــد مرافقــي أخيــه بالســجن وأنــه ســلم الذهــب لشــخص آخــر بنــاء علــى‬\n       ‫طلبــه ولــم يكــن يعلــم بأنــه مت االحتيــال علــى املدعــي لســرقة مبالــغ‬\n       ‫ماليــة مــن حســاباته ‪ -‬املدعــى عليــه أقــر باســتالم الذهــب املذكــور‬\n\n‫‪171‬‬\n\f‫يف الدعــوى وباقــي املبلــغ الــذي مت حتويلــه ‪ -‬قضــت احملكمــة بإلــزام‬\n‫املدعــى عليــه بتســليم املدعــي أصالــة املبلــغ املدعــى بــه وإفهامــه بــأن لــه‬\n‫الرجــوع علــى مــن غــره إن كان صادق ـ ًا فيمــا ادعــاه ‪ -‬عــارض املدعــى‬\n‫عليــه علــى احلكــم‪ -‬قــررت محكمــة االســتئناف باألكثريــة املصادقــة‬\n                                                                    ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض ففــي يــوم الســبت املوافــق‪ 1433/11/13‬ه ـ حضــر حامــل‬\n‫الســجل املدنــي رقــم‪ :‬بالوكالــة عــن ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ 1001424843‬مبوجــب الوكالــة الصــادرة من كتابة عدل‬\n‫اخلبــراء ورياضهــا برقــم‪ 2844 :‬يف ‪1432/6/28‬ه ـ والتــي تخوله املطالبة‬\n‫واملرافعــة واملدافعــة واملخاصمــة وتقــدمي الدعــوى والبينــات‪ ،‬وســماع‬\n‫الدعــوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح‪ ،‬وقبــول احلكــم أو‬\n‫االعتــراض عليــه‪ ،‬وطلــب األميــان وســماعها‪ ،‬وادعــى علــى احلاضــر معــه‬\n‫حامــل الســجل املدنــي رقــم‪ ،..... :‬قائــا يف دعــواه‪ :‬لقــد اتصــل شــخص‬\n‫علــى وزعــم أنــه مديــر الســجالت بــإدارة مصــرف ‪ ...‬وطلــب منــه حتديــث‬\n‫حســاب والــده موكلــي فقــام باالتصــال علــى أخيــه وأعطــاه رقــم املتصــل‬\n‫فاتصــل عليــه ‪ ...‬فطلــب منــه صاحــب الرقــم حتديــث حســاب موكلــي‬\n‫فذهــب ‪ ...‬إلــى الصــراف اآللــي وقــام بعمــل اإلجــراءات التــي طلبهــا‬\n‫منــه املتصــل ويف ‪1432/5/13‬ه ـ تفاجــأ موكلــي بعــدة حــواالت متــت‬\n‫مــن حســاباته لــدى مصــرف ‪ ...‬إلــى عــدة حســابات منهــا حســاب ‪...‬‬\n‫صاحــب محــل ‪ ...‬للذهــب وهــي علــى النحــو التالــي ‪ :‬أربعــة وعشــرون‬\n\n                                                                                        ‫‪172‬‬\n\f      ‫ألــف ريــال مــن حســاب موكلــي رقــم ومبلــغ خمســن ألــف ريــال مــن‬\n      ‫حســاب موكلــي رقــم ومبلــغ خمســة وثمانــن ألــف ريــال مــن حســاب‬\n      ‫موكلــي رقــم ومبلــغ خمســة عشــر ألــف ريــال مــن حســاب موكلــي رقــم‬\n      ‫ومجموعهــا مائــة وأربعــة وســبعون ألــف ريــال ‪ ،‬وبســؤال عــن املبالــغ‬\n      ‫التــي حولــت إلــى حســابه ذكــر أن املدعــى عليــه حضــر إليــه واختــار‬\n      ‫عــدة أطقــم مــن الذهــب وأفــاده أن الثمــن ســوف يــرد إلــى حســابه وبعــد‬\n      ‫تأكــد صاحــب احملــل مــن دخــول املبلــغ إلــى حســابه قــام بتصويــر بطاقــة‬\n      ‫املدعــى عليــه وســلمه الذهــب وكان مببلــغ مائــة واثنــن وســبعني ألفــا‬\n      ‫وخمســمائة ريــال ورد للمدعــى عليــه الباقــي مــن مبلــغ احلــواالت وقــدره‬\n      ‫ألــف وخمســمائة ريــال ‪ ،‬وأطلــب إلــزام املدعــى عليــه بــأن يســلم ملوكلــي‬\n      ‫مائــة وأربعــة وســبعني ألــف ريــال هــذه دعــواي ‪ ،‬وباســتجواب املدعــى‬\n      ‫عليــه قــال ‪ :‬إن ابــن خالتــي كان مســجونا بســجن امللــز وكنــت أحضــر‬\n      ‫لــه أغراضــه التــي يحتــاج إليهــا فأخبرنــي أن معــه أحــد الســجناء اســمه‬\n      ‫فطلــب منــي أن أحضــر األغــراض التــي يحتاجهــا ثــم أصبــح يتواصــل‬\n      ‫معــي عــن طريــق اجلــوال وهــو يف الســجن وأقــوم بقضــاء حاجاتــه ويف أحد‬\n      ‫األيــام اتصــل علــي وطلــب منــي أن أقــوم بشــراء ذهــب وأن اســلمه ألخيــه‬\n      ‫فذهبــت إلــى ســوق ‪ ...‬ودخلــت إلــى أحــد محــات الذهــب فاتصــل وطلــب‬\n      ‫منــي أن أعطيــه صاحــب احملــل فأعطيتــه صاحب احملل وشــاهدت البائع‬\n      ‫يقــوم بإخــراج الذهــب ويضعــه علــى الطاولــة ثــم اتفــق معــه علــى الســعر‬\n      ‫وقــدره مائــة واثنــان وســبعون ألفــا وخمســمائة ريــال وبعــد أن نــزل الثمــن‬\n      ‫يف حســاب صاحــب احملــل أعطانــي صاحــب احملــل املبلــغ الزائــد من مبلغ‬\n      ‫احلــواالت وقــدره ألــف وخمســمائة ريــال ثــم حمــل الذهــب معــي وأركبــه‬\n      ‫يف شــنطة الســيارة ثــم اتصــل علــي ‪ ...‬وأدخلنــي يف مكاملــة جماعيــة مــع‬\n\n\n‫‪173‬‬\n\f‫شــخص آخــر وطلــب منــي أن أقــوم بتســليمه الذهــب وبالفعــل قابلتــه يف‬\n‫شــارع ‪ ...‬بحــي ‪ ...‬وكان يركــب ســيارة ‪ ...‬وارد ‪ ...‬وســلمته الذهــب‬\n‫ا وأعطانــي ثمانيــة آالف وخمســمائة ريــال حيــث إنــه بعــد شــرائي‬   ‫كامـ ً‬\n‫للذهــب قــال لــي بــأن لــي حــاوة ولــم أعلــم بأنــه ســوف يقــوم بإعطائــي‬\n‫هــذا املبلــغ ثــم تبــن لــي بعــد ســبعة أشــهر بعــد قبــض علــي أن املبالــغ‬\n‫التــي حولــت حلســاب صاحــب محــل الذهــب لــم تكــن مــن حســاب‪....‬‬\n‫وإمنــا كانــت مــن حســابات املدعــي أصالــة بطريقــة احتياليــة وال أدري‬\n‫كيــف متــت هــذه العمليــة ‪ ،‬هكــذا أجــاب ‪ ،‬وبعــرض ذلــك علــى املدعــي‬\n‫وكالــة قــال ‪ :‬إن أنكــر مــا ذكــره املدعــى عليــه واملدعــى عليــه هــو‬\n‫الــذي اســتلم الذهــب فأطلــب إلزامــه بتســليم املبلــغ هكــذا قــرر ‪ ،‬فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه أقــر بأنــه‬\n‫اســتلم الذهــب ومبلــغ ألــف وخمســمائة ريــال مقابــل املبالــغ احملولــة مــن‬\n‫حســابات املدعــي أصالــة لــذا فقــد حكمــت علــى املدعــى عليــه بــأن‬\n‫يســلم للمدعــي أصالــة مائــة وأربعــة وســبعني ألــف ريــال وأفهمتــه أن لــه‬\n‫الرجــوع علــى‪ ......‬إن كان صادقــا فيمــا ادعــاه ‪ ،‬وبعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر عــدم القناعــة بــه وطلــب االســتئناف فأجبتــه لطلبــه‬\n‫وقــررت تســليمه صــورة مــن صــك احلكــم حــاال لتقــدمي معارضتــه عليــه‬\n‫خــال مــدة ال تتجــاوز ثالثــن يومــا فــإن تأخــر عــن ذلــك ســقط حقــه‬\n‫يف تقــدمي الالئحــة االعتراضيــة واكتســب احلكــم القطعيــة ‪ ،‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪ 1433/11/13‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/02/05‬ه ـ‬\n‫فتحــت اجللســة الســاعة ‪ 10:45‬وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n\n\n                                                                                    ‫‪174‬‬\n\f      ‫وقــد همــش علــى ظهــر الصــك مبــا نصــه ( تظهيــرات الدائــرة اجلزائيــة‬\n      ‫األولــى مبحكمــة االســتئناف بالريــاض ‪ ،‬احلمــد هلل وحــده وبعــد ‪ :‬فقــد‬\n      ‫اطلعنــا علــى هــذا القــرار رقــم ‪ 33451680‬وتاريــخ ‪1433/11/13‬ه ـ‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة العامــة بالريــاض الشــيخ ‪/‬‬\n      ‫وأصدرنــا القــرار رقــم ‪/3410255‬وتاريــخ ‪1434/01/12‬ه ـ املتضمــن‬\n      ‫أنــه لــم يظهــر لألكثريــة مــا يوجــب املالحظــة علــى احلكــم ‪ ،‬وبــاهلل‬\n      ‫التوفيــق ‪ .‬قاضــي اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف د‪ .‬ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة لــي وجهــة نظــر ختمــه وتوقيعــه ) وكان ختــام‬\n      ‫هــذه اجللســة الســاعة ‪ 11:00‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n          ‫نبينــا محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/02/05‬ه ـ ‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":171,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a8bdb65bcd5106b7ae5c4d625b1dab27872e9cdccc9bb2aabf25db9951fc0358","normalized_text_hash":"f6c003156a804cf363d4ecd6e8e3902fefe12648963ccb76abb21c89566d2131","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p171-33451680"},{"id":"bce6d6ef-8a5e-568b-9f48-7738275803e5","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -نشل مبلغ مالي من اجليب -إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه برد املبلغ املسروق -تنفيذ","document_number":"3410162","case_number":"33532164","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"رد مسروق -نشل مبلغ مالي من اجليب -إثبات بالقرائن مع مين املدعي -احلكم بإلزام املدعى عليه برد املبلغ املسروق -تنفيذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/12 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3410162 :‬‬\n                   ‫َر ْق ُم الدعوى‪33532164:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34197584‬تاريخه‪1434/4/24:‬هـ‬\n\n\n‫رد مســروق ‪ -‬نشــل مبلــغ مالــي مــن اجليــب ‪ -‬إثبــات بالقرائــن مــع‬\n‫ميــن املدعــي‪ -‬احلكــم بإلــزام املدعــى عليــه بــرد املبلــغ املســروق ‪ -‬تنفيــذ‬\n                                                                         ‫احلكــم ‪.‬‬\n\n\n\n\n                                ‫‪ -1‬اليمني تشرع يف جانب أقوى املتداعيني‪.‬‬\n‫‪ -2‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة‬\n                                                        ‫يف تســبيب احلكــم ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي علــى احلاضــر معــه أنــه قــام بنشــل مبلــغ مالــي مــن جيبــه‬\n‫أثنــاء وجــوده يف ســوق األغنــام‪ ،‬وطلــب إلزامــه بإعــادة املبلــغ الــذي نشــله‬\n‫منــه ‪ -‬أنكــر املدعــى عليــه نشــل املبلــغ املذكــور أو مشــاهدة املدعــي يف‬\n‫ســوق األغنــام ‪ -‬املدعــى عليــه أديــن يف حكــم جزائــي ســابق بالشــروع‬\n‫يف نشــل أحــد األشــخاص بنفــس الســوق وعليــه ســابقتا ســرقة ونشــل‬\n‫مســجلة ‪ -‬املدعــي لــم يقــدم بينــة موصلــة تثبــت دعــواه إال أن جانبــه‬\n‫يتقــوى بالقرائــن املذكــورة يف أســباب احلكــم فتشــرع بحقــه اليمــن‬\n‫املكملــة ‪ -‬قضــت احملكمــة بنــاء علــى القرائــن وميــن املدعــي املكملــة‬\n‫بإلــزام املدعــى عليــه بإعــادة املبلــغ املدعــى بــه إلــى املدعــي‪ -‬قنــع املدعــي‬\n                                                                                          ‫‪176‬‬\n\f      ‫باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف‬\n                      ‫املوافقــة علــى احلكــم باألكثريــة ‪ -‬مت تنفيــذ احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمة العامة باملدينة‬\n      ‫املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة باملدينــة املنــورة برقــم ‪ 33532164‬وتاريــخ ‪ 1433/08/18‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331556500‬وتاريــخ ‪ 1433/08/18‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافــق‪ 1433/12/27‬ه ـ حضــر‪ ....../‬مصــري اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم‪ ....‬وأدعــى علــى احلاضــر معــه يف مجلــس احلكــم‬\n      ‫‪ ....../‬مبوجــب اإلقامــة البديلــة برقــم ‪.......‬بقولــه‪ :‬إننــي كنــت متواجــد ًا‬\n      ‫يف ســوق الغنــم باملدينــة بتاريــخ ‪1432/12/7‬ه ـ وكان بحوزتــي وبجيبــي‬\n      ‫األيســر مبلغـ ًا قــدرة واحــد وثالثــون الفـ ًا وخمســون ريــال مــن أجــل شــراء‬\n      ‫أضاحــي وفجــأة فقدتهــا فلتفــت جهــة اليســار فوجــدت هــذا احلاضــر‬\n      ‫املدعــى عليــه وســألته عــن املبلــغ فقــال مــا علــي فيــك فتقدمــت ببــاغ‬\n      ‫لشــرطة املطــار وبعــد حوالــي شــهر ونصــف مت أبالغــي مــن شــرطة‬\n      ‫املطــار بأنــه مت القبــض علــى نشــال يف ســوق الغنــم وطلبــوا منــي احلضــور‬\n      ‫للتأكــد منــه وملــا حضــرت عرضــوا علــي مجموعــة أشــخاص ومــن‬\n      ‫ضمنهــم املدعــى عليــه وال تــزال ذاكرتــي تعــرف املدعــى عليــه ويف‬\n      ‫احلــال أشــرت علــى املدعــى عليــه بأنــه هــو الــذي كان بجانبــي وال أدري‬\n      ‫مــاذا حصــل بعــد ذلــك وأخبرونــي بأنــه هــو الســارق ولــذا فاطلــب احلكــم‬\n      ‫عليــه بدفــع املبلــغ الــذي ســرقه وقــدرة واحــد وثالثــون الفــا وخمســون‬\n      ‫ريــال هكــذا قــرر دعــواه وبعرضــه علــى املدعــى عليــه أنكــر مــا ذكــره‬\n‫‪177‬‬\n\f‫املدعــي جملــة وتفصيــا وقــال أننــي لــم أســرق املبلــغ املذكــور مــن جيــب‬\n‫املدعــي ولــم أشــاهده يف ســوق الغنــم ومــا ذكــره أننــي ســرقت املبلــغ‬\n‫غيــر صحيــح هكــذا أجــاب هــذا وقــد جــرى االطــاع علــى املعاملــة‬\n‫فوجدنــا مــن ضمــن لفاتهــا صــوره مــن القــرار الصــادر مــن احملكمــة‬\n‫اجلزائيــة برقــم ‪ 33202062‬يف ‪1433/4/20‬ه ـ املتضمــن دعــوى‬\n‫املدعــي العــام ضــد املدعــى عليــه مينــي اجلنســية مفادهــا أنــه بتاريــخ‬\n‫‪1432/12/7‬ه ـ تقــدم للجهــة االمنيــة املقيــم مصــري اجلنســية بتعرضــه‬\n‫للنشــل بســوق االغنــام صبــاح اخلميــس ‪1433/12/7‬ه ـ حيــث نشــل منــه‬\n‫مبلــغ قــدرة واحــد وثالثــون الفـ ًا وخمســون ريــال كان يف جنبــه االيســر‬\n‫كمــا أبلــغ املواطــن أنــه أثنــاء تواجــده بســوق األغنــام مــن أجــل شــراء‬\n‫أضاحــي كان بحوزتــه مبلــغ ســبعة وعشــرون ألــف ريــال وأثنــاء احلــراج‬\n‫انشــغل بذلــك ثــم لــم يجــد املبلــغ وبتاريــخ ‪1433/2/12‬ه ـ أبلــغ املواطــن‬\n‫عــن قيــام بإدخــال يــده بجيبــه االيســر مــن اجــل النشــل وعندمــا أحــس‬\n‫بــه قــام بالهــرب داخــل املســلخ وقــام بالتنكــر حيــث قــام برمــي مالبســه‬\n‫ومــن ثــم قــام باإلمســاك بــه وتســليمه الــى دوريــات االمــن وعثــر بحوزتــه‬\n‫علــى بطاقــة احــوال مدنيــة وبعرضــه علــى املدعــو ‪ ...‬أســتطاع التعــرف‬\n‫عليــه وانــه كان بجــواره عندمــا تعــرض للنشــل وباســتجواب املدعــى‬\n‫عليــه اعتــرف بانــه قــام بإدخــال يــده يف جيــب مــن أجــل النشــل وأنــه‬\n‫هــرب فتــم االمســاك بــه وأنتهــى التحقيــق باتهــام املدعــى عليــه بالشــروع‬\n‫يف نشــل أحــد االشــخاص ونشــل مبالــغ ماليــة قــدرة بثمانيــة وخمســون‬\n‫الــف ريــال مــن اشــخاص أخريــن علــى أوقــات متقاربــه كمــا تبــن وجــود‬\n‫ســابقتني عليــه احداهمــا ســرقه واالخــرى نشــل ‪ ....‬الــخ وخلــص حكــم‬\n‫فضيلتــه الــى أثبــات أدانــة املدعــى عليــه اجلنســية بالشــروع يف نشــل أحــد‬\n\n\n                                                                                    ‫‪178‬‬\n\f      ‫االشــخاص واســتعماله لهويــة وطنيــة وتوجــه التهمــه نحــوه مبــا نســب‬\n      ‫اليــه مــن نشــله ملبالــغ ماليــه قدرهــا ثمانيــة وخمســون الــف ريــال مــن‬\n      ‫أشــخاص أخريــن ولعــدم ارتداعــه مبــا ســبق لــه فقــد قــرر تعزيــره بســجنه‬\n      ‫ملــدة ســنه اعتبــارا مــن ‪1433/2/12‬ه ـ وبجلــده خمســة وســبعني جلــده‬\n      ‫تتكــرر عليــه عشــر مــرات ومــن ثــم أبعــاده الــى بــاده وحضــر عودتــه‬\n      ‫مــرة أخــرى وقــد قــرر املدعــى عليــه القناعــة بحكــم فضيلتــه يف حــن‬\n      ‫قــرر املدعــي العــام االعتــراض وصــدق القــرار مــن محكمــة االســتئناف‬\n      ‫مبكــة باألكثريــة برقــم ‪ 33240/495‬يف ‪1433/5/11‬ه ـ أ‪.‬ه ـ حيــث‬\n      ‫احلــال مــا ذكــر فقــد جــرى ســؤال املدعــي هــل لديــه زيــادة بينــه فقــال‬\n      ‫ليــس لــدي ســوى مــا جــاء يف نتيجــة التحقيــق هكــذا أجــاب ونظــر ًا لقــوة‬\n      ‫القرائــن ضــد املدعــى عليــه فقــد جــرى ســؤال املدعــي اليمــن الشــرعية‬\n      ‫علــى دعــواه فقــال أنــا أحلــف أنــه كان بجنبــي أثنــاء فقــد املبلــغ وحلظــة‬\n      ‫فقــد املبلــغ وســألته عــن املبلــغ ولكنــي لــم أســتطع القبــض عليــه حيــث‬\n      ‫كان يلبــس غتــرة حمــراء وعقــال وحســبته ســعودي ولذلــك لــم أســتطع‬\n      ‫القبــض عليــه وقــد تبــن مــن القضايــا االخــرى بانــه كان يلبــس هــذا‬\n      ‫اللبــس مــن اجــل التمويــه وأطلــب إمهالــي الــى االســبوع القــادم ورفعــت‬\n      ‫اجللســة ويف جلســة اخــرى حضــر الطرفــان وقــرر املدعــي اســتعداده‬\n      ‫بــأداء اليمــن علــى انــه حضــر لســوق الغنــم معــه املبلــغ املذكــور وانهــا‬\n      ‫فقــدت منــه وألول وهلــه ســأل املدعــى عليــه عــن املبلــغ وأن املدعــى عليــه‬\n      ‫الصــق النــاس بــه وانــه علــى يقــن مليــون باملائــة علــى ان املدعــى عليــه‬\n      ‫هــو الــذي ســرق املبلــغ املذكــور هكــذا قــرر وحيــث احلــال مــا ذكــر‬\n      ‫ا‬\n      ‫فقــد طلبــت مــن املدعــي اليمــن الشــرعية علــى ذلــك فحلــف قائ ـ ً‬\n      ‫واهلل العظيــم الــذي ال الــه اال هــو عالــم الغيــب والشــهادة أننــي حضــرت‬\n\n\n‫‪179‬‬\n\f‫لســوق الغنــم يف املدينــة يف ســبعة ذي احلجــة عــام ‪1432‬ه ـ ومعــي واحــد‬\n‫وثالثــون الفــا وخمســون ريــال ودخلــت الزحــام واملبلــغ معــي كان املدعــى‬\n‫عليــه هــذا احلاضــر اقــرب النــاس والصــق النــاس بــي وســألته حــال فقــد‬\n‫املبلــغ عــن املبلــغ وواهلل العظيــم انــه يف قــرارة نفســي مليــون باملائــة أن‬\n‫املدعــى عليــه هــو الــذي ســرق املبلــغ منــي واهلل علــى مــا أقــول شــهيد‬\n‫هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع‬\n‫علــى القــرار الشــرعي املشــار اليــه املصــدق مــن محكمــة االســتئناف‬\n‫مبكــة واملنصــوص فيــه بثبــوت أدانــة املدعــى عليــه بالشــروع يف نشــل‬\n‫احــد االشــخاص وتوجهــه التهمــة نحــوه بنشــل مبالــغ ماليــه مــن أشــخاص‬\n‫أخريــن واملشــار فيــه الــى بــاغ املدعــي عــن املدعــى عليــه بســرقة املبلــغ‬\n‫ومــا جــاء يف القــرار مــن وجــود ســابقتي ســرقة ونشــل علــى املدعــى عليــه‬\n‫وملــا جــاء يف نتيجــة التحقيــق مــع املدعــى عليــه لــدى هيئــة التحقيــق مــن‬\n‫اعترافــه مبحاولــة نشــل املجنــي عليــه وشــرائه بطاقــة احــوال وطنيــة‬\n‫والقبــض عليــه باجلــرم املشــهود مــن قبــل املدعــي املنــوه عنــه وتعــرف‬\n‫املجنــي عليــه عندمــا عــرض عليــه ووجــود البطاقــة املدنيــة بحوزتــه‬\n‫عنــد القبــض عليــه وتشــابه االســلوب االجرامــي لــه عــن قيامــه بالنشــل‬\n‫وتقــارب الوقــت بــن بــاغ بنفــس الســوق عنــد الداللــن أثنــاء احلــراج ومــا‬\n‫جــاء مــن عمــل التنكــر مــن املدعــى عليــه اثنــاء القبــض عليــه مــن رمــي‬\n‫مالبســه كل ذلــك ممــا يقــوي جانــب املدعــي وملــا قــرره احملققــون مــن‬\n‫ان اليمــن تشــرع يف جانــب اقــوى املتداعيــن وال ســيما مــع قــوة األدلــة‬\n‫وترادفهــا وتكاثرهــا وتشــابه اعمــال املدعــى عليــه وحيــث أدى املدعــي‬\n‫اليمــن الشــرعية بعاليــه فقــد حكمــت علــى املدعــى عليــه بدفــع املبلــغ‬\n‫املدعــى بــه وقــدره واحــد وثالثــون الفــا وخمســون ريــاال هــذا مــا حكمــت‬\n\n\n                                                                                      ‫‪180‬‬\n\f      ‫بــه فليعلــم وبعرضــه علــى الطرفــن قــرر املدعــي القناعــة وامــا املدعــى‬\n      ‫عليــه فقــرر عــدم القناعــة وقــررت تســليمه صــورة مــن صــك احلكــم‬\n      ‫لتقــدمي االعتراضيــة حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪ 1434/05/20‬ه ـ فقــد‬\n      ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة باخلطــاب‬\n      ‫رقــم‪ 332088894‬يف ‪ 1434/04/30‬ه ـ وبرفقهــا الصــك الصــادر منــا‬\n      ‫برقــم ‪ 3410162‬يف ‪ 1434/01/12‬ه ـ ومظهــر عليــه بالقــرار رقــم‬\n      ‫‪ 34197584‬يف ‪ 1434/04/24‬ه ـ الصــادر مــن الدائــرة اجلزائية الســابعة‬\n      ‫املتضمــن املوافقــة علــى احلكــم باألكثريــة واهلل املوفــق‪ .‬قاضــي‬\n      ‫اســتئناف ‪ ....‬لــي وجهــة نظــر ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه رئيــس اســتئناف د‪ .‬ختمــه وتوقيعــه ‪ .‬وصلــى اهلل وســلم علــى‬\n                                         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــدة وبعــد ففــي هــذا اليــوم األربعــاء املوافــق ‪1434/7/5‬ه ـ‬\n      ‫حضــر لدينــا مصــري اجلنســية مبوجــب اإلقامــة رقــم باملجلــس الشــرعي‬\n      ‫وقــرر لدينــا بأنــه اســتلم الشــيك رقــم ‪ 005201‬يف ‪1434/7/5‬ه ـ‬\n      ‫املســحوب علــى مصــرف ‪ ...‬مببلــغ وقــدرة واحــد وثالثــون ألفـ ًا وخمســون‬\n      ‫ريــال وهــو كامــل املبلــغ املدعــى بــه وبذلــك تكــون القضيــة منتهيــة لــذا‬\n      ‫جــرى إثباتــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                        ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/5‬ه ـ ‪.‬‬\n\n\n\n\n‫‪181‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":176,"source_page_end":181,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"471f7854724b8311add7acaf68aa58920aea450c7598f8084a425ca5ef0f2594","normalized_text_hash":"fa0cbbefd8d9811be4b9e8554e4918eb6c2802973907fefdd5f2576374741298","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p176-3410162"},{"id":"3f2cf1b6-f417-5bed-9ccb-5fd4a82c3d2f","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -تفويض -اجلهات احلكومية يكتفي بالتفويض بخطاب رسمي من صاحب الصالحية -سرقة مستلزمات كهربائية من املال العام -إنكار ملقدار املسروق -بينة غير موصلة -رد مين املدعى عليه على نفي عدد القطع املسروقة -قبول قول الغارم مع ميينه -تفويض يف املرافعة واملخاصمة من صاحب الصالحية -احلكم بإلزام املدعى عليه بدفع قيمة القطع املسروقة الواردة يف معاملة االدعاء العام -رد الدعوى يف غير ذلك.","document_number":"33411618","case_number":"33544297","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/9/13","year":"1434","subject":"رد مسروق -تفويض -اجلهات احلكومية يكتفي بالتفويض بخطاب رسمي من صاحب الصالحية -سرقة مستلزمات كهربائية من املال العام -إنكار ملقدار املسروق -بينة غير موصلة -رد مين املدعى عليه على نفي عدد القطع املسروقة -قبول قول الغارم مع ميينه -تفويض يف املرافعة واملخاصمة من صاحب الصالحية -احلكم بإلزام املدعى عليه بدفع قيمة القطع املسروقة الواردة يف معاملة االدعاء العام -رد الدعوى يف غير ذلك.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/9/13 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33411618 :‬‬\n                    ‫َر ْق ُم الدعوى‪33544297:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34290573‬تاريخه‪1434/8/7:‬هـ‬\n\n\n‫رد مســروق ‪ -‬تفويض ‪ -‬اجلهات احلكومية يكتفي بالتفويض بخطاب‬\n‫رســمي مــن صاحــب الصالحيــة ‪ -‬ســرقة مســتلزمات كهربائيــة مــن‬\n‫املــال العــام ‪ -‬إنــكار ملقــدار املســروق‪ -‬بينــة غيــر موصلــة‪ -‬رد ميــن املدعــى‬\n‫عليــه علــى نفــي عــدد القطــع املســروقة ‪ -‬قبــول قــول الغــارم مــع ميينــه‬\n‫‪ -‬تفويــض يف املرافعــة واملخاصمــة مــن صاحــب الصالحيــة ‪ -‬احلكــم‬\n‫بإلــزام املدعــى عليــه بدفــع قيمــة القطــع املســروقة الــواردة يف معاملــة‬\n                                 ‫االدعــاء العــام ‪ -‬رد الدعــوى يف غيــر ذلــك‪.‬‬\n\n\n\n\n                                    ‫املادة (‪ )6/47‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n‫ادعــت اجلهــة املدعيــة وميثلهــا املفــوض بالترافــع عنهــا بــأن املدعــى عليــه‬\n‫قــام بســرقة عــدد مــن القواطــع الكهربائيــة؛ وطلبــت إلزامــه بتســليمها‬\n‫قيمــة املســروقات ‪ -‬أقــر املدعــى عليــه بســرقة القواطــع الكهربائيــة إال‬\n‫أنــه أنكــر مقــدار املســروقات املذكــورة يف الدعــوى كمــا دفــع بأنهــا‬\n‫تالفــة فظــن بأنــه ال حاجــة لهــا ‪ -‬املدعيــة قدمــت بينــات غيــر موصلــة‬\n‫فيمــا يتعلــق مبقــدار املســروقات‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه‬\n\n                                                                                        ‫‪182‬‬\n\f      ‫بتســليم املدعيــة قيمــة املســروقات التــي أقــر بهــا كمــا قضــت بــرد دعوى‬\n      ‫املدعيــة فيمــا زاد علــى ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم وعارضــت‬\n      ‫عليــه املدعيــة ‪ -‬قــررت محكمــة االســتئناف باألكثريــة املوافقــة علــى‬\n                                                                          ‫احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامة مبكة‬\n      ‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة الرئيــس برقــم‬\n      ‫‪ 33544297‬وتاريــخ ‪1433/08/25‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 331498271‬وتاريــخ ‪ 1433/08/10‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n      ‫‪1433/08/28‬ه ـ افتتحــت اجللســة يف متــام الســاعة التاســعة صباح ـ ًا‬\n      ‫ا‬ ‫وفيهــا حضــر ســعودي بالســجل املدنــي رقــم ‪ ...‬حــال كونــه وكي ـ ً‬\n      ‫مبوجــب خطــاب تفويــض مــن مشــرف قصــور رقــم ‪/582‬ق ص‪/‬م وتاريــخ‬\n      ‫ا ضــد احلاضــر معــه يف مجلــس احلكــم‬      ‫‪1433/08/11‬ه ـ وادعــى قائ ـ ً‬\n      ‫ا يف تقريــر دعــواه ضــده ‪ :‬إن املدعــى‬ ‫ســعودي بالســجل املدنــي ‪ ...‬قائ ـ ً‬\n      ‫عليــه قــام بتاريــخ ‪1432/11/14‬ه ـ بســرقة قطع نحاســية عددها (‪)393‬‬\n      ‫قطعــة وذلــك مــن قصــر مبكــة املكرمــة وذلــك بعــد قيامــه بقــص قفــل‬\n      ‫البــاب اخلارجــي ملســتودع القصــر وقــد مت تقديــر جميــع القطــع املســروقة‬\n      ‫مببلــغ وقــدره (‪ 30654‬ثالثــون ألــف وســتمائة وأربــع وخمســون ريــال) لــذا‬\n      ‫؛ أطلــب احلكــم علــى املدعــى عليــه وإلزامــه بدفع قيمة القطع النحاســية‬\n      ‫املســروقة وهــو مبلــغ وقــدره (‪ 30654‬ثالثــون ألــف وســتمائة وأربــع‬\n      ‫وخمســون ريــال) هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫بقولــه ‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه مــن ناحيــة ســرقة القطــع‬\n‫‪183‬‬\n\f‫وعددهــا املذكــور يف دعــواه كلــه غيــر صحيح والصحيح أني شــاهدت‬\n‫عــدد مــن املواســير النحاســية التالفــة بجــوار املســتودع وتولــد لــدي‬\n‫إحســاس بأنــه ليــس هنــاك حاجــة لتلــك املواســير وعليــه فقــد قمــت‬\n‫بتحميلهــا داخــل شــنطتي وعددهــا تســعة وثالثــن ماســورة نحاســية وقــد‬\n‫بعتهــا مببلــغ ثالثــة آالف وســبعمائة ريــال ‪ ،‬ومســتعد بإعــادة هــذا املبلــغ‬\n‫هكــذا أجــاب وبســؤال املدعــي وكالــة عــن بينتــه علــى دعــواه فقــال ‪:‬‬\n‫بينتــي هــي مــا يف أوراق املعاملــة املتعلقــة باحلــق العــام ‪ .‬عنــد ذلــك جــرى‬\n‫منــي االطــاع علــى املعاملــة وفيهــا القــرار الشــرعي الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 3383574‬وتاريــخ ‪1433/02/15‬ه ـ واملتضمــن ثبــوت‬\n‫إدانــة املدعــى عليــه بخيانــة األمانــة وأخــذ مــال مؤمتــن عليــه بغيــر وجــه‬\n‫حــق وتعزيــره لقــاء ذلــك بســجنه ســنة وجلــده مائــة وخمســون جلــده كمــا‬\n‫جــرى منــي الرجــوع إلــى أوراق املعاملــة فوجــد مــن بينهــا محضــر القبــض‬\n‫والتفتيــش احملــرر علــى لفــة رقــم ‪ 15‬ولفــه رقــم ‪ 16‬فوجــد أنــه يتضمــن‬\n‫القبــض علــى املدعــى عليــه نظــر ًا ملــا توفــرت مــن معلومــات تفيــد اتهامــه‬\n‫بســرقة قواطــع كهربائيــة نحاســية ولــم جنــد يف احملضــر مــا يفيــد وجود‬\n‫شــيء مــن املســروقات لديــه كمــا جــرى منــي الرجــوع إلــى أوراق املعاملــة‬\n‫ومــن بينهــا إقــرار املدعــى عليــه املــدون علــى صحيفــة ‪ 15‬مــن دفتــر‬\n‫التحقيــق لفــة رقــم ‪ 1‬وهــذا نصــه ‪ (( :‬إقــرار بتاريــخ ‪1432/11/27‬ه ـ‬\n‫أقــر أنــا املدعــو ‪ /‬ســعودي اجلنســية حامــل بطاقــة رقــم وأنــا بكامــل‬\n‫قــواي العقليــة املعتبــرة شــرع ًا وبــدون إجبــار أو اكــراه يف يــوم األربعــاء‬\n‫أو الثالثــاء ويف متــام الســاعة احلاديــة عشــر صباحـ ًا دخلــت املســتودع مــن‬\n‫بــاب الطــوارئ مــن النفــق رقــم أربعــة لكــي أقــوم بترتيــب األبجــورات‬\n‫بداخــل املســتودع بواقــع عمــل كفنــي كهربــاء وشــاهدت القواطــع‬\n\n\n                                                                                       ‫‪184‬‬\n\f      ‫النحاســية ونقلتهــا مبعرفتــي إلــى مــكان قريــب مــن بــاب الطــوارئ الذي‬\n      ‫دخلــت منــه وكنــت أتــردد يوميـ ًا ألشــاهد القواطــع هــل هــي يف مكانهــا‬\n      ‫الــذي وضعتــه بهــا وبواقــع تــرددي علــى القواطــع لــم أتوقــع أحــد اهتــم‬\n      ‫للقواطــع فأغوانــي الشــيطان فقمــت بنقلهــا بيــدي ووضعتهــا يف شــنطة‬\n      ‫الســيارة وعددهــا تســعة وثالثــن قطعــة مــن النحــاس وحملتهــا دفعــة‬\n      ‫واحــدة وعنــد خروجــي مــن القصــر لــم يقــم أحــد بتفتيشــي كمــا هــو‬\n      ‫ـاء وبعــد‬‫معتــاد وخرجــت يف متــام الســاعة الثانيــة عشــر والربــع مسـ ً‬\n      ‫خروجــي مــن القصــر شــاهدت شــخص مــن الذيــن يشــترون علــب‬\n      ‫البيبســي واملعلبــات يف مخطــط احلمــراء وال أعرفــه أبــد ًا وعرضتهــا عليــه‬\n      ‫ووافــق علــى شــرائها مقابــل ثالثــة آالف وســبعمائة ريــال وبعتهــا لــه هــذا‬\n      ‫مــا حــدث بالتفصيــل وعلــى ذلــك أقــر علم ـ ًا أن املســتودع الــذي دخلــت‬\n      ‫وســرقت القواطــع النحاســية منــه يقــع بقصــر ‪ ....‬مبكــة الــذي أعمــل‬\n      ‫فيــه فنــي كهربــاء وعليــه أوقــع املقــر مبــا فيــه بصمتــه شــهود احلــال‬\n      ‫املــازم توقيعــه)) وقــد ذيــل عليــه مبــا نصــه ‪ (( :‬احلمــد هلل وحــده وبعــد ‪:‬‬\n      ‫حضــر لــدي املدعــو وبســؤاله عــن املدعــو بالصحيفــة رقــم ‪15‬صــادق‬\n      ‫عليه حرفي ًا طائع ًا مختار ًا ولذا جرى تصديقه حرر يف ‪1432/11/28‬هـ‬\n      ‫املقــر مبــا فيــه بصمتــه رئيــس احملكمــة اجلزئيــة مبكــة املكرمــة‬\n      ‫توقيعــه )) )) وبعرضهــا علــى املدعــى عليــه أجــاب بقولــه ‪ :‬مــا جــاء يف‬\n      ‫ذلــك صحيــح وليــس فيهــا مــا يــدل علــى دعــوى املدعــي وكالــة وبســؤال‬\n      ‫املدعــي وكالــة هــل لديــه زيــادة بينة ســوى مــا يف أوراق املعاملة ؟ فأجاب‬\n      ‫بأنــي أطلــب مهلــة للبحــث وحيــث ال مانــع مــن ذلــك رفعــت اجللســة ثــم يف‬\n      ‫يــوم األربعــاء املوافــق ‪1433/09/06‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫الثانيــة ظهــر ًا وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه املنــوه عنهمــا‬\n\n\n‫‪185‬‬\n\f‫بعاليــه وبســؤال املدعــي وكالــة عمــا وعــد بــه يف اجللســة املاضيــة مــن‬\n‫احضــار البينــة فأجــاب بقولــه ‪ :‬ليــس لــدي ســوى مــا يف أوراق املعاملــة‬\n‫مــن اعتــراف املدعــى عليــه بدخــول املســتودع ‪ ،‬كمــا أن املدعــى عليــه‬\n‫ليــس لــه أيــه صالحيــة لدخــول املســتودع ‪ ،‬واعترافــه بســرقة بعــض‬\n‫القطــع دليــل علــى ســرقة باقيهــا هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــى عليــه قــال ‪ :‬الصحيــح مــا ذكرتــه ومــا أخذتــه مــن املواســير فهــي‬\n‫تالفــة وهــي مرميــة يف صناديــق النفايــات وأطالــب بإحضــار تصويــر ذلــك‬\n‫بالكاميــرات إن كانــت الدعــوى صحيحــة وبعرضــه علــى املدعــي‬\n‫أجــاب بأنــه ال صحــة ملــا ذكــره املدعــى عليــه ومــا يكــون تالف ـ ًا فإنــه‬\n‫يشــكل لــه جلنــة لتقريــر ذلــك ومن ثــم يباع عن طريــق مناقصة حكومية‬\n‫وأمــا مــا ذكــره مــن تصويــر ذلــك بالكاميــرات فإنــه ال يوجــد لدينــا‬\n‫حاليـ ًا تصويــر لذلــك هكــذا اجــاب ثــم قــرر كل منهمــا اكتفــاؤه مبــا‬\n‫قــدم وعليــه فقــد قــررت رفــع اجللســة للتأمــل ودراســة املعاملــة ثــم يف يــوم‬\n‫األربعــاء املوافــق ‪1433/09/13‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n‫الواحــدة ظهــر ًا وفيهــا حضــر ممثــل اجلهــة املدعيــة واملدعــى عليــه ‪ ...‬املنــوه‬\n‫عنهمــا بعاليــه وبســؤال املدعــى عليــه عــن عــدد القطــع التــي أخذهــا ؟‬\n‫أجــاب إنهــا تســعة وثالثــون ماســورة نحاســية‪ ،‬فبنــاء علــى مــا ســلف مــن‬\n‫الدعــوى واإلجابــة وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا القــرار‬\n‫الشــرعي رقــم ‪ 3383574‬وتاريــخ ‪1433/02/15‬ه ـ ‪ ،‬وحيــث طلبــت‬\n‫اجلهــة املدعيــة بواســطة ممثلهــا تكليــف املدعــى عليــه بدفــع قيمــة‬\n‫املســروق وعــدده (‪ )393‬قطعــة نحاســية باملبلــغ املدعــى عليــه ‪ ،‬وحيــث‬\n‫أنكــر املدعــى عليــه عــدد القطــع املســروقة وذكــر أنهــا تســع وثالثــن‬\n‫ماســورة نحاســية ‪ ،‬ولــم يقــم املدعــي بينتــه علــى دعــواه يف عــدد القطــع‬\n\n\n                                                                                          ‫‪186‬‬\n\f      ‫‪ ،‬ومــا جــاء يف القــرار الشــرعي واالقــرار املصــدق شــرع ًا ‪ ،‬ال تــدل علــى‬\n      ‫مــا ذكــره ممثــل اجلهــة املدعيــة يف دعــواه ‪ ،‬ولــم يرغــب ميــن املدعــى‬\n      ‫عليــه علــى نفــي مــا زاد عــن القطــع املقــر بهــا ‪ ،‬وحيــث أن مــا أقــر بــه‬\n      ‫املدعــى عليــه مــن عــدد القطــع وقيمتهــا يفــوق مــا قومــت بــه اجلهــة املدعيــة‬\n      ‫كل قطعــة مــن القطــع النحاســية ‪ ،‬ملــا ســبق فقــد حكمــت مبــا يلــي ‪:‬‬\n      ‫أو ًال ‪ :‬ثبــت لــدي أن بذمــة املدعــى عليــه للشــؤون اخلاصــة ل ـ ـ ‪ ....‬مبلــغ‬\n      ‫وقدره (‪ 3700‬ثالثة آالف وســبعمائة ريال ) قيمة تســع وثالثون ماســورة‬\n      ‫نحاســية أخذهــا بغيــر وجــه حــق ‪ ،‬تــودع يف اخلزينــة العــام للدولــة لصالــح‬\n      ‫الشــؤون اخلاصــة لـ ــ‪ . ....‬ثانيـ ًا ‪ -:‬رددت دعــوى اجلهــة املدعيــة ‪ ...‬يف إلــزام‬\n      ‫املدعــى عليــه مبــا زاد علــى القطــع املذكــورة ‪ ،‬لكونــه لــم يثبــت لــدي‬\n      ‫وأفهمــت ممثلهــا بــأن للجهــة املدعيــة ميــن املدعــى عليــه متــى رغبــت هــذا‬\n      ‫مــا ظهــر لــي وبــه حكمــت وبإعــان احلكــم قــرر املدعــى عليــه القناعــة‬\n      ‫وقــرر ممثــل اجلهــة املدعيــة عدمهــا وطلــب اســتئنافه بالئحــة فجــرى‬\n      ‫تســليمه نســخه مــن الصــك يف نفــس اليــوم وإفهامــه بــأن مــدة االعتــراض‬\n      ‫ثالثــون يومـ ًا اعتبــار ًا مــن تاريــخ هــذا اليــوم وبأنــه إذا لــم يتقــدم بالئحــة‬\n      ‫اعتراضيــة خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم‬\n      ‫القطعيــة ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد آلــه وســلم حــرر‬\n      ‫يف ‪1433/09/13‬ه ـ احلمــد هلل وحــده والصــاة والســام علــى مــن ال‬\n      ‫نبــي بعــده وبعــد ‪ :‬ففــي هــذا اليــوم األحــد املوافــق ‪1434/03/29‬ه ـ‬\n      ‫افتتحــت اجللســة وكان قــد وردتنــا املعاملــة مــن محكمــة االســتئناف‬\n      ‫برقــم ‪ 331873432‬يف ‪1433/11/15‬ه ـ واملالحــظ عليها بقرار الدائرة‬\n      ‫اجلزائيــة األولــى رقــم ‪ 33447901‬يف ‪1433/11/08‬ه ـ ونــص احلاجــة‬\n      ‫منــه ‪ (( :‬وبدراســة احلكــم وصــورة ضبطــه قررنــا إعادتهــا لفضيلــة‬\n\n\n‫‪187‬‬\n\f‫حاكــم القضيــة ملالحظــة انــه ال توجــد وكالــة مــن اجلهــة املختصــة وإمنــا‬\n‫ملوجــود تفويــض يف املراجعــة وليــس يف الدعــوى واملرافعــة وال بــد مــن‬\n‫ذلــك ‪ .‬إلجــراء مــا يلــزم نحــو مــا أشــير إليــه )) ‪ ،‬وعليــه أجيــب أصحــاب‬\n‫الفضيلــة بأنــه كمــا نــوه يف ضبطــه فــإن اجلهــة املختصــة قــد فوضــت ‪/‬‬\n‫يف املطالبــة واملدافعــة واملرافعــة وقبــول احلكــم واالعتــراض عليــه ‪..‬الــخ‬\n‫مبوجــب خطابهــم رقــم ‪ /582‬ق ص ‪ /‬م يف ‪1433/08/11‬ه ـ املرفــق‬\n‫باملعاملــة ‪ ،‬وحيــث جــرى إكمــال الــازم فقــد قــررت رفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق حــرر يف‬\n‫‪1434/03/29‬ه ـ ‪.‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الثالثــاء‬\n‫املوافــق ‪1434/05/07‬ه ـ افتتحــت اجللســة يف متــام الســاعة الثامنــة‬\n‫صباح ـ ًا ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫رقــم ‪ 332028985‬وتاريــخ ‪1434/04/27‬ه ـ واملرفــق بهــا القــرار رقــم‬\n‫‪ 34189158‬وتاريــخ ‪1434/04/16‬ه ـ ونصــه « وبدراســة مــا أجــاب بــه‬\n‫فضيلتــه غيــر مقنــع وعليــه الرجــوع إلــى قرارنــا رقــم ‪ 33447901‬وتاريــخ‬\n‫‪1433/11/08‬ه ـ وإجــراء مــا يلــزم واهلل املوفــق « أ‪.‬ه ـ وعليــه أجيــب‬\n‫أصحــاب الفضيلــة ‪ -‬وفقهــم اهلل وأيدهــم ‪ ،‬بأنــه هــذه الدعــوى مقامــة‬\n‫مــن جهــة حكوميــة هــي ‪ ، ...‬واملدعــي احلاضــر هــو مفــوض مــن قبــل‬\n‫صاحــب الصالحيــة باخلطــاب املوجــه للمحكمــة برقــم ‪/582‬ق ص‪/‬م‬\n‫يف ‪1433/08/11‬ه ـ املرفــق باملعاملــة لفــة رقــم (‪ )26‬وقــد جــاء فيــه مــا‬\n‫نصــه ‪ (( :‬ولــه احلــق يف املطالبــة واملخاصمــة واملدافعــة واملرافعــة وإحضار‬\n‫البينــات والــرد عليهــا وقبــول احلكــم واالعتــراض عليــه والتوقيــع فيمــا‬\n‫ذكــر )) ‪ ،‬وحيــث أن هــذا التفويــض كافي ـ ًا يف مثــل هــذه احلالــة وال‬\n‫حاجــة إلصــدار وكالــة فقــد نصــت املــادة (‪ )6/47‬مــن نظــام املرافعــات‬\n\n\n                                                                                    ‫‪188‬‬\n\f      ‫الشــرعية علــى أن ‪ (( :‬ممثلــوا اجلهــات احلكوميــة يكتفــى بتفويضهــم‬\n      ‫بخطــاب رســمي مــن صاحــب الصالحيــة إلــى احملكمــة التــي تقــام لديها‬\n      ‫الدعــوى )) ‪ ،‬فلمــا ســبق فإنــه لــم يظهــر لــي ســوى مــا أجريتــه وقــررت‬\n      ‫إحلاقــه لصكــه وســجله ومــن ثــم إعادتهــا ألصحــاب الفضيلــة قضــاة‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة إلكمــال الزمهــا ‪ ،‬أعانهــم اهلل‬\n      ‫ووفقهــم ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n      ‫أجمعــن حــرر يف ‪1434/05/07‬ه ـ ‪.‬احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم األحــد املوافــق ‪1434/07/09‬ه ـ افتتحــت اجللســة يف متــام الســاعة‬\n      ‫الثانيــة عشــر ظهــر ًا ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة‬\n      ‫برقــم ‪ 332028985‬وتاريــخ ‪1434/06/14‬ه ـ املقيــدة بهــذه احملكمــة‬\n      ‫برقــم ‪ 332028985‬وتاريــخ ‪1434/06/16‬ه ـ واملرفــق بهــا القــرار رقــم‬\n      ‫‪ 34227224‬وتاريــخ ‪1434/05/29‬ه ـ ونصــه « وبدراســة مــا أجــاب بــه‬\n      ‫فضيلتــه وجــد غيــر مقنــع واملــادة التــي استشــهد بهــا خاصــة باهــل‬\n      ‫الصفــات االعتباريــة كرؤســاء ومــدراء الدوائــر احلكوميــة ‪ ،‬فعلــى‬\n      ‫فضيلتــه الرجــوع إلــى قرارنــا الســابق وإجــراء مقتضــاه واهلل املوفــق «أ‪.‬ه ـ‬\n      ‫وعليــه أجيــب أصحــاب الفضيلــة ‪-‬وفقهــم اهلل‪ :-‬بــأن صاحــب احلــق‬\n      ‫اخلــاص هــو جهــة حكوميــة ‪ ،‬واملــال املســروق هــو مــن أمــوال الدولــة ‪،‬‬\n      ‫وقــد ســبق أن كاتبــت املشــرف علــى مكتــب االدعــاء بهــذه احملكمــة‬\n      ‫بكتابــي رقــم ‪ 33257001‬يف ‪1433/02/14‬ه ـ إبــان نظــر الدعــوى‬\n      ‫العامــة مستفســر ًا عــن ملكيــة املــال املســروق ‪ ،‬فوردتنــي إفادتــه‬\n      ‫بكتابــه ذا الرقــم ه م ‪/2/‬ب‪ 167/‬يف ‪1433/02/15‬ه ـ ‪ ،‬املرفــق‬\n      ‫بالطــرد املرفــق باملعاملــة لفــة رقــم (‪ )74‬وبرفقــه كتــاب املشــرف علــى‬\n      ‫قصــور ‪ ...‬املــؤرخ يف ‪1433/02/14‬ه ـ املرفــق بالطــرد املرفــق باملعاملــة‬\n\n\n‫‪189‬‬\n\f‫لفــة رقــم (‪ )73‬واملتضمنــة جميع ـ ًا أن ملكيــة املواســير النحاســية‬\n‫املذكــورة يف الدعــوى ‪ ،‬تعــود إلــى أمــاك الدولــة ( وزارة املاليــة ) وأن‬\n‫مــا يبــاع منهــا يــودع قيمتــه بــوزارة املاليــة ‪ ،‬وعليــه فــا حاجــة حينئــذ‬\n‫إلصــدار وكالــة ‪ ،‬بــل يكتفــى بالتفويــض حســب التعليمــات والتــي‬\n‫ســبق إيرادهــا بعاليــه ‪ ،‬لذلــك فإنــه لــم يظهــر لــي ســوى مــا أجريــت‬\n‫وقــررت إعــادة املعاملــة حملكمــة االســتئناف لتدقيقهــا كاملتبــع وإعمال‬\n‫مقتضــى املــادة (‪ )188‬مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/07/09‬هــ‪ .‬احلمــد‬\n‫هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق ‪1434/09/08‬ه ـ عــادت‬\n‫املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة برقــم ‪332028985‬‬\n‫وتاريــخ ‪1434/08/22‬ه ـ واملقيــدة بأســاس هــذه احملكمــة رقــم‬\n‫‪ 332028985‬وتاريــخ ‪1434/08/29‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف رقــم ‪34290573‬‬\n‫وتاريــخ ‪1434/08/07‬ه ـ واملــدون علــى ظهــر الصك املتضمن (وبدراســة‬\n‫احلكــم وصــورة ضبطــه قررنــا باألكثريــة املوافقــة علــى احلكــم) لــذا‬\n‫جــرى حتريــر ذلــك وإحلاقــه حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل‬\n                   ‫على نبينا محمد وآله وسلم حرر يف ‪1434/09/08‬هـ ‪.‬‬\n\n\n\n\n                                                                                     ‫‪190‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":182,"source_page_end":190,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8cbc51a031c6aea0b23b63093ae4d304a60b7e21ca4cf61dab23c29c4180fa56","normalized_text_hash":"e7ad3e79a4d1ffeefda3d08433cd9be75f0634d65bf2e5179331093844a85b99","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p182-33411618"},{"id":"c4bd8b2b-c179-54cd-8ff6-da6a0df48033","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مغصوب -زوجة تدعي على زوجها رد مبلغ مالي مت االستيالء عليه من حساب مصريف -غياب املدعى عليه رغم تبليغه -اليمن تشرع يف جانب أقوى املتداعين -البينة :كشف احلساب وحلف اليمن -ثبوت الدعوى -حكم حضوري -التماس إعادة النظر -رفض االلتماس بعد النظر يف موضوعه.","document_number":"33442131","case_number":"33546412","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/29","year":"1434","subject":"مطالبة برد مغصوب -زوجة تدعي على زوجها رد مبلغ مالي مت االستيالء عليه من حساب مصريف -غياب املدعى عليه رغم تبليغه -اليمن تشرع يف جانب أقوى املتداعين -البينة :كشف احلساب وحلف اليمن -ثبوت الدعوى -حكم حضوري -التماس إعادة النظر -رفض االلتماس بعد النظر يف موضوعه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/29 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33442131 :‬‬\n                          ‫َر ْق ُم الدعوى‪33546412 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3417357‬تاريخه‪1434/1/20:‬هـ‬\n\n\n       ‫مطالبــة بــرد مغصــوب ‪ -‬زوجــة تدعــي علــى زوجهــا رد مبلــغ مالــي مت‬\n       ‫االســتيالء عليــه مــن حســاب مصــريف ‪ -‬غيــاب املدعــى عليــه رغــم تبليغــه‬\n       ‫‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن ‪ -‬البينــة‪ :‬كشــف احلســاب‬\n       ‫وحلــف اليمــن ‪ -‬ثبــوت الدعــوى ‪ -‬حكــم حضــوري‪ -‬التمــاس إعــادة‬\n                             ‫النظــر‪ -‬رفــض االلتمــاس بعــد النظــر يف موضوعــه‪.‬‬\n\n\n\n\n       ‫‪ -1‬قــول ابــن القيــم رحمــه اهلل يف إعــام املوقعــن (‪( :)101/1‬والــذي‬\n       ‫جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعيــن ‪..‬إلخ)‪.‬‬\n       ‫‪ -2‬مــا قــرره جمــع مــن أهــل العلــم مــن القضــاء علــى الغائب املســتتر وإن‬\n       ‫لــم يكــن مــع املدعــى بينــة حتــى ال يكــون االمتنــاع طريقـ ًا إلــى إســقاط‬\n       ‫احلقــوق التــي نصــب القاضــي حلفظهــا‪ .‬انظــر أدب القاضــي للمــاوردي‬\n                                                                             ‫(‪.)323/2‬‬\n                                        ‫‪ -3‬األصل امتالك اإلنسان ما يف حوزته‪.‬‬\n       ‫‪ -4‬املــواد (‪ )1/55‬و(‪ )3/195‬مــن الالئحــة التنفيذيــة لنظــام املرافعــات‬\n                                                                          ‫الشــرعية ‪.‬‬\n\n\n\n       ‫ادعــت املدعيــة بــأن املدعــى عليــه زوجهــا وقــد قــام بتحويل وســحب مبالغ‬\n       ‫ماليــة مفصلــة يف دعواهــا مــن حســابها اخلــاص إلــى حســابه اخلــاص بعــد‬\n‫‪191‬‬\n\f‫أن قــام بحبســها يف بيتــه وأخــذ بطاقــة الصــراف اآللــي اخلاصــة بها منها‪،‬‬\n‫ولــذا فقــد طلبــت احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n‫إليهــا‪ -‬املدعــى عليــه لــم يحضــر مــع تبلغــه مبوعــد اجللســة لــذا فقــد‬\n‫قــررت احملكمــة مواصلــة الســير يف الدعــوى بغيابــه وطلبت مــن املدعية‬\n‫تقــدمي بينتهــا فذكــرت أن بينتهــا هــي كشــف احلســاب لــدى املصــرف‬\n‫وباالطــاع عليــه وجدتــه احملكمــة يتضمــن حتويــات وســحوبات ماليــة‬\n‫مطابقــة لدعــوى املدعيــة‪ -‬املدعيــة تقــوى جانبهــا مبــا قدمتــه مــن بينــة‬\n‫مــع تغيــب املدعــى عليــه عــن اجللســة مــع تبلغــه باحلضــور لــذا فقــد وجهــت‬\n‫احملكمــة لهــا اليمــن املكملــة لبينتهــا فأدتهــا طبــق مــا طلــب منهــا‪-‬‬\n‫قضــت احملكمــة حضوري ـ ًا بإلــزام املدعــى عليــه بــأن يدفــع للمدعيــة‬\n‫املبلــغ املدعــى بــه‪ -‬قنعــت املدعيــة باحلكــم‪ -‬تقــدم املدعى عليــه بالتماس‬\n‫ال وأحالتــه للمحكمــة‬     ‫إعــادة نظــر فقبلتــه محكمــة االســتئناف شــك ً‬\n‫االبتدائيــة للنظــر يف موضوعــه‪ -‬مبواجهــة املدعــى عليــه بالدعــوى أقــر‬\n‫بالتحويــات والســحوبات املاليــة مــن حســاب املدعيــة ودفــع بــأن تلــك‬\n‫األمــوال هــي يف األصــل لــه وقــد أخذتهــا املدعيــة منــه بغيــر حــق فقــام‬\n‫باســتردادها منهــا‪ -‬طلبــت احملكمــة مــن املدعــى عليــه تقــدمي بينــة علــى‬\n‫مــا دفــع بــه فقــدم بينــات غيــر موصلــة ولــم يقبــل ميــن املدعيــة علــى نفــي‬\n‫ذلــك الدفــع‪ -‬قضــت احملكمــة برفــض االلتمــاس موضوعــا وأفهمــت‬\n‫املدعــى عليــه بــأن لــه ميــن املدعيــة متــى مــا طلبهــا‪ -‬اعتــرض املدعــى‬\n‫عليــه علــى احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‬\n\n\n\n\n                                                                                        ‫‪192‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بينبــع املســاعد برقــم ‪ 33546412‬وتاريــخ ‪1433/08/25‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331601376‬وتاريــخ ‪1433/08/25‬ه ـ‬\n      ‫ففــي يــوم األحــد املوافــق‪ 143/09/10‬ه ـ افتتحــت اجللســة الســاعة ‪45‬‬\n      ‫‪ 12 :‬وفيهــا حضــرت (‪ ).....‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم(‪ ).....‬واملعــرف بهــا مــن قبــل أخيهــا (‪ ).....‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬وادعــت علــى الغائــب عــن مجلــس احلكــم‬\n      ‫الشــرعي قائلــة يف دعواهــا إن املدعــى عليــه الغائــب عــن املجلــس‬\n      ‫الشــرعي زوجــي قــد قــام بحبســي يف بيتــه مــن تاريــخ ‪1432/08/20‬ه ـ‬\n      ‫حتــى تاريخ‪1432/09/10‬ه ـ وأخــذ منــي بطاقــة الصــراف اآللــي‬\n      ‫اخلاصــة بــي وقــام بتحويــل مبلــغ وقــدره (‪ )200,000‬مائتــا ألــف ريــال‬\n      ‫مــن حســابي اخلــاص يف (‪ ).....‬حلســابه اخلــاص يف (‪ ).....‬وأيض ـ ًا قــام‬\n      ‫بســحب مبلــغ نقــدي قــدره (‪ )50,000‬خمســون ألــف ريــال أطلــب احلكــم‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه وقــدره (‪ )250,000‬مائتــان‬\n      ‫وخمســون ألــف ريــال هــذه دعــواي وقــد ســبق أن تبلــغ املدعــى عليــه‬\n      ‫مبوعــد اجللســة يــوم األحــد املوافــق ‪1433/09/10‬ه ـ الســاعة العاشــرة‬\n      ‫حســب منــوذج التبليــغ املرفــق باملعاملــة ولــم يحضــر وملــا ســبق واســتناد ًا‬\n      ‫علــى الفقــرة (‪ )1‬مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية والئحتهــا التنفيذيــة ونصهــا (إذا تبلــغ املدعــى عليــه لشــخصه‬\n      ‫أو وكيلــه الشــرعي يف القضيــة نفســها مبوعــد اجللســة أو أودع هــو أو‬\n\n‫‪193‬‬\n\f‫وكيلــه مذكــرة بدفاعــه للمحكمــة قبــل اجللســة فيعــد احلكــم يف‬\n‫حقــه حضوريـ ًا ســواء أكان غيابــه قبــل قفــل بــاب املرافعــة أم بعده)‪.‬أ‪.‬ه ـ‬\n‫فلــذا قــررت الســير يف القضيــة فســألت املدعيــة هــل لديهــا بينــة علــى‬\n‫ذلــك فقالــت نعــم لــدي كشــف حســاب لــدى املصــرف وقــد راجعتهــم‬\n‫لطلبــه فرفضــوا حتــى أحضــر بطاقــة العائلــة وهــي ليســت معــي وإمنــا مــع‬\n‫زوجــي وليــس لــي عالقــة بــه اآلن وغيــر متواصــل معــي هكــذا أجابــت‬\n‫وألجــل الكتابــة ملصــرف (‪ ).....‬لتزويدنــا بكشــف حســاب للمدعيــة‬\n‫ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهــا مــن أخيهــا (‪).....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وقــد ســبق الكتابــة‬\n‫ملصــرف (‪ ).....‬بخطابنــا ذي الرقــم(‪ ).....‬وتاريــخ ‪1433/09/13‬ه ـ بشــأن‬\n‫تزويدنــا بكشــف حســاب للمدعيــة خــال الفتــرة مــن ‪1432/8/18‬ه ـ‬\n‫إلــى ‪1432/09/10‬ه ـ وكذلــك إفادتنــا بالعمليــات املتعلقــة بحســاب‬\n‫املدعــى عليــه ولــم يردنــي منهــم أي إفــادة وقــد أبــرزت املدعيــة كشــف‬\n‫حســاب صــادر مــن مصــرف (‪ ).....‬فــرع (‪ ).....‬وباالطــاع عليــه تضمــن‬\n‫مــا يلــي حتويــل مــن حســاب املدعيــة إلــى حســاب املدعــى عليــه بتاريــخ‬\n‫‪1432/08/24‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬عشــرون ألــف ريــال‬\n‫وتاريــخ ‪1432/08/25‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون‬\n‫ألــف ريــال وتاريــخ ‪1432/08/26‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬‬\n‫عشــرون ألــف ريــال وتاريــخ ‪1432/08/27‬ه ـ مت حتويــل مبلــغ وقــدره‬\n‫(‪ )20,000‬عشــرون ألــف ريــال وتاريــخ ‪1432/08/28‬ه ـ مت حتويــل مبلــغ‬\n‫وقدره (‪ )20,000‬عشرون ألف ريال وتاريخ ‪1432/08/29‬هـ مت حتويل‬\n‫مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال وتاريخ‪1432/08/30‬ه ـ‬\n‫مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال تاريــخ‬\n\n\n                                                                                  ‫‪194‬‬\n\f      ‫‪1432/09/01‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون ألــف ريــال‬\n      ‫وتاريــخ ‪1432/09/02‬ه ـ مت حتويــل مبلــغ وقــدره (‪ )20,000‬عشــرون‬\n      ‫ألــف ريــال وتاريــخ ‪1432/09/03‬ه ـ مت حتويــل مبلــغ وقــدره (‪)20,000‬‬\n      ‫عشــرون ألــف ريــال فيكــون مجمــوع مــا مت حتويلــه مــن حســاب املدعيــة‬\n      ‫حلســاب املدعــى عليــه مبلــغ وقــدره (‪ )200,000‬مئتــا ألــف ريــال ثــم أنــه‬\n      ‫مــن تاريــخ ‪1432/08/24‬ه ـ إلــى تاريــخ ‪1432/09/03‬ه ـ مت ســحب‬\n      ‫مبلــغ وقــدره (‪ )50,000‬خمســون ألــف ريــال وتفصيلــه كالتالــي بتاريــخ‬\n      ‫‪1432/08/24‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال‬\n      ‫وبتاريــخ ‪1432/08/25‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف‬\n      ‫ريــال وبتاريــخ ‪1432/08/26‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة‬\n      ‫آالف ريــال وبتاريــخ ‪1432/08/28‬ه ـ مت ســحب مبلــغ وقــدره (‪)5,000‬‬\n      ‫خمســة آالف ريــال وبتاريــخ ‪1432/08/29‬ه ـ مت ســحب مبلــغ وقــدره‬\n      ‫(‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/08/30‬ه ـ مت ســحب مبلــغ‬\n      ‫وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/09/01‬ه ـ مت ســحب‬\n      ‫مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ ‪1432/09/02‬ه ـ‬\n      ‫مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال وبتاريــخ‬\n      ‫‪1432/09/03‬ه ـ مت ســحب مبلــغ وقــدره (‪ )5,000‬خمســة آالف ريــال‬\n      ‫ثــم جــرى منــي ســؤال املدعيــة هــل لديهــا زيــادة بينــه علــى مــا ذكرتــه‬\n      ‫فأجابــت بقولهــا ليــس لــدي ســوى مــا ذكرتــه ومبــا أن املدعــى عليــه قــد‬\n      ‫تغيــب عــن اجللســة مــع تبلغــه باحلضــور إضافــة إلــى البينــة التــي قدمتهــا‬\n      ‫املدعيــة يرجــح قــوة جانبهــا لــذا فقــد أفهمتهــا بــأن اليمــن متوجهــة عليهــا‬\n      ‫يف إثبــات صحــة دعواهــا وعــدم ســداد املدعــى عليــه للمبلــغ املدعــى‬\n      ‫بــه أو بعضــه فاســتعدت باحللــف فجــرى منــي تخويفهــا مبغبــة اليمــن‬\n\n\n‫‪195‬‬\n\f‫الكاذبــة ففهمــت ذلــك وحلفــت قائل ـ ًة‪( :‬واهلل العظيــم الــذي ال إلــه إال‬\n‫هــو أن املدعــى عليــه قــد قــام بأخــذ بطاقــة الصــراف اآللــي اخلــاص بــي‬\n‫واختلــس مــن حســاباتي مبلغ ـ ًا وقــدره (‪ )250,000‬مائتــان وخمســون‬\n‫ألــف ريــال مــن غيــر علمــي وال موافقتــي أقســم بــاهلل علــى ذلــك) هكــذا‬\n‫حلفــت فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة ومبــا أن املدعــى عليــه‬\n‫قــد تبلــغ لشــخصه نظام ـ ًا مبوعــد اجللســة ولــم يحضــر ونظــر ًا ملــا ورد‬\n‫يف الالئحــة األولــى مــن املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n‫الشــرعية والئحتهــا التنفيذيــة ومبــا أن بينــة املدعيــة بينــة غيــر موصلــة‬\n‫إال أن غيــاب املدعــى عليــه عــن املجلــس الشــرعي مــع تبلغــه لشــخصه‬\n‫يرجــح قــوة جانــب املدعيــة واليمــن تتوجــه علــى أقــوى املتداعــن ولهــذا‬\n‫قــال ابــن القيــم رحمــه اهلل يف إعــام املوقعــن ‪ 101/1‬مــا نصــه (والــذي‬\n‫جــاءت بــه الشــريعة أن اليمــن تشــرع مــن جهــة أقــوى املتداعيــن فــأي‬\n‫اخلصمــن ترجــح جانبــه جعلــت اليمــن مــن جهتــه وهــذا مذهــب اجلمهــور‬\n‫كأهــل املدينــة وفقهــاء احلديــث كاإلمــام أحمــد والشــافعي ومالــك‬\n‫وغيرهــم) ونظــر ًا ملــا قــرره جمــع مــن أهــل العلــم مــن القضــاء علــى الغائــب‬\n‫املســتتر وإن لــم يكــن مــع املدعــى بينــة حتــى ال يكــون االمتنــاع طريقـ ًا‬\n‫إلــى إســقاط احلقــوق التــي نصــب القاضــي حلفظهــا انظــر أدب القاضــي‬\n‫للمــاوردي ( ‪ )323/2‬ومبــا أن املدعيــة حلفــت اليمــن املطلوبــة منها كما‬\n‫ـدي صحــة دعــوى املدعيــة وحكمــت‬        ‫هــو مفصــل أعــاه لــذا فقــد ثبــت لـ َّ‬\n‫علــى املدعــى عليــه حكمـ ًا حضوريـ ًا بــأن يدفــع للمدعيــة املبلــغ املدعــى‬\n‫بــه وقــدره (‪ )250,000‬مائتــان وخمســون ألــف ريــال والغائــب علــى حجتــه‬\n‫متــى حضــر ‪ ،‬وبعــرض احلكــم علــى املدعيــة قنعــت بــه وقــررت إكمــال‬\n‫مــا يلــزم حيــال إبــاغ املدعــى عليــه الغائــب باحلكــم حســب التعليمــات‬\n\n\n                                                                                         ‫‪196‬‬\n\f      ‫‪ ،‬ثــم رفــع كامــل املعاملــة حــال االقتضــاء إلــى محكمــة االســتئناف‬\n      ‫لدراســة احلكــم وتدقيقــه حســب املتبــع ‪ ،‬وبــاهلل التوفيــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1433/10/24‬ه ـ‬\n                                                        ‫الســاعة العاشــرة والنصــف ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد وردنــا خطــاب رئيــس محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف رقــم ‪341184568‬‬\n      ‫وتاريخ‪1434/06/10‬ه ـ وبرفقــه قــرار الدائــرة اجلزائيــة اخلامســة‬\n      ‫رقــم‪ 34225202‬وتاريخ‪1434/05/28‬ه ـ املتضمــن (احلمــد هلل وحــده‬\n      ‫والصــاة والســام علــى مــن ال نبـ ّـي بعــده‪ ،‬وبعــد‪ :‬فقــد جــرى منــا نحــن‬\n      ‫قضــاة الدائــرة اجلزائيــة اخلامســة االطــاع علــى إحالــة ســماحة رئيــس‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة رقــم ‪34223369‬‬\n      ‫وتاريخ‪1434/05/14‬ه ـ املشــفوع بهــا صحيفــة االلتمــاس املقدمــة مــن‬\n      ‫(‪ ).....‬املقيــدة برقــم ‪ 341184568‬وتاريــخ ‪1434/05/14‬ه ـ املتضمنــة‬\n      ‫التمــاس املذكــور إعــادة النظــر يف احلكــم الصــادر مــن فضيلــة‬\n      ‫الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة بينبــع برقــم‪33442131‬‬\n      ‫وتاريخ‪1433/10/29‬ه ـ املصــدق مــن محكمــة االســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة برقــم ‪ 3417357‬وتاريخ‪1434/01/20‬ه ـ وبدراســة‬\n      ‫ـاء علــى االلتمــاس املقــدم مــن (‪ ).....‬بشــأن احلكــم رقــم‬   ‫املعاملــة وبنـ ً‬\n      ‫‪ 33442131‬وتاريخ‪1433/10/29‬ه ـ واحملكــوم فيــه عليــه غيابي ـ ًا‬\n      ‫وحيــث تقــدم وبطلــب ســماع رده لــذا حتــال لفضيلتــه احلاكــم لســماع‬\n      ‫رده علــى الدعــوى ومــن ثــم إجــراء الــازم وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه قاضي‬\n      ‫اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة (‪ ).....‬ختمــه وتوقيعــه)‬\n\n\n‫‪197‬‬\n\f‫ا‪.‬ه ـ عليــه ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/06/27‬ه ـ افتتحــت‬\n‫اجللســة الســاعة الواحــدة والنصــف وفيهــا حضــر (‪ ).....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم (‪ ).....‬وبســؤاله عــن دعــوى املدعيــة أجــاب‬\n‫ا مــا ذكرتــه املدعيــة مــن قيامــي بتحويــل مبلــغ وقــدره (‪)200,000‬‬     ‫قائـ ً‬\n‫مائتــا ألــف ريــال مــن حســابها إلــى حســابي يف مصــرف (‪ ).....‬وقيامــي‬\n‫بســحب مبلــغ نقــدي قــدره(‪ )50,000‬خمســون ألــف ريــال مــن حســابها‬\n‫عبــر الصــراف اآللــي فصحيــح ولكــن بالنســبة ملبلــغ التحويــل فــإن‬\n‫املدعيــة قــد قامــت قبــل حوالــي ســنة ونصــف بالدخــول إلــى حســابي عــن‬\n‫طريــق االنترنــت نظــر ًا لكونهــا تعــرف الرقــم الســري حلســابي وقامــت‬\n‫بتحويــل مبلــغ وقــدره (‪ )100,000‬مائــة ألــف ريــال مــن حســابي حلســابها‬\n‫الشــخصي وبعدهــا كذلــك قامــت بنفــس العمليــة وقامــت بتحويــل مبلــغ‬\n‫وقــدره (‪ )100,000‬مائــة ألــف ريــال مــن حســابي حلســابها الشــخصي‬\n‫مبــا مجموعــه (‪ )200,000‬مائتــا ألــف ريــال ثــم تبــن لــي ذلــك فســألتها‬\n‫عــن تلــك العمليــة فأخبرتنــي أنهــا تريــد بــأن تتفاخــر بذلــك علــى أخوتهــا‬\n‫وبعدهــا بفتــرة قمــت بإجــراء التحويــل املذكــور يف دعواهــا اســترداد ًا‬\n‫للمبلــغ الــذي أخذتــه منــي بغيــر حــق وأمــا بالنســبة ملــا ذكرتــه مــن‬\n‫قيامــي بســحب مبلــغ (‪ )50,000‬خمســون ألــف ريــال نقــد ًا مــن الصــراف‬\n‫اآللــي فصحيــح بــل ســحبت أكثــر مــن ذلــك نظــر ًا ألن جميــع املبالــغ‬\n‫التــي بحســابها تعــود لــي شــخصي ًا وأنــا مــن قمــت بإيداعهــا والتحويــل‬\n‫فيهــا نظــر ًا ألننــي قمــت بإنشــاء ذلــك احلســاب لهــا مــن أجــل التســجيل‬\n‫بحافــز وبعدهــا قمــت باســتخدامه نظــر ًا لعــدم نــزول حافــز لهــا وبإذنهــا‬\n‫لــذا أطلــب إلغــاء احلكــم الصــادر علــي بدفــع تلــك املبالــغ للمدعيــة‬\n‫هكــذا أجــاب ثــم جــرى رفــع اجللســة لطلــب املدعيــة وســماع جوابهــا‬\n\n\n                                                                                     ‫‪198‬‬\n\f      ‫عــن دفــع املدعــى عليــه ويف جلســة أخــرى حضــرت املدعيــة واملعــرف‬\n      ‫بهــا مــن قبــل أخيهــا وحضــر حلضورهــا املدعــى عليــه وبعــرض إجابــة‬\n      ‫املدعــى عليــه علــى املدعيــة قــررت قائلــة مــا ذكــره املدعــى عليــه غيــر‬\n      ‫ا فأنــا ال أعــرف حســاباته وال أرقامهــا الســرية‬   ‫صحيــح جمل ـ ًة وتفصي ـ ً‬\n      ‫ولــم أدخــل عليهــا قــط ولــم أقــم بتحويــل مبلــغ (‪ )200,000‬مائتــن ألــف‬\n      ‫ريــال مــن حســابه إلــى حســابي ولــم أتقــدم علــى حافــز نظــر ًا لكونــي‬\n      ‫لــدي عمــال باســمي وأمــا مــا ذكــره مــن أن جميــع املبالــغ التــي بحســابي‬\n      ‫تعــود لــه شــخصي ًا فغيــر صحيــح وأمــا مــا ذكــره مــن أن مــن يقــوم بإيــداع‬\n      ‫املبالــغ بحســابي والتحويــل إليــه فصحيــح ذلــك أن بينــي وبينــه شــراكة‬\n      ‫وهــي عبــارة عــن اســتيراد أعشــاب مــن مصــر وكان عملــي هــو عمــل‬\n      ‫دعايــة علــى االنترنــت واســتقبال االتصــاالت وفــرز تلــك األعشــاب‬\n      ‫حــن وصولهــا وعملــه هــو القيــام باالســتيراد وكانــت الشــراكة بيننــا‬\n      ‫مناصفــة وكان يقــوم بدفــع مســتحقاتي عــن طريــق التحويــل احلســابي‬\n      ‫أو اإليــداع نهايــة كل شــهر هكــذا أجابــت وبعرضــه علــى املدعــى عليــه‬\n      ‫قــرر بقولــه مــا ذكرتــه املدعيــة غيــر صحيــح والصحيــح مــا ذكرتــه‬\n      ‫فســألت املدعــى عليــه هــل لديــه بينــة تشــهد بصحــة قيــام املدعيــة‬\n      ‫بتحويــل مبلــغ (‪ )200,000‬مائتــن ألــف ريــال علــى دفعتــن وأن املــال‬\n      ‫الــذي بحســاب املدعيــة هــو مالــه وعائــد لــه وليــس للمدعيــة منــه نصيــب‬\n      ‫فأجــاب بقولــه نعــم لديــه بينــة واطلــب مهلــة إلحضارهــا فأجبتــه لطلبــه‬\n      ‫ويف جلســة أخــرى حضــرت املدعيــة واملعــرف بهــا مــن قبــل ابــن أخيهــا‬\n      ‫(‪ ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي (‪ ).....‬وحضــر حلضورهــا‬\n      ‫املدعــى عليــه وبســؤال املدعــى عليــه هــل أحضــر بينتــه التــي اســتمهل مــن‬\n      ‫أجلهــا يف اجللســة املاضيــة فأجــاب بقولــه نعــم وأبــرز كشــف حســاب‬\n\n\n‫‪199‬‬\n\f‫صــادر مــن مصــرف (‪ ).....‬لرقــم احلســاب واملتضمــن حتويــل مــن احلســاب‬\n‫املذكــور إلــى حســاب رقــم (‪ ).....‬باســم مبلــغ وقــدره (‪ )100,000‬مائــة‬\n‫ألــف ريــال وحتويــل مــن احلســاب املذكــور إلــى حســاب رقــم باســم مبلــغ‬\n‫وقــدره (‪ )100,000‬مائــة ألــف ريــال فســألت املدعــى عليــه هــل لديــه‬\n‫زيــادة بينــة تشــهد بــأن الــذي قــام بالتحويــل هــي املدعيــة وأن املبلــغ الــذي‬\n‫بحســاب املدعيــة واملبلــغ الــذي قــام بســحبه مــن الصــراف اآللــي عائــد لــه‬\n‫وليــس للمدعيــة منــه نصيــب فأجــاب بقولــه ليــس لــدي ســوى مــا ذكرتــه‬\n‫فأفهمتــه أن لــه ميــن املدعيــة علــى نفــي مــا ادعــاه فقــال ال أطلــب ميينهــا‬\n‫فكــررت عليــه ذلــك ثــاث مــرات فرفــض ميينهــا لــذا وملــا تقــدم بيانــه‬\n‫مــن ادعــاء املدعــى عليــه بــأن املــال الــذي بحســاب املدعيــة مالــه ومبــا أن‬\n‫األصــل امتــاك اإلنســان مــا يف حوزتــه واحلســاب البنكــي يعتبــر ملــك ًا‬\n‫خاصـ ًا للشــخص وال يصــار عنــه إال ببينــة وليــس لــدى املدعــى عليــه بينــة‬\n‫موصلــة تشــهد بصحــة ادعائــه وقــد رفــض ميــن املدعيــة بنفــي مــا ادعــاه‬\n‫لــذا فــا زلــت علــى مــا حكمــت بــه ســابق ًا وأفهمــت املدعــى عليــه بــأن‬\n‫لــه ميــن املدعيــة متــى مــا طلبهــا وبعــرض احلكــم علــى املدعــى عليــه قــرر‬\n‫عــدم قناعتــه بــه وطلــب االســتئناف مســتعد ًا بتقــدمي الئحــة اعتراضيــة‬\n‫فأجبتــه لطلبــه وأفهمتــه بــأن عليــه مراجعــة احملكمــة خــال عشــرة أيــام‬\n‫الســتالم نســخة مــن الصــك ومــن ثــم تقــدمي الئحتــه االعتراضيــة خــال‬\n‫ثالثــن يومـ ًا مــن تاريــخ االســتالم ففهم ذلك وبــاهلل التوفيق ‪ ،‬وصلى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/07/03‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي باحملكمــة العامــة‬\n‫بينبــع والقائــم بعمــل املكتــب القضائــي اخلامــس مبوجــب قــرار فضيلــة‬\n‫رئيــس احملكمــة العامــة بينبــع املســاعد رقــم ‪ 341935902‬وتاريــخ‬\n\n\n                                                                                         ‫‪200‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":191,"source_page_end":200,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"167a2eb86f25de62b7614a0771d75ce4523af1f66515e42fd7d9ce4b961a82b3","normalized_text_hash":"5fa8118d1496f73fac0a9c0fcc6e446bf23c3e5340906176dfb177288f11229f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p191-33442131"},{"id":"a973a449-c57b-5de1-ad42-bbe64a390e03","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيكني -اإلقرار بالسرقة يف املعاملة اجلزائية -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -إلزام املدعى عليه بسداد املبلغ املدعى به .","document_number":"34194629","case_number":"33547446","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ببريدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/22","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق تزوير شيكني -اإلقرار بالسرقة يف املعاملة اجلزائية -عدم قبول الرجوع عن اإلقرار بحق اآلدمي -إلزام املدعى عليه بسداد املبلغ املدعى به .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/22 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34194629 :‬‬\n                          ‫َر ْق ُم الدعوى‪33547446:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34363824‬تاريخه‪1434/11/19:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق تزويــر شــيكني ‪ -‬اإلقــرار‬\n      ‫بالســرقة يف املعاملــة اجلزائيــة ‪ -‬عــدم قبــول الرجــوع عــن اإلقــرار بحــق‬\n                      ‫اآلدمــي ‪ -‬إلــزام املدعــى عليــه بســداد املبلــغ املدعــى بــه ‪.‬‬\n\n\n\n\n                                                 ‫‪ .1‬قاعدة‪ :‬اإلقرار حجة على من أقر ‪.‬‬\n                                                            ‫‪ .2‬قاعدة‪ :‬ال عذر ملن أقر ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه قــام بتزويــر توقيعــه علــى شــيكني مــن‬\n      ‫الشــيكات اخلاصــة بــه ثــم قــام بصرفهمــا لصالــح نفســه دون وجــه حــق ؛‬\n      ‫وطلــب إلزامــه بســداد قيمــة الشــيكني املذكوريــن لــه ‪ -‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى جملــة وتفصيــا ‪ -‬املدعــى عليــه لــه إقــرار مصــدق شــرعا‬\n      ‫مبــا جــاء يف الدعــوى وتؤيــده األحــكام الصــادرة ضــده للحــق العــام ‪-‬‬\n      ‫قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي قيمــة الشــيكني‬\n      ‫املزوريــن الذيــن قــام بصرفهمــا لصالــح نفســه ‪ -‬عــارض املدعــى عليــه‬\n        ‫علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫ببريــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة ببريــدة برقــم ‪ 33547446‬وتاريــخ ‪ 1433/08/26‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 331605130‬وتاريــخ ‪ 1433/08/26‬ه ـ ففــي يــوم‬\n‫االثنــن املوافــق‪ 1433/10/23‬ه ـ افتتحــت اجللســة ونظــرا لكونــه قد مت‬\n‫حتديــد موعــد لنظــر هــذه الدعــوى يف متــام الســاعة احلاديــة عشــر صباحــا‬\n‫املقامــة مــن ضـ ــد بخصــوص مطالبــة ماليــة ونظــرا لعــدم حضــور املدعــي‬\n‫وال وكيــا عنــه ولــم يقــدم لنــا عــذرا مقبــوال لــذا جــرى منــا شــطب هــذه‬\n‫الدعــوى للمــرة األولــى حســب التعليمــات املرعيــة واســتنادا إلــى املــادة‬\n‫(‪ )53‬مــن نظــام املرافعــات الشــرعية ‪ ،‬وبــاهلل التوفيــق ‪ ،‬ويف يــوم األثنــن‬\n‫املوافــق ‪1433/12/20‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعي ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬فادعــى علــى احلاضــر معــه‬\n‫ا يف تقريــر دعــواه‬  ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬قائـ ً‬\n‫عليــه إن هــذا احلاضــر املدعــى عليــه ســبق أن قــام بســرقة عــدة شــيكات‬\n‫مــن مكتبــي مــن حســابات متفرقــة وقــد صــرف شــيكني منهــا األول‬\n‫ميثــل مبلغ ـ ًا وقــدره مائــة وثمانــون ألــف ريــال واملســحوب علــى مصــرف‬\n‫‪ ...‬والثانــي ميثــل مبلغ ـ ًا وقــدره مائــة وســتون ألــف ريــال واملســحوب علــى‬\n‫البنــك ‪ ...‬وقــام بصرفهمــا وقــد أديــن بالســرقة وحكــم عليــه باحلــق العــام‬\n‫ووجــدت الشــيكات يف بيتــه محــاو ًال تطبيــق توقيعــي ‪ ،‬أطلــب احلكــم‬\n‫عليــه وإلزامــه بســداد مبلــغ هذيــن الشــيكني وقدرهــا ثالثمائــة وأربعــون‬\n‫ا‬\n‫ألــف ريــال هــذه دعــواي وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n\n                                                                                      ‫‪204‬‬\n\f      ‫مــا ذكــره املدعــي يف دعــواه غيــر صحيــح هكــذا أجــاب وحيــث أنكــر‬\n      ‫املدعــى عليــه دعــوى املدعــي طلبــت مــن املدعــي البينــة علــى دعــواه فقــال‬\n      ‫بينتــي موجــودة لــدى األدلــة اجلنائيــة وهيئــة التحقيــق واالدعــاء العــام‬\n      ‫لإلفــادة عــن ذلــك لــذا جــرى رفــع اجللســة حلــن ورود اإلجابــة ‪ ،‬ويف‬\n      ‫يــوم االثنــن املوافــق ‪ 1434/04/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫الطرفــان وقــد جــرى االطــاع علــى محضــر التحقيــق احملضــر فئــة (‬\n      ‫‪ 12‬صفحــة ‪ ) 1‬ووجــد فيــه إقــرارا منســوبا للمدعــى عليــه وهــذا نصــه‬\n      ‫(نعــم أنــا أقــر بطوعــي واختيــاري أننــي دخلــت إلــى إدارة معــرض ‪ ...‬يف‬\n      ‫طريــق املعــارض وقمــت بأخــذ مجموعــة مــن شــيكات مــن اإلدارة ثــم‬\n      ‫بعــد ذلــك قمــت بكتابــة اســمي عليهــا وتدويــن مبلــغ مائــة وثمانــن ألــف‬\n      ‫علــى أحدهمــا ومبلــغ مائــة وســتني ألــف ريــال علــى شــيك ثانــي ثــم قمــت‬\n      ‫بصرفهــا لصاحلــي بعــد التوقيــع عليهــا باملطابقــة مــع صورة شــيك أخذتها‬\n      ‫مــن نفــس املــكان وقــد احتفظــت مبــا تبقــى مــن الشــيكات يف غرفتــي‬\n      ‫يف بيــت والــدي كمــا أقــر بأنــي قمــت بأخــذ شــيكات مــن مؤسســة ‪...‬‬\n      ‫وعددهــا اثنــان صرفــت أحدهــا مببلــغ مائــة وعشــرون ألــف ريــال والثانــي‬\n      ‫(( مببلــغ مئــة وســتني )) مببلــغ ســتني ألــف ريــال كمــا أنــي فعلــت ذلــك‬\n      ‫بعــد كتابــة اســمي والتوقيــع علــى الشــيكات مبطابقــة صــورة أخذتهــا‬\n      ‫مــن نفــس املكتــب كمــا أنــي اشــتريت رافعــة مــن ‪ ...‬وســلمتهم إيصــال‬\n      ‫إيــداع شــيك مقاصــة علــى ‪ ...‬علــى حســاب لــي ليــس بــه رصيــد واســتلمت‬\n      ‫الرافعــة ولــم أســدد املبلــغ كمــا أننــي اشــتريت حراثــة مــن شــركة ‪..‬‬\n      ‫بقيمــة مئــة وثالثــن ألــف ريــال وســلمتهم إيصــال إيــداع شــيك مقاصــة‬\n      ‫علــى بنــك ‪ .......‬علــى حســاب لــي ليــس بــه رصيــد واســتلمت احلراثــة مــن‬\n      ‫الشــركة وبعتهــا بســبعني ألــف ريــال كمــا بعــت الرافعــة بأربعــن ألــف‬\n\n\n‫‪205‬‬\n\f‫ريــال كمــا أقــر جميــع مــا ضبــط يف غرفتــي مــن شــيكات عائــد لــي و‬\n‫كذلــك الدفتــر الــذي وجــد بــه تواقيــع مختلفــة وقــد جمعــت الشــيكات‬\n‫مــن أماكــن مختلفــة علمــا بأننــي أعانــي مــن مــرض نفســي منــذ أربــع‬\n‫ســنوات) كمــا وجــد فيــه‪ ( :‬س‪ /‬أنــت متهــم بســرقة شــيكات مــن إدارة‬\n‫معــرض وتدويــن أحدهمــا باســمك وتوقيعــه تزويــرا وصرفــه مببلــغ مائــة‬\n‫وثمانــن ألــف ريــال وصــرف آخــر بعــد تدوينــه لصاحلــك وتوقيــع صاحــب‬\n‫الشــيك تزويــرا مببلــغ مائــة وســتني ألــف ريــال فمــا قولــك ؟ ج‪ /‬نعــم‬\n‫صحيــح‪ .‬س‪ /‬كيــف حصلــت عليهــا؟ ج‪ /‬توقفــت عنــد صــاة املغــرب‬\n‫بالغــرب مــن مؤسســة ودخلــت املؤسســة لكــي أتوضــأ وكان مكتــب‬\n‫احملاســب مفتوحــا فدخلــت وأخــذت الشــيكات وأذكــر أن عددهــا‬\n‫عشــرة فصرفــت منهــا اثنــن وباقــي الشــيكات وضعتهــا بالبيــت‪ .‬س‪/‬‬\n‫اســتعنت للكشــف عــن احلســاب وهــل يغطــي أم ال؟ ج‪ /‬اســتعنت باملدعــو‬\n‫لكشــف حســاب ‪ ...‬وقــدم لــي خدمــة شــخصية وال عالقــة لــه باملوضــوع‬\n‫أمــا بحســابات ‪ ...‬لــم أســتطع كشــف احلســاب مــع أننــي ســألت أكثــر‬\n‫مــن واحد)‪.‬وهــذا اإلقــرار مصــدق عليــه مــن احملكمــة اجلزائيــة ببريــدة‬\n‫ونصــه‪( :‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األربعــاء املوافــق‬\n‫‪1430/11/16‬ه ـ وبعــد نهايــة الــدوام الرســمي ويف مكتبــي باحملكمــة‬\n‫اجلزئيــة ببريــدة ويف الســاعة الثانيــة ظهــرا وخمس وثالثــن دقيقة أحضر‬\n‫وجــرى تــاوة األوراق مــن الصفحــة (‪ )1‬حتــى الصفحــة (‪ )5‬علــى املقــر‬\n‫فصــادق عليهــا بطوعــه واختيــاره وهــو مــدرك للزمــان واملــكان ولــذا‬\n‫جــرى املصادقــة عليــه الســاعة الثانيــة والدقيقــة خمــس وثالثــن وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن قالــه القاضــي‬\n‫باحملكمــة اجلزئيــة ببريــدة‪ .‬املقــر مبــا فيــه توقيعــه كاتبــه الواصــل‬\n\n\n                                                                                ‫‪206‬‬\n\f      ‫توقيعــه القاضــي باحملكمــة اجلزئيــة ببريــدة ختمــه وتوقيعــه) وبعرضــه‬\n      ‫عليــه قــال مــا جــاء فيــه غيــر صحيــح كمــا وجــد علــى الصفحــة رقــم‬\n      ‫(‪ )3،2،1‬إقــرار منســوب للمدعــى عليــه وهــي عبــارة عــن وقائــع ونصهــا‪:‬‬\n      ‫(الواقعــة احلاديــة عشــرة‪ :‬قمــت بســرقة شــيكات مــن معــرض مــن‬\n      ‫معرضه ‪ ،...‬وزورت التوقيع على أحد الشــيكات‪ ،‬وكتبته مببلغ مائة‬\n      ‫وثالثــة عشــرة ألــف ريــال لصالــح معــرض بالدمــام‪ ،‬وأودعتــه يف حســابه‬\n      ‫بعــد أن اشــتريت منهــم ‪ ،...‬ثــم رجعــت إلــى وطلبــت إقالتــي مــن البيعــة‬\n      ‫فأعطانــي شــيكا باملبلــغ وكنــت يف الواقعــة منتحــا شــخصية‪.......‬‬\n      ‫الواقعــة الثانيــة عشــرة‪ :‬قمــت بأخــذ شــيك مــن معــرض وزورت توقيعــه‪،‬‬\n      ‫وكتبتــه وصرفتــه لصاحلــي‪ ،‬مببلــغ مائــة وثمانيــة وثالثــن ألــف ريــال‪.‬‬\n      ‫كمــا قمــت بأخــذ شــيك مــن معــرض ‪ ،‬ودونتــه مببلــغ وقــدره ثمانيــة‬\n      ‫وأربعــن ألــف‪ ،‬بعــد أن زورت توقيعــه‪ ،‬باســم املســتفيد‪ :‬الــذي أنتحــل‬\n      ‫شــخصيته‪ ،‬وصرفتــه نقــدا مبوجــب البطاقــة التــي أحملهــا) وبعرضهــا‬\n      ‫عليــه قــال مــا جــاء فيــه غيــر صحيــح فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n      ‫واإلجابــة واالطــاع علــى املعاملــة ومنهــا الصــك الصــادر مــن احملكمــة‬\n      ‫اجلزائيــة برقــم ‪ 2/248‬يف ‪1431/5/21‬ه ـ واملصــدق مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪/137‬ج ‪ /2‬أ يف ‪1432/2/15‬ه ـ واالطــاع‬\n      ‫علــى القــرار الصــادر مــن ديــوان املظالــم برقــم ‪1432/7/6/84‬ه ـ ومبــا‬\n      ‫أن املدعــى عليــه أقــر واإلقــرار حجــة علــى مــن أقــر وال عــذر ملــن أقــر‪،‬‬\n      ‫ملــا ســبق كلــه فقــد حكمــت علــى املدعــى عليــه وألزمتــه بســداد املبلــغ‬\n      ‫املدعــى بــه وقــدره ثالثمائــة وأربعــون ألــف ريــال للمدعــي حــاال وبعــرض‬\n      ‫احلكــم عليــه قــرر عــدم القناعــة باحلكــم وطلــب االســتئناف بالئحــة‬\n      ‫اعتراضيــة فأجيــب لطلبــه وجــرى تزويــده بنســخة مــن احلكــم لتقــدمي‬\n\n\n‫‪207‬‬\n\f‫الالئحــة االعتراضيــة وأفهــم أن لــه مــدة ثالثــن يومــا مــن تاريــخ اليــوم‬\n‫‪1434/4/22‬ه ـ بعدهــا يســقط حقــه يف االعــراض ففهــم ذلــك وبــاهلل‬\n‫الوفيــق ‪.‬وصلــى اهلل وســلم علــى نبيينــا محمــد حــرر يف ‪1434/4/22‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪ :‬ويف‬\n‫يــوم األربعــاء ‪1435/01/03‬ه ـ افتتحــت اجللســة وقــد وردتنــي املعاملــة‬\n‫مــن محكمــة االســتئناف بالقصيــم رفــق خطــاب فضيلــة رئيســها رقــم‬\n‫‪ 342293524‬يف ‪1434/11/27‬ه ـ واملقيــدة بهــذه احملكمــة برقــم‬\n‫‪ 34/2293524‬يف ‪1434/12/02‬ه ـ واملرفــق بهــا قــرار الدائــرة احلقوقية‬\n‫الثانيــة مبحكمــة االســتئناف رقــم ‪ 34363824‬يف ‪1434/11/19‬ه ـ‬\n‫املتضمــن املصادقــة علــى احلكــم الصــادر منــي برقــم ‪ 34194629‬يف‬\n‫‪1434/04/22‬ه ـ واهلل املوفــق ولــذا جــرى إثباتــه والتهميــش مبوجبــه‬\n‫علــى الضبــط وســجل الصــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                                  ‫نبيينــا محمــد حــرر يف ‪1435/01/03‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                   ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":203,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c2d095fd3b34349efccf5e2030f40105e7825d5be3d3e360ddf131f1d0a53afb","normalized_text_hash":"9dcc1f02d1cd881ee895561a84753e48485b9530b51da8912dc02253b5a4be56","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p203-34194629"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
